  ('21f3d0c592b4cd01064204132d8fa9f07d39085b591626243b05af036f64e326', 'ur', 'Entering / Leaving Home', 'گھر میں داخل ہونا اور نکلنا'),
  ('6c0c4fb2ddce4960a48bb13367dc078fbfec3c23b0a7dc2dbc1c4ce836315f8d', 'ur-roman', 'Entering / Leaving Home', 'ghar me dakhil hona aur nikalna'),
