  ('b6f3f214d19e1b0c8b0a72430f124e6d14d8e2566298989a41fb335a9ede4e60', 'ur', 'Sneezing & Yawning', 'چھینک اور جمائی'),
  ('f195c66206336ab35e5fd473e5f9553ff7f63348a2df7c9ccb19f5cf12522d4e', 'ur-roman', 'Sneezing & Yawning', 'chheenk aur jamahi'),
  ('205e7780dc7aeba8af7dcb6663a45f83aff501c28e11304e23c0c40b364a0381', 'ur', 'Clothing & Dressing', 'لباس اور پہناوا'),
  ('49a83db6faf5d6204ec0683df392f93496c9c0d7180f0fb892e980bdecdfa270', 'ur-roman', 'Clothing & Dressing', 'libaas aur pehnawa'),
  ('14964f7592fb42cf5a9dcd281ffaff50a4cb4c8e955c4b29d178061d98a46521', 'ur', 'Travel', 'سفر'),
  ('4fac5ad544e01aeba61e0b60b3cf36d08cd9cb59814c86f1e55ce20ec5b27b44', 'ur-roman', 'Travel', 'safar'),
  ('a17efba70cb0ffa2846e94e5204a21f7fa4ac2115d45ba615dd16bc79079622b', 'ur', 'Gatherings (Majlis)', 'مجلس'),
  ('e52ddb91edc453ed2dceb12f641a265b0f075559e1d7effdba426d235bc3f36a', 'ur-roman', 'Gatherings (Majlis)', 'majlis'),
  ('d2ac3be280f2c05938957e95c6c64f0d527592f80591943f3ea37869d7034d0e', 'ur', 'Parents & Elders', 'والدین اور بزرگ'),
  ('6c27c6d8aee0840d02841774c044286c25d960381b731a6e9926b73fd448cbca', 'ur-roman', 'Parents & Elders', 'walidain aur buzurg'),
  ('528f43ac6a68b8ceffe7e80e6d3c5f41030b647dd0dc399f4527db9cc065e0db', 'ur', 'Speech & the Tongue', 'گفتگو اور زبان'),
  ('648acc78ab3a6f8c35e4f2baf44e318b49dc22618d8beb7fd8c0aaf74ddf4f71', 'ur-roman', 'Speech & the Tongue', 'guftagu aur zabaan'),
  ('64bdf6b02dce5daee3f748e73f0a0919b3ea6434fff7f72bdf161dbad5272a0d', 'ur', 'Manners of eating food.', 'کھانا کھانے کے آداب۔'),
  ('50eb0b43a9c101168ea16eedc45c90a9536034cac476c58d04d55fb1984c53e0', 'ur-roman', 'Manners of eating food.', 'khana khane ke aadaab.'),
  ('3e93dd04ab6c140a46d088fcab5b8e01c8ff23ebd943393df2b6f222f4dee3c2', 'ur', 'Wash both hands before and after eating.', 'کھانے سے پہلے اور بعد میں دونوں ہاتھ دھوئیں۔'),
  ('4c6afcc51eb9d0ac711e46be9e4ec028174c1c36e9bdae7ea64ca8b230c36635', 'ur-roman', 'Wash both hands before and after eating.', 'khane se pehle aur baad me dono haath dho lein.'),
  ('8536c3797d9e84fff04e015a96bdfb8fcc6853288a07eadf42a4a9ff8ff47c66', 'ur', 'Say “Bismillah” before starting. If forgotten, say “Bismillahi awwalahu wa akhirahu”.', 'شروع کرنے سے پہلے “Bismillah” کہیں۔ اگر بھول جائیں تو “Bismillahi awwalahu wa akhirahu” کہیں۔'),
  ('319c31227dcfa0f133d45d124bb3f2a100591c11edae5cd08d3beff9c6142ee4', 'ur-roman', 'Say “Bismillah” before starting. If forgotten, say “Bismillahi awwalahu wa akhirahu”.', 'shuru karne se pehle “Bismillah” kahein. agar bhool jayein to “Bismillahi awwalahu wa akhirahu” kahein.'),
  ('406592c20388a92435f2a1906f373634e3c32323ab27b8f8b801da3a744d60c6', 'ur', 'Eat with the right hand, and eat from what is directly in front of you.', 'دائیں ہاتھ سے کھائیں، اور اپنے سامنے سے کھائیں۔'),
  ('0110d0bc5f3d261e16f212dc608406f2bb96373aef06e2c460a01dd41e2a36f5', 'ur-roman', 'Eat with the right hand, and eat from what is directly in front of you.', 'dayein haath se khayein, aur apne saamne se khayein.'),
  ('f25710165d6176647452702c41bbfe536e2b716207ea0b50c2ee740b13bad560', 'ur', 'Sit and eat; do not eat while leaning back.', 'بیٹھ کر کھائیں؛ ٹیک لگا کر نہ کھائیں۔'),
  ('23f957fa75661b408481266e9bcd0f6883b513113bd189a12effe9313c38187b', 'ur-roman', 'Sit and eat; do not eat while leaning back.', 'baith kar khayein; tek laga kar mat khayein.'),
  ('4ec128ec6a4c206cf97571b6fff05626e14a5a71bd6be401d016874bdbe81726', 'ur', 'Eat from the sides of the dish, not from the middle — blessing descends in the middle.', 'برتن کے کناروں سے کھائیں، بیچ سے نہیں — برکت بیچ میں نازل ہوتی ہے۔'),
  ('37185fd7e62a0cd0feca0c696c0a592216640023a77fa21efa795b06aea852f7', 'ur-roman', 'Eat from the sides of the dish, not from the middle — blessing descends in the middle.', 'bartan ke kinaron se khayein, beech se nahin — barkat beech me nazil hoti hai.'),
  ('7fab81307235d58774a7fb8e92e6421743b7602701b5ae6d4d3cb72542ac1273', 'ur', 'Do not find fault with food; eat it if you like it, otherwise leave it.', 'کھانے میں عیب نہ نکالیں؛ پسند ہو تو کھائیں، ورنہ چھوڑ دیں۔'),
  ('2dca320ff0145a5162d33ee288ad35e663d5ab7a32e4adbcad48927aae3d8e28', 'ur-roman', 'Do not find fault with food; eat it if you like it, otherwise leave it.', 'khane me aib mat nikalein; pasand ho to khayein, warna chhod dein.'),
  ('490d7b624c09e9371bc4ab82126321d657e06990bcdeefc8bd67734ac8e2ae65', 'ur', 'Eat with three fingers and clean the fingers and the plate when finished.', 'تین انگلیوں سے کھائیں اور فارغ ہو کر انگلیاں اور پلیٹ صاف کریں۔'),
  ('f792e908f34edfc105643091aa34d5b294545da2d70c68ccbb53de91366f999a', 'ur-roman', 'Eat with three fingers and clean the fingers and the plate when finished.', 'teen ungliyon se khayein aur khatam kar ke ungliyan aur plate saaf karein.'),
  ('12a4f61a080debac7e9c344d78cc16444f5dbc921535e15ff74faad60e819725', 'ur', 'Eat and drink in moderation; do not overfill the stomach.', 'اعتدال سے کھائیں پئیں؛ پیٹ بھر کر زیادہ نہ کھائیں۔'),
  ('81dbaee7396642011692380627bb61530ec040d3cd1edb4fa41e4b87366e0144', 'ur-roman', 'Eat and drink in moderation; do not overfill the stomach.', 'itedaal se khayein piyein; pet zaroorat se zyada mat bharein.'),
  ('d7175fa3bb2beeabb96836127beb25a81466d6626728e9eb4f81a87c4f774819', 'ur', 'Do not use gold or silver utensils.', 'سونے یا چاندی کے برتن استعمال نہ کریں۔'),
  ('26f2354a723f7a8a47e57eb10edf1f90ea8d7ca990ec8112eb88d3064b6e5cae', 'ur-roman', 'Do not use gold or silver utensils.', 'sone ya chandi ke bartan istemaal mat karein.'),
  ('4f54ba59b85796986be025464b3ab501bdb16ef4934d878eaf8348a9a065ea12', 'ur', 'Praise Allah when finished: “Alhamdulillahil-ladhi at‘amana wa saqana wa ja‘alana muslimin”.', 'فارغ ہو کر اللہ کی حمد کریں: “Alhamdulillahil-ladhi at‘amana wa saqana wa ja‘alana muslimin”۔'),
  ('9a2fde6f5c3a3e9fed46b485d745670c79262a07b3d8cb60728b862893e98355', 'ur-roman', 'Praise Allah when finished: “Alhamdulillahil-ladhi at‘amana wa saqana wa ja‘alana muslimin”.', 'khatam kar ke Allah ki hamd karein: “Alhamdulillahil-ladhi at‘amana wa saqana wa ja‘alana muslimin”.'),
  ('795552ebddaa293808cc400f7e6eec9bae1c31ee21a81e781fb20c1052e4472a', 'ur', 'If a morsel falls, pick it up, remove any dirt and eat it; do not leave it for Shaytan.', 'اگر لقمہ گر جائے تو اٹھا لیں، مٹی صاف کر کے کھا لیں؛ اسے شیطان کے لیے نہ چھوڑیں۔'),
  ('1e8df36d38cfb3403dbb5f2e923c217ded335e762a34f7cec375625a966c320f', 'ur-roman', 'If a morsel falls, pick it up, remove any dirt and eat it; do not leave it for Shaytan.', 'agar luqma gir jaye to utha lein, mitti saaf kar ke kha lein; ise shaytan ke liye mat chhodein.'),
  ('143f8dd6f6c36701a71aaae899915363c419e4749dffbb334e884fc889c32b91', 'ur', 'Do not blow on hot food or drink; wait for it to cool.', 'گرم کھانے یا پینے کی چیز پر پھونک نہ ماریں؛ ٹھنڈا ہونے کا انتظار کریں۔'),
  ('f08144d5294d018f39b2472d7609b31d967a27e012c99a08fc0728f2384ad1c5', 'ur-roman', 'Do not blow on hot food or drink; wait for it to cool.', 'garam khane ya peene par phoonk mat maarein; thanda hone ka intezaar karein.'),
  ('491eb2603553fdc872f2afe5b8d018c3a69e7130f1bdbada401127815f93b00a', 'ur', 'Eat together, not separately — there is blessing in eating in a group.', 'مل کر کھائیں، الگ الگ نہیں — مل کر کھانے میں برکت ہے۔'),
  ('7966e2d9d43e25e8d49f3734f1ffed20a2991710e4e54dba58a77f4bc7a2d70a', 'ur-roman', 'Eat together, not separately — there is blessing in eating in a group.', 'mil kar khayein, alag alag nahin — mil kar khane me barkat hai.'),
  ('12b5259ad5d67a890f5b55537f9418c2904e4f7392ee415a80c54197453ab10a', 'ur', 'The food of two suffices three, and the food of three suffices four.', 'دو کا کھانا تین کے لیے کافی ہوتا ہے، اور تین کا کھانا چار کے لیے۔'),
  ('32945f6d5b00621a0a6ccd828f66df4a5b3b77a1ddf628bb0792f7d2c73a0b60', 'ur-roman', 'The food of two suffices three, and the food of three suffices four.', 'do ka khana teen ke liye kaafi hai, aur teen ka khana chaar ke liye.'),
  ('fe18164b88c6da0c74f3fe11e12e0bbdf770f3da2da36e100e95d3fc08820d29', 'ur', 'Lick the fingers and wipe the plate clean; you do not know in which part the blessing lies.', 'انگلیاں چاٹ لیں اور پلیٹ صاف کر لیں؛ آپ نہیں جانتے کس حصے میں برکت ہے۔'),
  ('db26606283a3f7416a987e0a6dfef425fbcf1d73299b3194ebb368a3121e4077', 'ur-roman', 'Lick the fingers and wipe the plate clean; you do not know in which part the blessing lies.', 'ungliyan chaat lein aur plate saaf kar lein; aap nahin jaante kis hisse me barkat hai.'),
  ('d4da738577400f09b71be4c1ded4ea852ab7ea0cddbb46f633f554c3137f6118', 'ur', 'Do not waste food; honour it and give any surplus to others.', 'کھانا ضائع نہ کریں؛ اس کی قدر کریں اور جو بچے وہ دوسروں کو دے دیں۔'),
  ('14f6ff41ee8bc5b50ce67b51fde552be456e8ce03af04099fc073f1608ba1b65', 'ur-roman', 'Do not waste food; honour it and give any surplus to others.', 'khana zaya mat karein; iski qadar karein aur jo bache wo doosron ko de dein.'),
  ('d2005fae959666fbb999158e02e1a352bf12a56d4b745d43eb10cbb21b815b1d', 'ur', 'Make du’a for the one who feeds you: “Allahumma at‘im man at‘amani…”.', 'جو آپ کو کھلائے اس کے لیے دعا کریں: “Allahumma at‘im man at‘amani…”۔'),
  ('30ab009cfb8d1a0f29c7b0a601d3d029bd2372e9bca885c05eb07d7ffb282b10', 'ur-roman', 'Make du’a for the one who feeds you: “Allahumma at‘im man at‘amani…”.', 'jo aap ko khilaye uske liye dua karein: “Allahumma at‘im man at‘amani…”.'),
  ('1ec3b57f3463bd8a99550562344f067c016ee44daf8c7162c0defffa075546c2', 'ur', 'Say “Bismillah” and drink with the right hand.', '“Bismillah” کہیں اور دائیں ہاتھ سے پئیں۔'),
  ('a62fe614eb49dba2321ea41fe783fade7fd0c89b4b7bbd0b34c3b52d39435224', 'ur-roman', 'Say “Bismillah” and drink with the right hand.', '“Bismillah” kahein aur dayein haath se piyein.'),
  ('68db9ac040024815114ab8e392b0b7b9117077ac524fb009c2a5cffb3c5c02b1', 'ur', 'Sit while drinking (preferred); drink in three breaths, not one gulp.', 'بیٹھ کر پئیں (افضل ہے)؛ ایک ہی سانس میں نہیں بلکہ تین سانس میں پئیں۔'),
  ('42d12f7ec7fa07358193f9594e417d6f59e080c6c97af76c4d08f9971fe1897b', 'ur-roman', 'Sit while drinking (preferred); drink in three breaths, not one gulp.', 'baith kar piyein (behtar hai); ek hi saans me nahin balki teen saans me piyein.'),
  ('583c5a3d1a483fe2c7875baf8145017e0351fa1b7d9b7763831ae48a84fa74ac', 'ur', 'Do not breathe into the vessel while drinking.', 'پیتے وقت برتن میں سانس نہ لیں۔'),
  ('3fa0a55a47ba8145d024acc06bfd4856a185c568b0faa609b418c6dd2554e10c', 'ur-roman', 'Do not breathe into the vessel while drinking.', 'peete waqt bartan me saans mat lein.'),
  ('1768ebe19567df0fbf47aba576a61b6b3c0074dee6de8beb3b76b28f24020912', 'ur', 'Look at the water before drinking; do not drink from a cracked or broken edge.', 'پینے سے پہلے پانی کو دیکھ لیں؛ چٹخے یا ٹوٹے ہوئے کنارے سے نہ پئیں۔'),
  ('8ff863441f6ed8ad7d006bfaba353e2368e63fba8daf456684473b5ada7ef8ce', 'ur-roman', 'Look at the water before drinking; do not drink from a cracked or broken edge.', 'peene se pehle pani ko dekh lein; chatke ya toote hue kinare se mat piyein.'),
  ('1c4a36ca3923753b9b6b84f6d1c52e70c131cfea37ace0be149ad6d431e6706e', 'ur', 'When sharing, pass to the one on the right.', 'مل کر پیتے وقت دائیں طرف والے کو دیں۔'),
  ('9bbed0b4c09388b08f413af31dea6b3b7d1db2af906ec54ef65819cc76d14fc9', 'ur-roman', 'When sharing, pass to the one on the right.', 'mil kar peete waqt dayein taraf wale ko dein.'),
  ('3c492ef92136f58bc65cd8ce9c738c00ab3c943c223ea421df16adb336612ccc', 'ur', 'The one who pours/serves drinks last.', 'جو پلاتا یا خدمت کرتا ہے وہ سب سے آخر میں پیے۔'),
  ('c3a272b060220643422b0b435082a07adba662727dcdbad97331da1f02acdfad', 'ur-roman', 'The one who pours/serves drinks last.', 'jo pilata ya khidmat karta hai wo sab se aakhir me piye.'),
  ('e0318490941e6e4e054db9b64ce3b476743ee73e9b791d51c2b4d699d40ad7eb', 'ur', 'Do not drink directly from the mouth of a water-skin or large vessel.', 'مشکیزے یا بڑے برتن کے منہ سے سیدھا نہ پئیں۔'),
  ('c9779f38b2ddd47e0270871c89535fd7ef7c0095010aeff8d10477c99709cbc5', 'ur-roman', 'Do not drink directly from the mouth of a water-skin or large vessel.', 'mashkeeze ya bade bartan ke munh se seedha mat piyein.'),
  ('0b0a7488b244a931300283947e917b65aa0c784d3daeba3ef1a076f2da4792b0', 'ur', 'When given milk, say: “Allahumma barik lana fihi wa zidna minhu”.', 'جب دودھ ملے تو کہیں: “Allahumma barik lana fihi wa zidna minhu”۔'),
  ('8577e107de716fb5835887496f93ba55fbca52fab0838dd3d3ab8d06fb6c6726', 'ur-roman', 'When given milk, say: “Allahumma barik lana fihi wa zidna minhu”.', 'jab doodh mile to kahein: “Allahumma barik lana fihi wa zidna minhu”.'),
  ('b82c657a146b10c28c0f9742136ceffc66e95ae5c8971fa5237c8d14e4960e1f', 'ur', 'Do not throw away leftover water; give it to others or an animal.', 'بچا ہوا پانی پھینکیں نہیں؛ دوسروں کو یا کسی جانور کو دے دیں۔'),
  ('3d514a02679b7555bb737eba63fa3f10a3a492787dac3337961d17782d00e4ed', 'ur-roman', 'Do not throw away leftover water; give it to others or an animal.', 'bacha hua pani phenkein nahin; doosron ko ya kisi jaanwar ko de dein.'),
  ('8f9253060f64eea893c3fcaf9462764c5de8bbbd32a6df0dff7f994546d6a459', 'ur', 'Say “Alhamdulillah” after drinking.', 'پینے کے بعد “Alhamdulillah” کہیں۔'),
  ('a5ec25b800dc071852cef37620f2b2f37d2bec1c53bcaf013945113a46747673', 'ur-roman', 'Say “Alhamdulillah” after drinking.', 'peene ke baad “Alhamdulillah” kahein.'),
  ('2b39869c603aaac28b4c351fb3d39903bff85c1cd5c4b7d1e192f3ba138d26b6', 'ur', 'Perform wudu before going to sleep.', 'سونے سے پہلے وضو کر لیں۔'),
  ('aea67aa11b7c183b9726614009be6844ef6591780ff1ae01cdb13107a57b7c62', 'ur-roman', 'Perform wudu before going to sleep.', 'sone se pehle wuzu kar lein.'),
  ('eb198db4d4b497712aefc4694591033068b7aa576c81f16d003a0b672ecde16b', 'ur', 'Dust off the bed three times before lying down.', 'لیٹنے سے پہلے بستر کو تین بار جھاڑ لیں۔'),
  ('61cbbb2f4379f4fed51696bcbf43650fd219c3a7c605949e8de45e6ea5308912', 'ur-roman', 'Dust off the bed three times before lying down.', 'letne se pehle bistar ko teen baar jhaad lein.'),
  ('cb33043e2ee7b4124d2c64b5f3449d875022a5b3e54ac5442440e73545963d79', 'ur', 'Sleep on the right side, hand under the cheek.', 'دائیں کروٹ پر سوئیں، ہاتھ گال کے نیچے رکھ کر۔'),
  ('bf0f6891bb63333894ade429753f3ea2db8eee5ab8599849a3cf9b62c1b5132d', 'ur-roman', 'Sleep on the right side, hand under the cheek.', 'dayein karwat par soyein, haath gaal ke neeche rakh kar.'),
  ('9c6104058de161d7cffba667a0748a05cadbd70d8f10d4f1fab5ffd7a728f345', 'ur', 'Recite Ayat al-Kursi, the last two ayahs of Surah Al-Baqarah, and Surah Al-Mulk.', 'آیت الکرسی، سورۃ البقرہ کی آخری دو آیات، اور سورۃ الملک پڑھیں۔'),
  ('554907169b8425e90831c2665c48e543e05b72e1e9f5e7778f48dfa84080705e', 'ur-roman', 'Recite Ayat al-Kursi, the last two ayahs of Surah Al-Baqarah, and Surah Al-Mulk.', 'Ayatul Kursi, Surah Al-Baqarah ki aakhri do ayatein, aur Surah Al-Mulk padhein.'),
  ('00aad805aa935ac85873f183cbdb1df1aebe2cdab847d4392b5e0e522bf61f88', 'ur', 'Recite the three Quls (Ikhlas, Falaq, Nas), blow into the palms and wipe over the body three times.', 'تینوں قل (اخلاص، فلق، ناس) پڑھ کر ہتھیلیوں میں پھونکیں اور تین بار پورے جسم پر پھیریں۔'),
  ('5c2966524387abb05d111114a00c4711e9913bf30e83b8a51c2b60d1e431518e', 'ur-roman', 'Recite the three Quls (Ikhlas, Falaq, Nas), blow into the palms and wipe over the body three times.', 'teenon Qul (Ikhlas, Falaq, Naas) padh kar hatheliyon me phoonkein aur teen baar poore jism par pherein.'),
  ('48582209c1e9fa8c9924027e22c73bbf4a4981e52442a6d1f3ba88e98f34dc07', 'ur', 'Say the sleeping du’a: “Allahumma bismika amutu wa ahya”.', 'سوتے وقت کی دعا پڑھیں: “Allahumma bismika amutu wa ahya”۔'),
  ('12ea53eddea577da91f2aa1a6b6d670c8b012c9db397992df5f57ece98a1ca6a', 'ur-roman', 'Say the sleeping du’a: “Allahumma bismika amutu wa ahya”.', 'sote waqt ki dua padhein: “Allahumma bismika amutu wa ahya”.'),
  ('5ba790973bf1a38bf4e29d7449d917a248c3df8d34d9fb48f914407c89ec40de', 'ur', 'On waking say: “Alhamdulillahil-ladhi ahyana ba‘da ma amatana wa ilayhin-nushur”.', 'بیدار ہو کر کہیں: “Alhamdulillahil-ladhi ahyana ba‘da ma amatana wa ilayhin-nushur”۔'),
  ('20407c176ad6f5fe57f62358e774d2f9859c69b78bc25f7c3adb9579db911ecd', 'ur-roman', 'On waking say: “Alhamdulillahil-ladhi ahyana ba‘da ma amatana wa ilayhin-nushur”.', 'jaag kar kahein: “Alhamdulillahil-ladhi ahyana ba‘da ma amatana wa ilayhin-nushur”.'),
  ('f5244a0d256adc68be588a9f06eaafd23dbffdf62c7fce6e21d6ec302ccef934', 'ur', 'Do not sleep on the stomach — this posture is disliked.', 'پیٹ کے بل نہ سوئیں — یہ طریقہ ناپسندیدہ ہے۔'),
  ('30182e73af3a614783818ba5a8d64cf2bdcc1b574fbe2e39e0c10072c8627f1c', 'ur-roman', 'Do not sleep on the stomach — this posture is disliked.', 'pet ke bal mat soyein — yeh tareeqa napasand hai.'),
  ('4dd52b2106157ccb14288b067d28a6084aa707ae133ee2f3ccd9c99005809a36', 'ur', 'Recite Tasbih-e-Fatima before sleeping — SubhanAllah 33, Alhamdulillah 33, Allahu Akbar 34.', 'سونے سے پہلے تسبیحِ فاطمہ پڑھیں — SubhanAllah 33، Alhamdulillah 33، Allahu Akbar 34۔'),
  ('768b0a86095957fe232f0c6a3a3bcc6ef4ad0457f19f0efba7733c2ac53df756', 'ur-roman', 'Recite Tasbih-e-Fatima before sleeping — SubhanAllah 33, Alhamdulillah 33, Allahu Akbar 34.', 'sone se pehle Tasbeeh-e-Fatima padhein — SubhanAllah 33, Alhamdulillah 33, Allahu Akbar 34.'),
  ('0b659cc1d9b0831754402fcc438233468dfe970c7ad57461a0e615c7f9250cae', 'ur', 'Sleep early after Isha; avoid staying up needlessly.', 'عشاء کے بعد جلدی سو جائیں؛ بلا ضرورت جاگنے سے بچیں۔'),
  ('d3ccb41433840e6bd54539820fa5bf5c2ac0f12f1faf557cc2c16c23087159d5', 'ur-roman', 'Sleep early after Isha; avoid staying up needlessly.', 'Isha ke baad jaldi so jayein; bila zaroorat jaagne se bachein.'),
  ('dca5ebbf9330f188039f8ba5d4b7a90e9d33b274f54e82dc3b55894ff6307045', 'ur', 'Cover food and drink vessels and put out any open flame before sleeping.', 'سونے سے پہلے کھانے پینے کے برتن ڈھانپ دیں اور کھلی آگ بجھا دیں۔'),
  ('fa863d4bce53c1fef92da37643158e724d9c292482fa503fbdc40bf152cd66eb', 'ur-roman', 'Cover food and drink vessels and put out any open flame before sleeping.', 'sone se pehle khane peene ke bartan dhaanp dein aur khuli aag bujha dein.'),
  ('63d678f7a484ff072bf368f087ae5edbdc33193526db7a73c955b41739044f21', 'ur', 'On a bad dream, seek refuge in Allah, spit lightly to the left three times, change side, and do not tell anyone.', 'برا خواب دیکھیں تو اللہ کی پناہ مانگیں، بائیں طرف تین بار ہلکا تھوکیں، کروٹ بدل لیں، اور کسی کو نہ بتائیں۔'),
  ('a23c465edf2aca587ddbc4bb8661f0c33156bd7bff7cf3d7f42d84f69bca4038', 'ur-roman', 'On a bad dream, seek refuge in Allah, spit lightly to the left three times, change side, and do not tell anyone.', 'bura khwab dekhein to Allah ki panah maangein, bayein taraf teen baar halka thookein, karwat badal lein, aur kisi ko mat batayein.'),
  ('efcf643af8941b4be7f092c77cfdf2db4f631f0cc228523067b2cbf959b7bcf1', 'ur', 'Sleep with a clean heart — forgive others before sleeping.', 'صاف دل کے ساتھ سوئیں — سونے سے پہلے دوسروں کو معاف کر دیں۔'),
  ('1b2ff66ae0420efd8eb147b8c9a7b2f3a2024155205b0cc9711878aa0bc85670', 'ur-roman', 'Sleep with a clean heart — forgive others before sleeping.', 'saaf dil ke saath soyein — sone se pehle doosron ko maaf kar dein.'),
  ('405454752ce29b0a4761258ce3710df066117c0b7dd295450f486a46474be5a7', 'ur', 'Enter with the left foot, saying “Allahumma inni a‘udhu bika minal khubuthi wal khaba’ith”.', 'بائیں پاؤں سے داخل ہوں اور کہیں “Allahumma inni a‘udhu bika minal khubuthi wal khaba’ith”۔'),
  ('e9da871749142f82c11510061b984a887fa04ca1f87239c03d67986aa420aedb', 'ur-roman', 'Enter with the left foot, saying “Allahumma inni a‘udhu bika minal khubuthi wal khaba’ith”.', 'bayein paon se dakhil hon aur kahein “Allahumma inni a‘udhu bika minal khubuthi wal khaba’ith”.'),
  ('d4d75a844264159ed8172247a518f0a765dacbc5bf3f4681108c9a8ec785b296', 'ur', 'Leave with the right foot, saying “Ghufranaka”.', 'دائیں پاؤں سے نکلیں اور کہیں “Ghufranaka”۔'),
  ('bd978cd5f4bc0f555a1ab163e31ce3d0fe12a139324fb9cb14ff770ecdf59063', 'ur-roman', 'Leave with the right foot, saying “Ghufranaka”.', 'dayein paon se niklein aur kahein “Ghufranaka”.'),
  ('b879dcd397ae17dc9874551951e1da68f5566fff595d0a423f9eaa605d6e735c', 'ur', 'Do not face the Qibla or turn the back towards it while relieving oneself.', 'قضائے حاجت کے وقت نہ قبلہ کی طرف منہ کریں نہ پیٹھ۔'),
  ('7782078068b2d779316ec94a58928698d227470a47eaff6423a011fb05f210da', 'ur-roman', 'Do not face the Qibla or turn the back towards it while relieving oneself.', 'qaza-e-haajat ke waqt na Qibla ki taraf munh karein na peeth.'),
  ('e3705ec1359260f8b93eb0fab35e6772daa7a07dc9b8a9bd08c3371fc871e44b', 'ur', 'Use the left hand for istinja (cleaning); do not use the right hand.', 'استنجا (صفائی) کے لیے بایاں ہاتھ استعمال کریں؛ دایاں ہاتھ استعمال نہ کریں۔'),
  ('3a7b07ff91f2eaefb6906747b0fc5c2705f4dda169b47c56e6a7401aeda036d1', 'ur-roman', 'Use the left hand for istinja (cleaning); do not use the right hand.', 'istinja (safai) ke liye baya haath istemaal karein; daya haath istemaal mat karein.'),
  ('167714a0876eeec49800baa14fb08e45560d7b30f86a379fdad4258b1066065a', 'ur', 'Clean thoroughly with water (or stones/tissue where water is unavailable).', 'پانی سے اچھی طرح صفائی کریں (اور جہاں پانی نہ ہو وہاں ڈھیلے یا ٹشو سے)۔'),
  ('72fc65e66cf9fc5eadffdaef9111a327fefb216813b526d67c6f27bb46e6f378', 'ur-roman', 'Clean thoroughly with water (or stones/tissue where water is unavailable).', 'pani se achhi tarah safai karein (aur jahan pani na ho wahan dhele ya tissue se).'),
  ('cfbc6b60d3fdd21b98d640afcc1a9eacc39ea1b65c6490f8392093fe4ebb3498', 'ur', 'Do not carry anything bearing the name of Allah or Qur’an unnecessarily, and avoid talking inside.', 'بلا ضرورت اللہ کے نام یا قرآن والی کوئی چیز اندر نہ لے جائیں، اور اندر بات کرنے سے بچیں۔'),
  ('1ad963fcaf5a4c5ef222742827bacf12e18da265d5fea54b9113d3095c935f84', 'ur-roman', 'Do not carry anything bearing the name of Allah or Qur’an unnecessarily, and avoid talking inside.', 'bila zaroorat Allah ke naam ya Quran wali koi cheez andar mat le jayein, aur andar baat karne se bachein.'),
  ('711c20fa109fb3405c58cae63c611368f5097a29f517bec4c7a0a7996a66d65f', 'ur', 'Choose a concealed place and do not expose the satr before others.', 'چھپی ہوئی جگہ منتخب کریں اور ستر کسی کے سامنے نہ کھولیں۔'),
  ('3903a18d901cac13987ae6dac8f3c8a00ce8140f01485055a668383e6777ead2', 'ur-roman', 'Choose a concealed place and do not expose the satr before others.', 'chhupi hui jagah chunein aur satar kisi ke saamne mat kholein.'),
  ('88eba79c43532dc80d4903c29edcc44e2c3e3b5763177169dfd9284650eebbc3', 'ur', 'Do not face or expose oneself towards the sun or moon while relieving oneself.', 'قضائے حاجت کے وقت سورج یا چاند کی طرف منہ یا ستر نہ کھولیں۔'),
  ('cb4b9bb4cad53cf5e0c20bccce3cb624ca71b360faa71494387d9a35b23dcfce', 'ur-roman', 'Do not face or expose oneself towards the sun or moon while relieving oneself.', 'qaza-e-haajat ke waqt sooraj ya chaand ki taraf munh ya satar mat kholein.'),
  ('d91045f234d471d941f1de29dfd67d00c667bc51ffbeddedd1dbfff9605e227d', 'ur', 'Do not relieve oneself in still water, on pathways, or where people rest.', 'ٹھہرے ہوئے پانی میں، راستوں پر، یا جہاں لوگ بیٹھتے ہوں وہاں قضائے حاجت نہ کریں۔'),
  ('bf61b2238eb3b439d099d634987a77e1fdcb5250cc12a60c0ab92a9b7918bbd1', 'ur-roman', 'Do not relieve oneself in still water, on pathways, or where people rest.', 'thehre hue pani me, raaston par, ya jahan log baithte hon wahan qaza-e-haajat mat karein.'),
  ('edde58e2eb0147ed9f75382bca34bbfc3e6010f9b565e8679e356b127043fad8', 'ur', 'Remove any impurity and make wudu afterwards for prayer.', 'ہر نجاست دور کریں اور نماز کے لیے بعد میں وضو کر لیں۔'),
  ('12a65157ac81cf1038738566888e3ea81ba18641f5909480c82aa30c92f0fedf', 'ur-roman', 'Remove any impurity and make wudu afterwards for prayer.', 'har najasat door karein aur namaz ke liye baad me wuzu kar lein.'),
  ('c29cd717eeb2457f89be051ab0f6639e80c9ca3cf0b97e04f72b2392ed5d85e5', 'ur', 'Spread the salam among one another — it increases love.', 'آپس میں سلام پھیلائیں — اس سے محبت بڑھتی ہے۔'),
  ('3f1bc79fef89498590c49cf517058db167d975b1158e4150f38122770a16c9eb', 'ur-roman', 'Spread the salam among one another — it increases love.', 'aapas me salam phailayein — is se mohabbat badhti hai.'),
  ('d3c2e0921745126bcb9fb9a5165fd2d5ee910ef7c9adfc23d598b700322a3137', 'ur', 'The full greeting: “Assalamu alaikum wa rahmatullahi wa barakatuh”.', 'مکمل سلام: “Assalamu alaikum wa rahmatullahi wa barakatuh”۔'),
  ('4e501707c49dca2b0e6845afab6a0d3ea282fec9e8097697793eca876382cc8a', 'ur-roman', 'The full greeting: “Assalamu alaikum wa rahmatullahi wa barakatuh”.', 'mukammal salam: “Assalamu alaikum wa rahmatullahi wa barakatuh”.'),
  ('e57733cb84a65c0d060a8a1bd47640d69eec871890e539be93715b650728f37d', 'ur', 'Reply with an equal or better greeting.', 'جواب اسی جیسے یا اس سے بہتر الفاظ میں دیں۔'),
  ('30715c19a5c991e5f15df51655b18938f4c7cd27b4521e50e833e7a842f28e08', 'ur-roman', 'Reply with an equal or better greeting.', 'jawab isi jaisa ya is se behtar alfaaz me dein.'),
  ('0bac5395232d3a5973cbebcf3b28f511225271955fca95cf3aff4ef95ca48f06', 'ur', 'The rider greets the walker, the walker greets the sitting, and the smaller group greets the larger.', 'سوار پیدل کو سلام کرے، پیدل بیٹھے ہوئے کو، اور چھوٹی جماعت بڑی جماعت کو سلام کرے۔'),
  ('c453a34952fb344656b1c2786eeb15aecf27948308d006ce7fdd49627c7384de', 'ur-roman', 'The rider greets the walker, the walker greets the sitting, and the smaller group greets the larger.', 'sawar paidal ko salam kare, paidal baithe hue ko, aur chhoti jamaat badi jamaat ko salam kare.'),
  ('7031a0672af190e081fd4d9ee4bac0520fb9ea8d4041410f427928068130aac5', 'ur', 'Give salam when entering a gathering and when leaving it.', 'مجلس میں آتے وقت اور جاتے وقت سلام کریں۔'),
  ('47e0aaa2782eaa9f1a873501990986e789d4788276a1823854a846f40635c1cc', 'ur-roman', 'Give salam when entering a gathering and when leaving it.', 'majlis me aate waqt aur jaate waqt salam karein.'),
  ('032ed6d2c164948fd295e92a8d6c6c602ffbd6f353fa35ab8a6558b21d90f737', 'ur', 'Respond to a sneezer, visit the sick, and fulfil promises — rights of a Muslim.', 'چھینکنے والے کا جواب دیں، بیمار کی عیادت کریں، اور وعدے پورے کریں — یہ مسلمان کے حقوق ہیں۔'),
  ('ee60bfa25332613dab2cc3ff8198a2b33a8cb14809985e4d8d03d51b15f62fb5', 'ur-roman', 'Respond to a sneezer, visit the sick, and fulfil promises — rights of a Muslim.', 'chheenkne wale ka jawab dein, beemar ki iyadat karein, aur waade poore karein — yeh musalman ke huqooq hain.'),
  ('4c3e9bd958eeb4d61ebc74be00b05a1000494152d6beaf9ae7bac92990299332', 'ur', 'Enter with the right foot, say “Bismillah”, and greet the household with salam.', 'دائیں پاؤں سے داخل ہوں، “Bismillah” کہیں، اور گھر والوں کو سلام کریں۔'),
  ('042c52320fde1846ce0b5232dfc86400f88e64dc35a5e3c220a82dd2672129f7', 'ur-roman', 'Enter with the right foot, say “Bismillah”, and greet the household with salam.', 'dayein paon se dakhil hon, “Bismillah” kahein, aur ghar walon ko salam karein.'),
  ('6f63f73a1d7f30cce46161fde2d3bc40eb2d60f8c9d0f1cc6fe0542825b9b503', 'ur', 'Mention Allah’s name when entering and when eating — it keeps Shaytan out.', 'داخل ہوتے اور کھاتے وقت اللہ کا نام لیں — اس سے شیطان دور رہتا ہے۔'),
  ('63a08877d3ab06b3341c6e6d02ffbb7670dd1ea81bd48a4af6d78e7df0fb63cd', 'ur-roman', 'Mention Allah’s name when entering and when eating — it keeps Shaytan out.', 'dakhil hote aur khate waqt Allah ka naam lein — is se shaytan door rehta hai.'),
  ('6b2102846b9e6c5040569e3da07b6ce7270011731379d52087c965eaffd8ff96', 'ur', 'When leaving say: “Bismillahi tawakkaltu ‘alallah, la hawla wa la quwwata illa billah”.', 'نکلتے وقت کہیں: “Bismillahi tawakkaltu ‘alallah, la hawla wa la quwwata illa billah”۔'),
  ('34364217aa16d1c63cbcdf7e072f220440328d87cbc29638e84fa623b88b236a', 'ur-roman', 'When leaving say: “Bismillahi tawakkaltu ‘alallah, la hawla wa la quwwata illa billah”.', 'nikalte waqt kahein: “Bismillahi tawakkaltu ‘alallah, la hawla wa la quwwata illa billah”.'),
  ('411e31ee26793bbd274411d5f58e4f4b9ec8e3e86f0c338b17d08d14ed94aed3', 'ur', 'Seek permission (isti’dhan) before entering others’ homes, up to three times.', 'دوسروں کے گھر میں داخل ہونے سے پہلے اجازت (استیذان) لیں، تین بار تک۔'),
  ('0a35201f56dc09e1b2da698a5e75979ae55438fbf51ae8b5eb3af34e9659eabf', 'ur-roman', 'Seek permission (isti’dhan) before entering others’ homes, up to three times.', 'doosron ke ghar me dakhil hone se pehle ijaazat (istizaan) lein, teen baar tak.'),
  ('ec9b23917d22cb8cd2183dea74e74d8ad80d27c30c34e3cc86d1a5e9dff51483', 'ur', 'Give salam even if the house is empty: “Assalamu ‘alaina wa ‘ala ‘ibadillahis-salihin”.', 'گھر خالی ہو تب بھی سلام کریں: “Assalamu ‘alaina wa ‘ala ‘ibadillahis-salihin”۔'),
  ('fead22dd52e072ab06cbff55c29570fc27c4962821f1d9777d2691980ffdb2f6', 'ur-roman', 'Give salam even if the house is empty: “Assalamu ‘alaina wa ‘ala ‘ibadillahis-salihin”.', 'ghar khali ho tab bhi salam karein: “Assalamu ‘alaina wa ‘ala ‘ibadillahis-salihin”.'),
  ('95a7c11eb501e961c1ba49dc372b23045831a4710853c92d3a1f61bd36513fe5', 'ur', 'Use the miswak on entering the home, as was the Prophet’s ﷺ habit.', 'گھر میں داخل ہوتے وقت مسواک کریں، جیسا کہ نبی ﷺ کی عادت تھی۔'),
  ('ee013fa92827816031ac94f6bff093b022eba7376c57d6b9db703dacaa768327', 'ur-roman', 'Use the miswak on entering the home, as was the Prophet’s ﷺ habit.', 'ghar me dakhil hote waqt miswak karein, jaisa ke Nabi ﷺ ki aadat thi.'),
  ('757816bf01e3d078606628fb6c55b6690a775dc83b98d4c79729f7a546861c22', 'ur', 'Help the household with chores — the Prophet ﷺ served his family.', 'گھر کے کاموں میں گھر والوں کی مدد کریں — نبی ﷺ اپنے گھر والوں کے کام کرتے تھے۔'),
  ('5e9c3ee34476d87031610a0226ddc4528230ed1febccacafcf2f9b26ab4720a5', 'ur-roman', 'Help the household with chores — the Prophet ﷺ served his family.', 'ghar ke kaamon me ghar walon ki madad karein — Nabi ﷺ apne ghar walon ke kaam karte the.'),
  ('2641d324f48c1f2dea5795b8b88eb7ef9ce02fe093c4d458540e1c10c174d0b0', 'ur', 'Recite Surah Al-Baqarah in the home; Shaytan flees from a house in which it is recited.', 'گھر میں سورۃ البقرہ پڑھیں؛ جس گھر میں یہ پڑھی جائے شیطان وہاں سے بھاگتا ہے۔'),
  ('21d224ed6836124369315b875767a5c22230ad3e53e3963722934f3bd12e9da0', 'ur-roman', 'Recite Surah Al-Baqarah in the home; Shaytan flees from a house in which it is recited.', 'ghar me Surah Al-Baqarah padhein; jis ghar me yeh padhi jaye shaytan wahan se bhaagta hai.'),
  ('d42e46619dd34a90d0065995202234ca5eb36686311330a466647f434a7f054c', 'ur', 'At nightfall close the doors, cover the vessels and mention Allah’s name.', 'رات ہوتے ہی دروازے بند کر دیں، برتن ڈھانپ دیں اور اللہ کا نام لیں۔'),
  ('5f6b34aca4fb87c39ad3f893afbc8e5ecc7cae9d25eb7bd7f2c832dd1503de2c', 'ur-roman', 'At nightfall close the doors, cover the vessels and mention Allah’s name.', 'raat hote hi darwaze band kar dein, bartan dhaanp dein aur Allah ka naam lein.'),
  ('1343e7ca595a5b29493b2c1b70b4fbcb9fc032fa92c4547d81dab9c23098bd53', 'ur', 'Do not keep pictures of living beings or a dog (except for guarding/farming) in the home.', 'گھر میں جانداروں کی تصویریں یا کتا نہ رکھیں (سوائے حفاظت یا کھیتی کے لیے)۔'),
  ('01d413c2618e064fa923e909b03b371ef8bc385ace6151474743f0f87bf7a941', 'ur-roman', 'Do not keep pictures of living beings or a dog (except for guarding/farming) in the home.', 'ghar me jaandaron ki tasveerein ya kutta mat rakhein (siwaye hifazat ya kheti ke liye).'),
  ('9c3588bed18a2134428c28c2861eeb4bd0717e01f875c886b7a3634545205c9f', 'ur', 'Keep the home clean and remove anything harmful from the path/entrance.', 'گھر کو صاف رکھیں اور راستے یا دروازے سے ہر تکلیف دہ چیز ہٹا دیں۔'),
  ('0f5c5884c982512e352d1229e719c81e08446a318b7c76f26ff345a8e9cdc7fc', 'ur-roman', 'Keep the home clean and remove anything harmful from the path/entrance.', 'ghar ko saaf rakhein aur raaste ya darwaze se har takleef deh cheez hata dein.'),
  ('1085d3449aa7285aae42e4a8e8bbf52bbb0fbef28536f6ec24e063d26b21cb31', 'ur', 'Do not return to the family suddenly late at night without notice.', 'بغیر اطلاع کے رات گئے اچانک گھر والوں کے پاس نہ لوٹیں۔'),
  ('4f9818d65771a1c2d093fc3a68899d300a463f2192fc022fee47720790629008', 'ur-roman', 'Do not return to the family suddenly late at night without notice.', 'bagair ittila ke raat gaye achanak ghar walon ke paas mat lautein.'),
  ('5bd70a381a182991ff288be8f3c91c9b03fc8b866524333807f4b352ea40892c', 'ur', 'Enter with the right foot, saying “Allahumma iftah li abwaba rahmatik”.', 'دائیں پاؤں سے داخل ہوں اور کہیں “Allahumma iftah li abwaba rahmatik”۔'),
  ('8173eddb341e6d44f874c40f0e3c71100d003b725ebf05fbe5cee51f10ed627d', 'ur-roman', 'Enter with the right foot, saying “Allahumma iftah li abwaba rahmatik”.', 'dayein paon se dakhil hon aur kahein “Allahumma iftah li abwaba rahmatik”.'),
  ('9c1eb967c5fcc2af2c1eff6b6428badcec88eee1c78f658cfbb870d7d46eaf3f', 'ur', 'Leave with the left foot, saying “Allahumma inni as’aluka min fadlik”.', 'بائیں پاؤں سے نکلیں اور کہیں “Allahumma inni as’aluka min fadlik”۔'),
  ('cf1201255756045d20c8a18269bd9ce8a80d8605b06bc3d09fa5e347b94315ee', 'ur-roman', 'Leave with the left foot, saying “Allahumma inni as’aluka min fadlik”.', 'bayein paon se niklein aur kahein “Allahumma inni as’aluka min fadlik”.'),
  ('e973721553880c1f0a83a9216087b4806bbd2cf7c62f6e46aadbba060d8c62cf', 'ur', 'Pray two rak’ah (Tahiyyat al-Masjid) before sitting down.', 'بیٹھنے سے پہلے دو رکعت (تحیۃ المسجد) پڑھیں۔'),
  ('a5a8d663e1f10d9329115b89e2b03bd0803abea80f4ae3c94533f300f721e38e', 'ur-roman', 'Pray two rak’ah (Tahiyyat al-Masjid) before sitting down.', 'baithne se pehle do rakat (Tahiyyatul Masjid) padhein.'),
  ('3dfa92095472bd5491114585d3122baff1675cf83cce0b3d1eddc1017c448790', 'ur', 'Come in a state of wudu, in clean clothes, without the smell of raw onion/garlic.', 'وضو کی حالت میں، صاف کپڑوں کے ساتھ، اور کچی پیاز یا لہسن کی بو کے بغیر آئیں۔'),
  ('0c1fe26fc24558e210f9a2c7677a9c0a0cf0cb19cd9dd162ba1c42116f8c0d73', 'ur-roman', 'Come in a state of wudu, in clean clothes, without the smell of raw onion/garlic.', 'wuzu ki halat me, saaf kapdon ke saath, aur kachi pyaz ya lehsan ki boo ke bagair aayein.'),
  ('edbcdef59a4f88ae382660a14b8bb734f302765602014ae6d80b40d4e140067e', 'ur', 'Keep the masjid clean and quiet; no worldly buying and selling inside.', 'مسجد کو صاف اور پُرسکون رکھیں؛ اندر دنیاوی خرید و فروخت نہ کریں۔'),
  ('651bdabf2259d49fe10bd63ced38aab4e53921c230881f335893f7957a4adacc', 'ur-roman', 'Keep the masjid clean and quiet; no worldly buying and selling inside.', 'masjid ko saaf aur pursukoon rakhein; andar duniyavi khareed o farokht mat karein.'),
  ('42860dd92aaa0a4c1ebda961163b5f8137d019d806f59b79934494db9d2af35e', 'ur', 'Walk to the masjid calmly and with dignity; do not run, even if the prayer has started.', 'مسجد کی طرف سکون اور وقار سے چلیں؛ چاہے نماز شروع ہو چکی ہو، دوڑیں نہیں۔'),
  ('d5d80dffde67b3bae306c9556f134c7aef90369d36dcf88a024636b232f5d427', 'ur-roman', 'Walk to the masjid calmly and with dignity; do not run, even if the prayer has started.', 'masjid ki taraf sukoon aur waqaar se chalein; chahe namaz shuru ho chuki ho, daudein nahin.'),
  ('cae66dd720fd79239ee4fa470760495eed77a9addde39c795f3a0d6bb151a3de', 'ur', 'Do not disturb others’ prayer or raise the voice in recitation over them.', 'دوسروں کی نماز میں خلل نہ ڈالیں اور تلاوت میں ان پر آواز بلند نہ کریں۔'),
  ('fa3a9a7e92cec1b0035a8491a8c13dfe2d429f79afd1657d9356ffb2b9fb1b48', 'ur-roman', 'Do not disturb others’ prayer or raise the voice in recitation over them.', 'doosron ki namaz me khalal mat daalein aur tilawat me un par awaz buland mat karein.'),
  ('0252bf3a6422d616edfe3f2be22f4dea63b74cc3707a798e484dba83ba3df673', 'ur', 'Do not announce lost property in the masjid.', 'مسجد میں گمشدہ چیز کا اعلان نہ کریں۔'),
  ('26b1cc972aef16d16a59c235e2a801ae2cc3f71bfd48ed896632fabb440d639f', 'ur-roman', 'Do not announce lost property in the masjid.', 'masjid me gumshuda cheez ka elaan mat karein.'),
  ('e3a825525a565eb9ee82866ffdc01a1ad010381617cba4c7dcd1a765063e0600', 'ur', 'Seek the front rows — there is great virtue in the first row.', 'اگلی صفوں میں جگہ ڈھونڈیں — پہلی صف میں بڑی فضیلت ہے۔'),
  ('7b705d22f2d6c0822ee4f41a97c97ff06826809c0540bb539219c17eecab43c3', 'ur-roman', 'Seek the front rows — there is great virtue in the first row.', 'agli safon me jagah dhoondein — pehli saf me badi fazeelat hai.'),
  ('e4361efd84032f551daea51f14d5130a4c97fc65f45d8308f454bb808e37e54e', 'ur', 'Pray towards a sutrah (barrier) and do not let anyone pass directly in front.', 'سترہ (آڑ) کی طرف نماز پڑھیں اور کسی کو اپنے بالکل سامنے سے گزرنے نہ دیں۔'),
  ('99ba25a671d331f6e93fd06d7d5550a228ec712936c4ed44e04619cad3d67901', 'ur-roman', 'Pray towards a sutrah (barrier) and do not let anyone pass directly in front.', 'sutrah (aad) ki taraf namaz padhein aur kisi ko apne bilkul saamne se guzarne mat dein.'),
  ('e127e95a5940e2675977af3ff9cfd22b4aa4b5a56a50bfc53e3bbf39cd0ae8ab', 'ur', 'While waiting for salah you are “in prayer”, and the angels send blessings upon you.', 'نماز کے انتظار میں آپ گویا “نماز میں” ہیں، اور فرشتے آپ پر رحمت بھیجتے ہیں۔'),
  ('f74c43344158021cf3e3e3b87b1d9f53c81938fb245e18589f2e9d551bc79e5a', 'ur-roman', 'While waiting for salah you are “in prayer”, and the angels send blessings upon you.', 'namaz ke intezaar me aap goya “namaz me” hain, aur farishte aap par rehmat bhejte hain.'),
  ('dab44966c8ec4818f4e64951b8b14926cb26d9342060d4f1d854431b4d4e8ad3', 'ur', 'Women’s rows are behind the men’s; maintain modesty and order.', 'عورتوں کی صفیں مردوں کے پیچھے ہوں؛ حیا اور ترتیب برقرار رکھیں۔'),
  ('1f1cdf3f9409422c268d48020750f023497430c1eccdd4c8748c1caf59c86265', 'ur-roman', 'Women’s rows are behind the men’s; maintain modesty and order.', 'auraton ki safein mardon ke peeche hon; haya aur tarteeb barqaraar rakhein.'),
  ('de20158c7342107c0bab00e64bede78bf6475ebe926a2e770f696802e30cc591', 'ur', 'Straighten and fill the rows, closing gaps for the congregation.', 'صفیں سیدھی کریں اور بھر دیں، جماعت کے لیے خالی جگہیں پُر کریں۔'),
  ('2ecf02e190f3eace34c98e88728d67dd771c003bd6e23d50ab8cdbdc031b92a5', 'ur-roman', 'Straighten and fill the rows, closing gaps for the congregation.', 'safein seedhi karein aur bhar dein, jamaat ke liye khali jagahein pur karein.'),
  ('73972a6a19e388ed9056bf2a9eb77ff13fadb69e3e8b974f178cb734a1a44b73', 'ur', 'When you sneeze, say “Alhamdulillah”, and lower the voice while covering the mouth.', 'جب چھینک آئے تو “Alhamdulillah” کہیں، منہ ڈھانپ کر آواز پست رکھیں۔'),
  ('5b22e4a56cc3e8944b209c3dbc77c15f7366695ba8c43f61311c128708e684ef', 'ur-roman', 'When you sneeze, say “Alhamdulillah”, and lower the voice while covering the mouth.', 'jab chheenk aaye to “Alhamdulillah” kahein, munh dhaank kar awaz pasht rakhein.'),
  ('38081820001b90c07d73af46d789914bf6c981584fdfe482d4cde355a093646c', 'ur', 'The one who hears it replies “Yarhamukallah”.', 'سننے والا جواب میں “Yarhamukallah” کہے۔'),
  ('b36258ad8386ddf15b00a62e7104e46f032597dc70064336ef92b2282d87cc7e', 'ur-roman', 'The one who hears it replies “Yarhamukallah”.', 'sunne wala jawab me “Yarhamukallah” kahe.'),
  ('11369f46f26a8c307b5f5d7462ee022028e3e67a20abccd9684886b3d8bad182', 'ur', 'The sneezer then answers “Yahdikumullahu wa yuslihu balakum”.', 'پھر چھینکنے والا جواب دے “Yahdikumullahu wa yuslihu balakum”۔'),
  ('e128cf02aaf8b7ee5481ace95cd88a3ca7bf58c58f37631cd7d8ab19fc772b21', 'ur-roman', 'The sneezer then answers “Yahdikumullahu wa yuslihu balakum”.', 'phir chheenkne wala jawab de “Yahdikumullahu wa yuslihu balakum”.'),
  ('5296943f010874d18b67776cd84b205b675c624545a2d487b18f02447714fb10', 'ur', 'Yawning is from Shaytan — suppress it as much as possible and cover the mouth with the hand.', 'جمائی شیطان کی طرف سے ہے — جتنا ہو سکے اسے روکیں اور ہاتھ سے منہ ڈھانپ لیں۔'),
  ('09a3572df169d12e5197e592775c6631c85419a07c7e95bd49a3acd1c6208777', 'ur-roman', 'Yawning is from Shaytan — suppress it as much as possible and cover the mouth with the hand.', 'jamahi shaytan ki taraf se hai — jitna ho sake ise rokein aur haath se munh dhaank lein.'),
  ('135fbc25a74e75c8f4cd8b1bfba6baf2a01b50ebaba2568887b15b198b62b031', 'ur', 'Begin with the right side when putting on clothes and shoes; begin with the left when removing.', 'کپڑے اور جوتے پہنتے وقت دائیں طرف سے شروع کریں؛ اتارتے وقت بائیں طرف سے۔'),
  ('915508ea4c08bcff5344ce135b6fc53de5cdf92481b604ea58ff26b220b15a55', 'ur-roman', 'Begin with the right side when putting on clothes and shoes; begin with the left when removing.', 'kapde aur joote pehente waqt dayein taraf se shuru karein; utaarte waqt bayein taraf se.'),
  ('4373362a0fd1d9ad6ad9fa0640c5a2b74db88c3862671db1a572bb38bd62af49', 'ur', 'Recite the du’a for new clothes, thanking Allah for the covering.', 'نئے کپڑوں کی دعا پڑھیں اور اللہ کا شکر ادا کریں کہ اس نے پردہ عطا کیا۔'),
  ('60d82b2f8097b06e5e7ddc837cb3b9247bae2431c8979ae4f2688858611b2e71', 'ur-roman', 'Recite the du’a for new clothes, thanking Allah for the covering.', 'naye kapdon ki dua padhein aur Allah ka shukr ada karein ke usne parda ata kiya.'),
  ('452ab619e37f46eec8e635f7c632337d470afe3e8c522e8e763222f9481ac19b', 'ur', 'Men must not let the lower garment hang below the ankles (isbal) out of pride.', 'مرد تکبر سے تہبند یا پائجامہ ٹخنوں سے نیچے نہ لٹکائیں (اسبال)۔'),
  ('c94e87bf4702797eb422b8f3045f236778d847e6c5c2c0c10b1faf94920a1e18', 'ur-roman', 'Men must not let the lower garment hang below the ankles (isbal) out of pride.', 'mard takabbur se tehband ya paijama takhnon se neeche mat latkayein (isbaal).'),
  ('eb84bffbd4a985c809c9f3cb4f09497044e4b5c1bc266de33484ee2a248e63b7', 'ur', 'Men must not wear silk or gold.', 'مرد ریشم یا سونا نہ پہنیں۔'),
  ('8a92e30283b982aeb563abee63b17a7e861329c8cc1771e401b72372789aaa44', 'ur-roman', 'Men must not wear silk or gold.', 'mard resham ya sona mat pehnein.'),
  ('525cd802f9f11f28a6b6eed5f7ccdd3193c6d102f60a9716870bf4f48bec1e50', 'ur', 'Women should observe full, loose, modest covering (hijab) before non-mahram.', 'عورتیں غیر محرم کے سامنے مکمل، ڈھیلا اور باحیا پردہ (حجاب) کریں۔'),
  ('7f6b0ec80179ec53dcf0d1024134be4b8c2fa645a9c518c7e543fd0fff78f09e', 'ur-roman', 'Women should observe full, loose, modest covering (hijab) before non-mahram.', 'auratein ghair-mehram ke saamne mukammal, dheela aur ba-haya parda (hijab) karein.'),
  ('e33d5417c27f6517ff7850a03d2bd0822126a6eb7fafff178e2be1f2adaeb0d8', 'ur', 'Dress modestly and cleanly; avoid imitating the opposite gender.', 'باحیا اور صاف ستھرا لباس پہنیں؛ مخالف جنس کی مشابہت سے بچیں۔'),
  ('bfd7bd2504bdd5d51dda86662eb258f33d767066f9caa9c9ce86c1731ba5c8cf', 'ur-roman', 'Dress modestly and cleanly; avoid imitating the opposite gender.', 'ba-haya aur saaf suthra libaas pehnein; mukhaalif jins ki mushabahat se bachein.'),
  ('2b1454fb990a229ad417261e6684300c432d9178746f4d5db9fc391adf75b73c', 'ur', 'Always keep the awrah covered — men from navel to knee, women all but the face and hands.', 'ستر ہمیشہ ڈھکا رکھیں — مرد ناف سے گھٹنے تک، عورتیں چہرے اور ہاتھوں کے سوا سب کچھ۔'),
  ('2b4f5c1569b18377318f6a5277efd0fdbe00e7cf2f97fc0eea11afc92c374cc1', 'ur-roman', 'Always keep the awrah covered — men from navel to knee, women all but the face and hands.', 'satar hamesha dhaka rakhein — mard naaf se ghutne tak, auratein chehre aur haathon ke siwa sab kuch.'),
  ('295b8a248fc8d9331fd440a472586a1e7eccf4a112480cbee719bfb2fd541b23', 'ur', 'White garments are recommended, and keep clothes clean.', 'سفید کپڑے پہننا پسندیدہ ہے، اور کپڑے صاف رکھیں۔'),
  ('820cd3299dd36ff31f6d38f474114848f12f4c17028dcd755e7e738aaaf9531e', 'ur-roman', 'White garments are recommended, and keep clothes clean.', 'safed kapde pehanna pasandeeda hai, aur kapde saaf rakhein.'),
  ('e89d0f06bf407d4bc6c6b10d16ec559b8eba7fd0ed6b5e1b5c984c9970f44d1e', 'ur', 'Avoid clothing worn for fame or show (libas ash-shuhrah).', 'شہرت یا دکھاوے کے لیے پہنا جانے والا لباس (لباسِ شہرت) نہ پہنیں۔'),
  ('f5eceb5455eb87e4db922c6d5e9347514ba7eddbde618a5fc9229a4fa7692a18', 'ur-roman', 'Avoid clothing worn for fame or show (libas ash-shuhrah).', 'shohrat ya dikhawe ke liye pehna jane wala libaas (libaas-e-shuhrat) mat pehnein.'),
  ('e8c7832d0653c1bf9cff027b4c5aa7607eccffe4f6b219aff1a57d17c74101b5', 'ur', 'Wear both shoes or neither; put on the right first, take off the left first.', 'یا تو دونوں جوتے پہنیں یا کوئی نہیں؛ پہلے دایاں پہنیں، پہلے بایاں اتاریں۔'),
  ('3034749bbb783a1eead6f3eb1ca154f5ef8880c27f6fc45342a1661d0adac69a', 'ur-roman', 'Wear both shoes or neither; put on the right first, take off the left first.', 'ya to dono joote pehnein ya koi nahin; pehle daya pehnein, pehle baya utaarein.'),
  ('b83145c23f88e8a82bd06b23224c654185dd68cfae48f6f7be4b55eecaf0e3d4', 'ur', 'Women must not wear tight, transparent clothing, nor perfume before non-mahram.', 'عورتیں تنگ یا باریک کپڑے نہ پہنیں، اور غیر محرم کے سامنے خوشبو نہ لگائیں۔'),
  ('99bb72df9c7142788c13e036af9c2a552c37e264d7e0430157be6399caabd31b', 'ur-roman', 'Women must not wear tight, transparent clothing, nor perfume before non-mahram.', 'auratein tang ya bareek kapde mat pehnein, aur ghair-mehram ke saamne khushbu mat lagayein.'),
  ('7ddaaf422b51eaf6811647404b644fdb04aa942eee8fc71824ce89a177936bd3', 'ur', 'Men should keep the beard and trim the moustache (fitrah).', 'مرد داڑھی رکھیں اور مونچھیں پست رکھیں (فطرت میں سے ہے)۔'),
  ('fdc916cb89a47e4b2d71163e4668fd80298ebfc2c5b4254646f8fd408770303a', 'ur-roman', 'Men should keep the beard and trim the moustache (fitrah).', 'mard daadhi rakhein aur moonchein pasht rakhein (fitrat me se hai).'),
  ('fe526f8fea03b593a2a68116799705489a4b24aade509d37bb82211ab163083c', 'ur', 'Recite the travel du’a when setting out: “Subhanal-ladhi sakhkhara lana hadha…”.', 'روانہ ہوتے وقت سفر کی دعا پڑھیں: “Subhanal-ladhi sakhkhara lana hadha…”۔'),
  ('02bd01ee5089b654bd282403afc54fc3539a4a4ad59903ae564d11dc6ab3a73b', 'ur-roman', 'Recite the travel du’a when setting out: “Subhanal-ladhi sakhkhara lana hadha…”.', 'rawana hote waqt safar ki dua padhein: “Subhanal-ladhi sakhkhara lana hadha…”.'),
  ('53430901f55439d47282809e0acaed7d14016f0391b7d83e6edcde21169f8fde', 'ur', 'Say “Allahu Akbar” when going up an incline and “Subhanallah” when going down.', 'چڑھائی پر “Allahu Akbar” کہیں اور ڈھلان پر “Subhanallah” کہیں۔'),
  ('7f2f85e01fdb15df1f6675dfc5024c731a7f87be8736fed6e95eeb28fff30c32', 'ur-roman', 'Say “Allahu Akbar” when going up an incline and “Subhanallah” when going down.', 'chadhai par “Allahu Akbar” kahein aur dhalaan par “Subhanallah” kahein.'),
  ('0ba71fd3b6796822bf26fb31cb8aeef8cffac94ccbc69071ea071c737581cf11', 'ur', 'Appoint a leader (amir) when three or more travel together.', 'جب تین یا زیادہ لوگ مل کر سفر کریں تو ایک امیر مقرر کریں۔'),
  ('c8aa1947639c6e5805e0b4972a5d14ac96208427b296dfa3376b1d14091662dd', 'ur-roman', 'Appoint a leader (amir) when three or more travel together.', 'jab teen ya zyada log mil kar safar karein to ek ameer muqarrar karein.'),
  ('e1e418e6419fae130386c9d9cfa5436124cb7404955f7c9359c253890cc2f637', 'ur', 'A traveller may shorten (qasr) the four-rak’ah fard to two.', 'مسافر چار رکعت فرض کو دو رکعت (قصر) کر سکتا ہے۔'),
  ('975e17ca49724268a3d15e47d3ba5268b6a7a6ef38e0d25365faa5c3619e8db8', 'ur-roman', 'A traveller may shorten (qasr) the four-rak’ah fard to two.', 'musafir chaar rakat farz ko do rakat (qasr) kar sakta hai.'),
  ('9e47d36b5f793414e34c8a6e4ee60c395c7949e0402786b624319ceedb0c8084', 'ur', 'Seek Allah’s protection and return promptly to the family once the need is met.', 'اللہ سے حفاظت مانگیں اور کام پورا ہوتے ہی جلد گھر والوں کے پاس لوٹ آئیں۔'),
  ('a8526a75027f3447b2f7767a5c91a91b7b899e7283aa842a2339cc62308929a9', 'ur-roman', 'Seek Allah’s protection and return promptly to the family once the need is met.', 'Allah se hifazat maangein aur kaam poora hote hi jald ghar walon ke paas laut aayein.'),
  ('565f81fcdedea4f346ea4d5d5a2b9f96d1a68d3d083d67d2cf74b0f74d693024', 'ur', 'Travel in company; a single rider is a devil, two are devils, three are a travelling party.', 'ساتھ مل کر سفر کریں؛ اکیلا سوار شیطان ہے، دو شیطان ہیں، اور تین ایک قافلہ ہیں۔'),
  ('f006ab9a542163311c32e625d38df2a22f5aa34c7ea458db44b9a9f72f7ac4ea', 'ur-roman', 'Travel in company; a single rider is a devil, two are devils, three are a travelling party.', 'saath mil kar safar karein; akela sawar shaytan hai, do shaytan hain, aur teen ek qafila hain.'),
  ('c4ca5d5cab583f6220a56e3bad3a0b148ea2e0aa639a7d4bbe427019f99a4062', 'ur', 'When three set out, they should appoint one of them as amir (leader).', 'جب تین لوگ نکلیں تو ان میں سے ایک کو امیر مقرر کر لیں۔'),
  ('1bf9b4befc8d215ca59e1bd9b34a7a8549550593153121c739216d58b3ddb2c3', 'ur-roman', 'When three set out, they should appoint one of them as amir (leader).', 'jab teen log niklein to un me se ek ko ameer muqarrar kar lein.'),
  ('4bf4e2aaaf3cf49673ed113472c270877241404f636a930577c5e8905fad821b', 'ur', 'Make plentiful du’a — the traveller’s supplication is accepted.', 'کثرت سے دعا کریں — مسافر کی دعا قبول ہوتی ہے۔'),
  ('6d9db0ff723d16ea32a24d43ec5321eca1dc192db35304057b83a1522ba96b57', 'ur-roman', 'Make plentiful du’a — the traveller’s supplication is accepted.', 'kasrat se dua karein — musafir ki dua qabool hoti hai.'),
  ('6df4daa9ffa5d242ed2e244b25dd95ab092c8bdf7dc401b04b38634c7ab295c7', 'ur', 'Bid farewell to loved ones: “Astawdi‘ullaha dinaka wa amanataka wa khawatima ‘amalika”.', 'اپنے پیاروں کو رخصت کرتے وقت کہیں: “Astawdi‘ullaha dinaka wa amanataka wa khawatima ‘amalika”۔'),
  ('53ba7db7c85b5032543cd72f51bfd05db4c7f65ae3f4ddf03583424b1189c634', 'ur-roman', 'Bid farewell to loved ones: “Astawdi‘ullaha dinaka wa amanataka wa khawatima ‘amalika”.', 'apne pyaron ko rukhsat karte waqt kahein: “Astawdi‘ullaha dinaka wa amanataka wa khawatima ‘amalika”.'),
  ('df12bf6f1cc312d9399dd6d06b3231f4031c0c62b4f6b942dbe12ad2fa0011ec', 'ur', 'A traveller may combine and shorten prayers as permitted.', 'مسافر اجازت کے مطابق نمازیں جمع اور قصر کر سکتا ہے۔'),
  ('6040d4362c3affcc55e8bb59547cd84f34a0d6dfb5f196fa768185cd48135b8e', 'ur-roman', 'A traveller may combine and shorten prayers as permitted.', 'musafir ijaazat ke mutabiq namazein jama aur qasr kar sakta hai.'),
  ('6e53c7f9e2f50c835e013a104173c15b2f729880cc9ad9c65e13bbe83ef6641b', 'ur', 'On returning, it is Sunnah to first go to the masjid and pray two rak’ah.', 'واپسی پر سنت یہ ہے کہ پہلے مسجد جا کر دو رکعت پڑھیں۔'),
  ('3c301a5712eb6b4a8ba6e117980b534a57629411944ed0758033ab77c7d2d43b', 'ur-roman', 'On returning, it is Sunnah to first go to the masjid and pray two rak’ah.', 'wapsi par sunnat yeh hai ke pehle masjid ja kar do rakat padhein.'),
  ('7e6e3e802d5a81fc095d91861f93910b6491c962107ca8bd8d53e8c82a983e20', 'ur', 'Do not arrive home unannounced late at night.', 'رات گئے بغیر اطلاع کے گھر نہ پہنچیں۔'),
  ('450b12c78b42d525c0ce1afa469c32bd3b073d4b9d3987b7d2bbdc4afe5851b3', 'ur-roman', 'Do not arrive home unannounced late at night.', 'raat gaye bagair ittila ke ghar mat pahunchein.'),
  ('d011c5c6872d54e0a720d503c3fd123f03ba15b58583e2a8ecb268a5670515ea', 'ur', 'Give salam when arriving at a gathering and when leaving it.', 'مجلس میں پہنچتے وقت اور جاتے وقت سلام کریں۔'),
  ('d096dd2561e091037b1ac502a0478f4a45ccf1fc0a5867016893b002e715b1e8', 'ur-roman', 'Give salam when arriving at a gathering and when leaving it.', 'majlis me pahunchte waqt aur jaate waqt salam karein.'),
  ('598e94ec5c707eeabeaba77a16e1f0ebf59d0cd439d51131ec4110c29b425b50', 'ur', 'Make room for others; do not make anyone rise to take his seat.', 'دوسروں کے لیے جگہ بنائیں؛ کسی کو اٹھا کر اس کی جگہ نہ بیٹھیں۔'),
  ('4be5035fa953d05b7fccf607515549b49c0a11a958da04b97d92d449bd842e50', 'ur-roman', 'Make room for others; do not make anyone rise to take his seat.', 'doosron ke liye jagah banayein; kisi ko utha kar uski jagah mat baithein.'),
  ('62fc421d2a6da0b47592aa88b753ff9d3ec06a365720a114b0ea40b8ae46ba7e', 'ur', 'Sit where there is space; do not sit between two people without their permission.', 'جہاں جگہ ہو وہاں بیٹھیں؛ دو آدمیوں کے درمیان ان کی اجازت کے بغیر نہ بیٹھیں۔'),
  ('42b8534768ec3ac8ada98abe4d17b2f82a41d32a6824ada12100dec3c30938d1', 'ur-roman', 'Sit where there is space; do not sit between two people without their permission.', 'jahan jagah ho wahan baithein; do aadmiyon ke darmiyaan unki ijaazat ke bagair mat baithein.'),
  ('e0f818ac341700462ef419a02c91e4b4fa6d4a74e5407aaffab1380df4807ef1', 'ur', 'Do not whisper between two people while excluding a third.', 'تیسرے کو چھوڑ کر دو آدمی آپس میں سرگوشی نہ کریں۔'),
  ('21ebc6129b280f8a26e0b25f8468c50cdd04db55d3896bd50a9d50c473f606f3', 'ur-roman', 'Do not whisper between two people while excluding a third.', 'teesre ko chhod kar do aadmi aapas me sargoshi mat karein.'),
  ('25506afb389a9a050adeda1f42f326d4d5b5c9281bc8c100d187d6fdc4ee6e59', 'ur', 'Speak good or remain silent; avoid backbiting and idle talk.', 'اچھی بات کریں یا خاموش رہیں؛ غیبت اور فضول باتوں سے بچیں۔'),
  ('e1398c41aba685e8a6271c78fedc54b3e090d5aeb4f0f4773ffa1e8497b854ee', 'ur-roman', 'Speak good or remain silent; avoid backbiting and idle talk.', 'achhi baat karein ya khamosh rahein; gheebat aur fizool baaton se bachein.'),
  ('c74ee90cd5c32b79f899111b93ca94b99580c68d8b6a4dae5972ba2216bb2a0c', 'ur', 'Lower the gaze and be humble; do not dominate the gathering.', 'نظریں نیچی رکھیں اور عاجزی اختیار کریں؛ مجلس پر چھا جانے کی کوشش نہ کریں۔'),
  ('3f6c99ff458a204431e085ab2be285059999bb36168f2f5c9911a16887774762', 'ur-roman', 'Lower the gaze and be humble; do not dominate the gathering.', 'nazrein neechi rakhein aur aajizi ikhtiyaar karein; majlis par chha jane ki koshish mat karein.'),
  ('27de93435e7f6667f71bfae7b4a869362329a09591857f07d8f931b3341310a4', 'ur', 'Recite the du’a on leaving (kaffarah al-majlis): “Subhanaka Allahumma wa bihamdika, ash-hadu an la ilaha illa anta, astaghfiruka wa atubu ilayk”.', 'اٹھتے وقت مجلس کی دعا (کفارۃ المجلس) پڑھیں: “Subhanaka Allahumma wa bihamdika, ash-hadu an la ilaha illa anta, astaghfiruka wa atubu ilayk”۔'),
  ('33af716f8cd07b442fb7f724822fd37632d5f2ee0c7c345fc9e99dd679786410', 'ur-roman', 'Recite the du’a on leaving (kaffarah al-majlis): “Subhanaka Allahumma wa bihamdika, ash-hadu an la ilaha illa anta, astaghfiruka wa atubu ilayk”.', 'uthte waqt majlis ki dua (kaffara-tul-majlis) padhein: “Subhanaka Allahumma wa bihamdika, ash-hadu an la ilaha illa anta, astaghfiruka wa atubu ilayk”.'),
  ('68d696277c005a8a66fe4917a446c4daa5f2799330549312c4bc7504260270b2', 'ur', 'Honour the guest and the elder; begin serving from the right.', 'مہمان اور بزرگ کی عزت کریں؛ خدمت دائیں طرف سے شروع کریں۔'),
  ('b9d9d6f0da569e1d6e158416c7cd337490389e0e661ccf7a01606699cc6c7e7a', 'ur-roman', 'Honour the guest and the elder; begin serving from the right.', 'mehmaan aur buzurg ki izzat karein; khidmat dayein taraf se shuru karein.'),
  ('976a82a557ce8b402a4e647b6ec1cdaaf1ca81c7fc8e515a96ddf9b7e03bb9fe', 'ur', 'Be kind and obedient to parents; lower the wing of humility to them.', 'والدین کے ساتھ نرمی اور فرمانبرداری کریں؛ ان کے سامنے عاجزی سے جھکے رہیں۔'),
  ('d7176d52396bff6b138b5903afa170be35dd9229fc85872d9fbdb05d75ec7b31', 'ur-roman', 'Be kind and obedient to parents; lower the wing of humility to them.', 'walidain ke saath narmi aur farmabardaari karein; unke saamne aajizi se jhuke rahein.'),
  ('6dfada1ad77567ebe4870290c6c87bd39976a59acfd2d75c3ac731a3e11b699a', 'ur', 'Never say “uff” to them nor rebuke them; speak a gracious word.', 'ان کو کبھی “اُف” تک نہ کہیں اور نہ جھڑکیں؛ ان سے نرم اور عزت والی بات کریں۔'),
  ('f888278b6c1df7d80853f72e74c9f4af887f288e081cc857556d699b2afac9aa', 'ur-roman', 'Never say “uff” to them nor rebuke them; speak a gracious word.', 'unko kabhi “uff” tak mat kahein aur na jhidkein; unse naram aur izzat wali baat karein.'),
  ('705792bdac3dd4e07f4d556599b01a97d8e99490aa695ae99bd989b3de8f5254', 'ur', 'Seek their pleasure — Allah’s pleasure lies in the pleasure of the parents.', 'ان کی رضا حاصل کریں — اللہ کی رضا والدین کی رضا میں ہے۔'),
  ('bdd592248b4718b029db1cbf20da5064799052dec69f4d53a49a2336c669aa60', 'ur-roman', 'Seek their pleasure — Allah’s pleasure lies in the pleasure of the parents.', 'unki raza haasil karein — Allah ki raza walidain ki raza me hai.'),
  ('0cae3ee533bb1f4d40b83a29f3ed71adf11b648b11b5e5657ee7e63e76da2022', 'ur', 'Serve them, spend on them, and make du’a: “Rabbir-hamhuma kama rabbayani saghira”.', 'ان کی خدمت کریں، ان پر خرچ کریں، اور دعا کریں: “Rabbir-hamhuma kama rabbayani saghira”۔'),
  ('1b854fee1be26677d2b7c03f33034765751184f5b9ba9713c7a070777589de97', 'ur-roman', 'Serve them, spend on them, and make du’a: “Rabbir-hamhuma kama rabbayani saghira”.', 'unki khidmat karein, un par kharch karein, aur dua karein: “Rabbir-hamhuma kama rabbayani saghira”.'),
  ('e978e25c1e9d746c981da4df46593c9d9af62e873aa5ce5ff892ba21d497ee85', 'ur', 'Respect elders and show mercy to the young.', 'بڑوں کی عزت کریں اور چھوٹوں پر شفقت کریں۔'),
  ('9101a8d5caca087ff568ce803ac254613d8bc6f5f9dbc624bffa25762a5b0209', 'ur-roman', 'Respect elders and show mercy to the young.', 'badon ki izzat karein aur chhoton par shafqat karein.'),
  ('8de0ff08fbcce5df1821dfaa54eae3f0defcfecc488449e0a2209b2430988075', 'ur', 'Maintain kindness after their death — du’a, charity, and keeping ties with their friends.', 'ان کی وفات کے بعد بھی حسن سلوک جاری رکھیں — دعا، صدقہ، اور ان کے دوستوں سے تعلق نبھانا۔'),
  ('bbb69d56ea553e3fa8558d8068a93cad5961cf9c6c2e30823ec0b4d49ec2e181', 'ur-roman', 'Maintain kindness after their death — du’a, charity, and keeping ties with their friends.', 'unki wafat ke baad bhi husn-e-sulook jari rakhein — dua, sadqa, aur unke doston se taalluq nibhana.'),
  ('5fa9530c741aa0a6e4fa34970fb0f4ae674fb3ec26788d292858f1d739d07ac0', 'ur', 'Keep ties of kinship (silah rahm); do not sever relations.', 'صلہ رحمی قائم رکھیں؛ رشتہ داری نہ توڑیں۔'),
  ('4eff354f242e3e0d68bf45152817a00e4659046e09c8496ae99c7ebf69e06165', 'ur-roman', 'Keep ties of kinship (silah rahm); do not sever relations.', 'sila-rehmi qaim rakhein; rishtedaari mat todein.'),
  ('84f6fd00aeb72f8c60bf4c837db9c1f193025ae49a41d39c670ed627341b1d61', 'ur', 'Whoever believes in Allah and the Last Day, let him speak good or remain silent.', 'جو اللہ اور آخرت کے دن پر ایمان رکھتا ہے وہ اچھی بات کہے یا خاموش رہے۔'),
  ('650c56583310b20bbc6ea42feca62a8f6314a883194eb0f90ddcadf607b6adb3', 'ur-roman', 'Whoever believes in Allah and the Last Day, let him speak good or remain silent.', 'jo Allah aur aakhirat ke din par imaan rakhta hai wo achhi baat kahe ya khamosh rahe.'),
  ('c293e94ecffdc8bed4e09a1e1e43304bc98c8e618ae9629f66b28a5c1f3ac41c', 'ur', 'Be truthful; truthfulness leads to righteousness and to Paradise.', 'سچ بولیں؛ سچائی نیکی کی طرف اور جنت کی طرف لے جاتی ہے۔'),
  ('62fbf5dc8c030e2c6a4c79fd37b583189c137d9b8f249827b946d2ed473f1aa2', 'ur-roman', 'Be truthful; truthfulness leads to righteousness and to Paradise.', 'sach bolein; sachai neki ki taraf aur jannat ki taraf le jaati hai.'),
  ('7156f2c32f303e9cbe58d08362dd1fd9974ecabbd235585ad73b57e4e93f6976', 'ur', 'Avoid backbiting (gheebah) and tale-carrying (nameemah).', 'غیبت اور چغل خوری (نمیمہ) سے بچیں۔'),
  ('76d2d8c9ff7ee71c8ae9acc000023a75fc47f679c5b35ad9d00617553c880777', 'ur-roman', 'Avoid backbiting (gheebah) and tale-carrying (nameemah).', 'gheebat aur chughal-khori (nameema) se bachein.'),
  ('e7548f015fe95b1a7c9b1d1f82bd6e5b3ad981b0647f1135720ee8c8053429b7', 'ur', 'Lower your voice; the harshest of voices is the braying of a donkey.', 'اپنی آواز پست رکھیں؛ سب سے بری آواز گدھے کی آواز ہے۔'),
  ('b4248aeab62b0e6b7e81faea104aa20a61715df729ac44063c5df54d5a78ef05', 'ur-roman', 'Lower your voice; the harshest of voices is the braying of a donkey.', 'apni awaz pasht rakhein; sab se buri awaz gadhe ki awaz hai.'),
  ('bbac9697445f5f4dffc64c7c61290a0b333a35c6ed207d20f18d215f2433e196', 'ur', 'Do not argue even when you are right; abandon lying even in jest.', 'حق پر ہوتے ہوئے بھی جھگڑا نہ کریں؛ مذاق میں بھی جھوٹ چھوڑ دیں۔'),
  ('463bfdb067f25d48e2c0ab4d3487d4f1d32f20288cb07aeb2db4bf3d845428de', 'ur-roman', 'Do not argue even when you are right; abandon lying even in jest.', 'haq par hote hue bhi jhagda mat karein; mazaq me bhi jhoot chhod dein.'),
  ('24cc4c8fa563e1a9fd9f58814af76ee6d61dc025a189a6071fb0ec7ca94b02f2', 'ur', 'Fulfil promises and speak with justice, even against oneself.', 'وعدے پورے کریں اور انصاف کی بات کریں، چاہے اپنے ہی خلاف ہو۔'),
  ('20e03f953a25a31e75bcd3da4aabfd2b0b8cbd856895b31054771208fb99df3a', 'ur-roman', 'Fulfil promises and speak with justice, even against oneself.', 'waade poore karein aur insaaf ki baat karein, chahe apne hi khilaf ho.'),
  ('47ebd65782e4edc9b102cb464adecc1e47378400b213cdcbaa1d7189108d38c2', 'ur', 'Do not mock, insult, or call others by offensive nicknames.', 'کسی کا مذاق نہ اڑائیں، گالی نہ دیں، اور برے القاب سے نہ پکاریں۔'),
  ('c95890b8e0607bfe8db0b5422849c2f4972c93f6e333a3d8164681c596704084', 'ur-roman', 'Do not mock, insult, or call others by offensive nicknames.', 'kisi ka mazaq mat udayein, gaali mat dein, aur bure alqaab se mat pukarein.'),
  ('c9661d4c41c4e76c381816e9f16fe0edfc9b6a14143ab1592893c37f2d8bad06', 'ur', 'Cleanse the heart from spiritual diseases — anger, jealousy, pride and more. Tap a scholar to watch their talks and shorts on each topic.', 'دل کو روحانی بیماریوں سے پاک کریں — غصہ، حسد، تکبر اور دیگر۔ ہر موضوع پر کسی عالم کے بیانات اور شارٹس دیکھنے کے لیے ان پر ٹیپ کریں۔'),
  ('d33a9165d37adcbb5879cbb90927dd22b99a2bc481c40067327e4038bc7e92a8', 'ur-roman', 'Cleanse the heart from spiritual diseases — anger, jealousy, pride and more. Tap a scholar to watch their talks and shorts on each topic.', 'dil ko roohani bimaariyon se paak karein — gussa, hasad, takabbur aur deegar. har mauzoo par kisi aalim ke bayanaat aur shorts dekhne ke liye un par tap karein.'),
