  ('8146f7921c26feea92f1d1ee227b288cf80da574ab4ebdadc415784ff1dad913', 'ur', 'Things that do NOT break the fast', 'وہ چیزیں جو روزہ نہیں توڑتیں'),
  ('00c60e81cd6b3764d37331aba87d59668bd1344993814ccd4bb8f7584d0d3a51', 'ur-roman', 'Things that do NOT break the fast', 'wo cheezein jo roza nahin todtein'),
  ('37acb546658c6a0f489a650d6c0a731d688e5c17b2c30b5a7090b6b5ed89e721', 'ur', 'Sunnah & Mustahab', 'سنت اور مستحب'),
  ('669c5256ff3d5373f06a0d31f825d1600e04f910535dc5a3d012d1a803030771', 'ur-roman', 'Sunnah & Mustahab', 'sunnat aur mustahab'),
  ('006d7b0fcd6d308962c36992b4b7e04adde2c06faf6a36822ddf8cf43f751a37', 'ur', 'Who may leave the fast (with qada / fidyah)', 'کون روزہ چھوڑ سکتا ہے (قضا / فدیہ کے ساتھ)'),
  ('37ccf123b179a9345e0ee87c034acae1ac115c56e62c30f00c718c12cb0f73eb', 'ur-roman', 'Who may leave the fast (with qada / fidyah)', 'kaun roza chhod sakta hai (qaza / fidya ke saath)'),
  ('a6ef40a13c796eec6ae3f88ada1dedd910106e36389710bef1ed509b0a844375', 'ur', 'Wajibat', 'واجبات'),
  ('d897225614300480beb203a6fa6b743ba41704d18984c0a57162fbab168b369b', 'ur-roman', 'Wajibat', 'wajibaat'),
  ('ada370517ab16ecf5c6efcd8559f14b9a6b6a0f6036020d788a4f50b0ca477d3', 'ur', 'Types of Hajj', 'حج کی اقسام'),
  ('06e9f8ccb529e597426d2b73c99827e105a294a7f0aa69c9ba9f3c4ba7f1f360', 'ur-roman', 'Types of Hajj', 'Hajj ki aqsaam'),
  ('235579310130231d3ecc396dbf6699825cd083cd6081c10b76cdba7e8676e458', 'ur', 'Prohibitions in Ihram', 'احرام میں ممنوعات'),
  ('29667532b631db1f7e45f44719eb30913e95a2cd895e9451356967ab6fc014f4', 'ur-roman', 'Prohibitions in Ihram', 'ehraam me mamnooaat'),
  ('03b604bc8b0a2f789fea574b59565dad13eb4baa5e66345eef89055e41264283', 'ur', 'Wash the whole face once — from the top of the forehead (hairline) to the bottom of the chin, and from one earlobe to the other.', 'پورا چہرہ ایک بار دھونا — پیشانی کے بالوں کی جڑ سے ٹھوڑی کے نیچے تک، اور ایک کان کی لو سے دوسری تک۔'),
  ('736c764a34e53d77516db1eb6f4e79d0f7157e3fc2adbf92cd9367e3232c63d0', 'ur-roman', 'Wash the whole face once — from the top of the forehead (hairline) to the bottom of the chin, and from one earlobe to the other.', 'poora chehra ek baar dhona — peshani ke baalon ki jad se thodi ke neeche tak, aur ek kaan ki lo se doosri tak.'),
  ('4e6b4b1ea18d0910b54d347bf07cddb792a329bc11b40763764c638f2bb304ce', 'ur', 'Wash both arms including the elbows once.', 'دونوں بازو کہنیوں سمیت ایک بار دھونا۔'),
  ('906d3cd328eac5ef0364b2b15385595d337a082bc9e33c8515990f37bad33569', 'ur-roman', 'Wash both arms including the elbows once.', 'dono baazu kohniyon samet ek baar dhona.'),
  ('3d132ae15372be70f65c5691daf49c3e9587613f1344ef9262a1edceb77e8101', 'ur', 'Wipe (masah) at least one-quarter of the head once.', 'سر کے کم از کم چوتھائی حصے کا ایک بار مسح کرنا۔'),
  ('66fe2b65be2d335fcc00279742c1d4a61dfe614439e5db3515bceee295659b87', 'ur-roman', 'Wipe (masah) at least one-quarter of the head once.', 'sar ke kam az kam chauthai hisse ka ek baar masah karna.'),
  ('9d56cea396bc755ce77f71c05d0c30e1f96e46fb5ff243606f59d27a5a60ae3e', 'ur', 'Wash both feet including the ankles once.', 'دونوں پاؤں ٹخنوں سمیت ایک بار دھونا۔'),
  ('35b90e11107ef1f10085bff5d03677c61e16bc04429aaf7ea7bb907513caeaa1', 'ur-roman', 'Wash both feet including the ankles once.', 'dono paon takhnon samet ek baar dhona.'),
  ('fc21a79d5f5e254bfbbbac2e0942e5609c8058e59fb67ca8bc16ce4bf53e244e', 'ur', 'Making the intention (niyyah) for wudu.', 'وضو کی نیت کرنا۔'),
  ('c932208c6c43bdde960b5ce7f21913b6aa53a49f87f726d4dbefb776dc48045a', 'ur-roman', 'Making the intention (niyyah) for wudu.', 'wuzu ki niyyat karna.'),
  ('776c44eeed97889a89442efc27565ff532c1890a49039ddfb7ef6cc7f9e50dbc', 'ur', 'Saying Bismillah at the beginning.', 'شروع میں بسم اللہ کہنا۔'),
  ('7f31e1004d3e363e13f11974926259c0910ceeb5ef541d2521e8b3695762ddb9', 'ur-roman', 'Saying Bismillah at the beginning.', 'shuru me Bismillah kehna.'),
  ('380b569db8e1549b3e8abdcdbb04ea14813fba0d718444de0b16a2d72f8b5928', 'ur', 'Washing both hands up to the wrists three times at the start.', 'شروع میں دونوں ہاتھ گٹوں تک تین بار دھونا۔'),
  ('2456029eff506823039579dcdceb9b03059ae74577bc537add9bdc97d53e58d8', 'ur-roman', 'Washing both hands up to the wrists three times at the start.', 'shuru me dono haath gatton tak teen baar dhona.'),
  ('984e116eb3bc9fdf9a9124e44406d6b9d84ea842d11e22ef83688421bcbb88b6', 'ur', 'Using the miswak (or finger if unavailable).', 'مسواک کرنا (اور نہ ہو تو انگلی سے)۔'),
  ('f9fb91cbb25d846803d9dce64f2be0a8e0243685d2fe5199bf7ba4fa0477b95c', 'ur-roman', 'Using the miswak (or finger if unavailable).', 'miswak karna (aur na ho to ungli se).'),
  ('07b945296d4aee2097c305149340527f3912d326e6b0be16ea1be6d88a90e3ac', 'ur', 'Rinsing the mouth three times (madmadah), gargling if not fasting.', 'منہ تین بار دھونا (مضمضہ)، اگر روزہ نہ ہو تو غرارہ کرنا۔'),
  ('415956f94623d3b17f0ab750c4cbe130a787af433b6050707e4bbd99a9581deb', 'ur-roman', 'Rinsing the mouth three times (madmadah), gargling if not fasting.', 'munh teen baar dhona (madmadah), agar roza na ho to gharara karna.'),
  ('9f7bc0de83a61dc7cd2dd8635091ae19dd7f67240f29be960ba038be3ccd2029', 'ur', 'Sniffing water into the nose three times (istinshaq).', 'ناک میں تین بار پانی چڑھانا (استنشاق)۔'),
  ('930baa4af473019b851b946f7d20ebb15e236120e4afabd48a38bc1a8444a52e', 'ur-roman', 'Sniffing water into the nose three times (istinshaq).', 'naak me teen baar pani chadhana (istinshaq).'),
  ('f75744bff21a320426fad078ef5ee2ad4be7256760457b45cc356a9a9b8fdc59', 'ur', 'Khilal of the beard and between the fingers and toes.', 'داڑھی کا اور انگلیوں اور پاؤں کی انگلیوں کے درمیان خلال کرنا۔'),
  ('6e465adc697ecd2f2b68cb27d157e44de7593ff6c9ba06592381818b3cb6ed9d', 'ur-roman', 'Khilal of the beard and between the fingers and toes.', 'daadhi ka aur haath aur paon ki ungliyon ke darmiyaan khilal karna.'),
  ('25a852ba639c915c3a542bffbd0c83a69011242836813861952a7cb2d39ac756', 'ur', 'Washing each limb three times.', 'ہر عضو کو تین بار دھونا۔'),
  ('d93fbfd27d0a932c9d62815138570c9119d205bd3809f7062cc1a3272453352b', 'ur-roman', 'Washing each limb three times.', 'har uzuw ko teen baar dhona.'),
  ('d459f41dbdd06bef443efe03479ad9de183295fbd23bba8bb1a1a9096c031c5c', 'ur', 'Masah of the whole head once, then the ears (inside with index fingers, outside with thumbs).', 'پورے سر کا ایک بار مسح، پھر کانوں کا (اندر شہادت کی انگلیوں سے، باہر انگوٹھوں سے)۔'),
  ('0d9fc47f68077adaa38c53666969cf34e5fdbce0fb29eebd458485a401c25853', 'ur-roman', 'Masah of the whole head once, then the ears (inside with index fingers, outside with thumbs).', 'poore sar ka ek baar masah, phir kaanon ka (andar shahadat ki ungliyon se, bahar angoothon se).'),
  ('7bdbce0f184941433c0d3537fce46b947f74de0ed51320874520bf9deb139d9f', 'ur', 'Maintaining the order (tartib) and washing continuously without pause (muwalat).', 'ترتیب برقرار رکھنا اور بغیر رکے مسلسل دھونا (موالات)۔'),
  ('4022ab6ba11d104d254bcefd46d19c56a4de4655eae6cf10f3e41f183501345b', 'ur-roman', 'Maintaining the order (tartib) and washing continuously without pause (muwalat).', 'tarteeb barqaraar rakhna aur bagair ruke musalsal dhona (muwalat).'),
  ('3b72edb658ce0b399d5cd9f1198ae4acf3f2c02eaa5a27e36a00652de9f4c0a0', 'ur', 'Beginning each limb from the right, then the left.', 'ہر عضو کو پہلے دائیں طرف سے، پھر بائیں طرف سے شروع کرنا۔'),
  ('b37c3783dc8b363c3b23744cb4be0141e23b7396740b65add96b8b01d0582673', 'ur-roman', 'Beginning each limb from the right, then the left.', 'har uzuw ko pehle dayein taraf se, phir bayein taraf se shuru karna.'),
  ('b6ef7f5754ce249a4248656eced073252c27c70c94b159e0c16e5762ecc37cb9', 'ur', 'Facing the Qibla during wudu.', 'وضو کے دوران قبلہ کی طرف رخ کرنا۔'),
  ('cb5a7d6f42d8190674210582f5f1d72a9da255ee356fa861af359215400a9e73', 'ur-roman', 'Facing the Qibla during wudu.', 'wuzu ke douran Qibla ki taraf rukh karna.'),
  ('bb7e2bc6cae63409c460064e36cfda72e353abe96596f32d13ce43754a89885d', 'ur', 'Performing wudu on a raised, clean place.', 'اونچی، صاف جگہ پر وضو کرنا۔'),
  ('79bb6d7c22ea34f56c5f7228d4eb37b0cbc42e013a6d202e46b150d9b934968b', 'ur-roman', 'Performing wudu on a raised, clean place.', 'oonchi, saaf jagah par wuzu karna.'),
  ('9a18f9baf7658d7ec91b287b93d52db7d7fe7b0c1eedc95cdbe59266c6cdba10', 'ur', 'Not taking help from others without need.', 'بلا ضرورت دوسروں سے مدد نہ لینا۔'),
  ('b045475a930cb5513b8ae4c7883ee7fad527e0ae657cb00ffaf348e45247b04e', 'ur-roman', 'Not taking help from others without need.', 'bila zaroorat doosron se madad na lena.'),
  ('b1cfe3db3ca6beb921d8814fe3c511a367a3671df9f7bcd7af6dd8c477d0f21b', 'ur', 'Reciting the Kalimah Shahadah and the du’a after wudu.', 'وضو کے بعد کلمہ شہادت اور دعا پڑھنا۔'),
  ('92dcad2b8b461614988023a8b22774438cbb711b5018363e455b04db735daf22', 'ur-roman', 'Reciting the Kalimah Shahadah and the du’a after wudu.', 'wuzu ke baad kalima shahadat aur dua padhna.'),
  ('f50eb9c91ae338e2dbcb805b453350a629beeacff4d8d764b9fade71ef98dd4f', 'ur', 'Not wasting water, even at a flowing river.', 'پانی ضائع نہ کرنا، چاہے بہتی نہر ہی پر کیوں نہ ہو۔'),
  ('83228bf235bbe711ba9a7ce70958c376c55085b2cb00438b6d9d81c6c9db5add', 'ur-roman', 'Not wasting water, even at a flowing river.', 'pani zaya na karna, chahe behti nahar hi par kyun na ho.'),
  ('a2dc8aad6eabd1786b76579160037f354913d6373fb92724e32e142c3f4803ff', 'ur', 'Wasting water or using excessively little.', 'پانی ضائع کرنا یا حد سے کم استعمال کرنا۔'),
  ('dd794f67e5725b61bebbbd746692c2212e8e357a19dabc1aa0ffc8312032c524', 'ur-roman', 'Wasting water or using excessively little.', 'pani zaya karna ya had se kam istemaal karna.'),
  ('4c2f5693ff49d4b60a26bd91c6e10a3be84874d93602c442ea6ab91eb3438c89', 'ur', 'Splashing water on the face forcefully.', 'چہرے پر زور سے پانی مارنا۔'),
  ('19c0acbffe6b6741cc4c7c3b8de787aff530cd04324a59ec137d59764d636f08', 'ur-roman', 'Splashing water on the face forcefully.', 'chehre par zor se pani maarna.'),
  ('1a54a6e3bd26c5958a8a963131e6d7b07180b0905e07989639a31a4dcc6c10d6', 'ur', 'Talking unnecessary worldly talk during wudu.', 'وضو کے دوران فضول دنیاوی باتیں کرنا۔'),
  ('2344aaa1831605914404070ab66cc9ba9040ad16ef8ba8715cd017c6b8d75e56', 'ur-roman', 'Talking unnecessary worldly talk during wudu.', 'wuzu ke douran fizool duniyavi baatein karna.'),
  ('a216ce885b1bb2b335524a15c2a56824d62974f13e3c52a157b86ce9d100fc17', 'ur', 'Performing wudu in an impure place.', 'ناپاک جگہ پر وضو کرنا۔'),
  ('061dd0f952aecfbd6a557526c9d8b908b8f8012ee8675e6e2a7675b40f2347bc', 'ur-roman', 'Performing wudu in an impure place.', 'napaak jagah par wuzu karna.'),
  ('f48105cbfe5440dc3027c29ddbaeed392de54f37d280dcfe195161034dd06a2b', 'ur', 'Anything exiting from the front or back passage — urine, stool, wind.', 'آگے یا پیچھے کے راستے سے کسی چیز کا نکلنا — پیشاب، پاخانہ، ہوا۔'),
  ('52437fd4954c4b65dc8a5be3703501cc61baf421782236a30f601cb341f4a253', 'ur-roman', 'Anything exiting from the front or back passage — urine, stool, wind.', 'aage ya peeche ke raaste se kisi cheez ka nikalna — peshab, pakhana, hawa.'),
  ('292218ab226fa67547c98afb890790f0693dfa90d7bf0915f7afa13ed8312e10', 'ur', 'Flowing blood, pus or fluid from a wound or the body.', 'زخم یا جسم سے خون، پیپ یا پانی کا بہنا۔'),
  ('06b143edd41820ebd580e98f32d7efffdb8987877843e4ed1684166667ceafdf', 'ur-roman', 'Flowing blood, pus or fluid from a wound or the body.', 'zakhm ya jism se khoon, peep ya pani ka behna.'),
  ('0a76a0bff335f48b00a14c9f6570efad0ce093d572b69ff1a8a5f18b83502718', 'ur', 'Vomiting a mouthful (of food, water, bile or blood).', 'منہ بھر کر قے آنا (کھانا، پانی، صفرا یا خون)۔'),
  ('d79e430bd127103a7dfe9f18dd8e5c8c35a54a37bf6cdf0c06dd344f2bcd8a89', 'ur-roman', 'Vomiting a mouthful (of food, water, bile or blood).', 'munh bhar kar qai aana (khana, pani, safra ya khoon).'),
  ('11a3fe8c367c7d7e0978dde61f1cd59a4f7b87f4e8761f8df3783f39bbbbaa6c', 'ur', 'Sleeping lying down or reclining against a support.', 'لیٹ کر یا کسی سہارے سے ٹیک لگا کر سونا۔'),
  ('859e75fa5227b854ee12f50c5e8bb405a005031a09641d12f2a93ffee4022578', 'ur-roman', 'Sleeping lying down or reclining against a support.', 'let kar ya kisi sahare se tek laga kar sona.'),
  ('aaf23010ed658cec0a7c759571d5aa06974f08fb098a5ff4b9d211520cd4b72e', 'ur', 'Losing consciousness through fainting, intoxication or insanity.', 'بے ہوشی، نشہ یا جنون کی وجہ سے ہوش کھو دینا۔'),
  ('8d385e94e67ea6410cc92e179c60bace897d19e67ff7bc9705cd7033850b5f26', 'ur-roman', 'Losing consciousness through fainting, intoxication or insanity.', 'be-hoshi, nasha ya junoon ki wajah se hosh kho dena.'),
  ('6b0fe1d230609daeffcb1efef35ddffe82fe245d3ea0a2e751177ef9a48d83ee', 'ur', 'Loud laughter (audible to oneself and neighbours) during a salah that has ruku and sujud — this breaks both the salah and the wudu.', 'ایسی نماز میں جس میں رکوع اور سجدہ ہو، قہقہہ لگانا (جو خود اور ساتھ والوں کو سنائی دے) — یہ نماز اور وضو دونوں توڑ دیتا ہے۔'),
  ('b100d1d6fc3cc9ae4ee3548f3d2c203b49069472308ff6bf00e67d5885684efb', 'ur-roman', 'Loud laughter (audible to oneself and neighbours) during a salah that has ruku and sujud — this breaks both the salah and the wudu.', 'aisi namaz me jis me ruku aur sajda ho, qehqaha lagana (jo khud aur saath walon ko sunai de) — yeh namaz aur wuzu dono tod deta hai.'),
  ('4f3e018722b7d9f6d309acd7d3a490ba9834d4990290deb9b9b39c1e0c6270d6', 'ur', 'Flow of mazi (pre-seminal fluid) or wadi.', 'مذی (شہوت کی رطوبت) یا ودی کا نکلنا۔'),
  ('6d9417d7e39dc962f9dff19257f45c12e1f9a5647723b34b027be0a327f5095e', 'ur-roman', 'Flow of mazi (pre-seminal fluid) or wadi.', 'mazi (shahwat ki rutoobat) ya wadi ka nikalna.'),
  ('7a98c1476a7f2863a851db8d15d69ce6246b688b43e20729d6b19151f7505d89', 'ur', 'A resident may wipe over valid leather socks for 24 hours, a traveller for 72 hours, counted from the first breaking of wudu after wearing them.', 'مقیم جائز چمڑے کے موزوں پر 24 گھنٹے اور مسافر 72 گھنٹے مسح کر سکتا ہے، جو موزے پہننے کے بعد پہلی بار وضو ٹوٹنے سے شمار ہوتے ہیں۔'),
  ('0785844d297140f08e1933e4dc72ede34e7a7f98f5a5e8f3c6417300cb1311f1', 'ur-roman', 'A resident may wipe over valid leather socks for 24 hours, a traveller for 72 hours, counted from the first breaking of wudu after wearing them.', 'muqeem jaiz chamde ke mozon par 24 ghante aur musafir 72 ghante masah kar sakta hai, jo moze pehanne ke baad pehli baar wuzu tootne se shumar hote hain.'),
  ('43f480c7d3f15194c0f9b062284efe33bce1940f276825daf8d2cf969232d472', 'ur', 'Condition: the socks were put on while in a state of wudu, cover the ankles, and are durable enough to walk in.', 'شرط: موزے وضو کی حالت میں پہنے گئے ہوں، ٹخنوں کو ڈھانپتے ہوں، اور اتنے مضبوط ہوں کہ ان میں چلا جا سکے۔'),
  ('bbbe8bcbd1588684bb9c8e670f4cd22e67fccb5230da00da13cf793e8e167b4a', 'ur-roman', 'Condition: the socks were put on while in a state of wudu, cover the ankles, and are durable enough to walk in.', 'shart: moze wuzu ki halat me pehne gaye hon, takhnon ko dhaanpte hon, aur itne mazboot hon ke un me chala ja sake.'),
  ('970429d2244c13aa2473cbf9b46d2f1947f13b709ecb005fc1d18d14e9af84ad', 'ur', 'Masah is done once over the top of each foot with wet fingers.', 'گیلی انگلیوں سے ہر پاؤں کے اوپر ایک بار مسح کیا جاتا ہے۔'),
  ('b0bd73f2d893663cd8df49882a4081d012f386ea8dee6772823f2a18544f2b12', 'ur-roman', 'Masah is done once over the top of each foot with wet fingers.', 'geeli ungliyon se har paon ke oopar ek baar masah kiya jata hai.'),
  ('db2154c116f8d1acc49b4a5ef56c0a813ec2602aedaa44d02b628e23c6b28b7e', 'ur', 'Masah is invalidated by anything that breaks wudu, by removing the socks, or by the time expiring.', 'مسح ہر اس چیز سے ٹوٹ جاتا ہے جو وضو توڑے، یا موزے اتارنے سے، یا مدت ختم ہونے سے۔'),
  ('35ce2e59f809b234f484a364694897017ca9eca81a844edd94dba217f317793f', 'ur-roman', 'Masah is invalidated by anything that breaks wudu, by removing the socks, or by the time expiring.', 'masah har us cheez se toot jata hai jo wuzu tode, ya moze utaarne se, ya muddat khatam hone se.'),
  ('2b66c38ebcf4846203b8274c2f9dd24208c1d4b31cc515419c21410cf35c2130', 'ur', 'Rinsing the whole mouth once so water reaches everywhere (gargle if not fasting).', 'پورے منہ کو ایک بار اس طرح دھونا کہ پانی ہر جگہ پہنچ جائے (روزہ نہ ہو تو غرارہ کریں)۔'),
  ('eb58d099693864337aea7c2295704b644849c69be8263de53bd847d677886789', 'ur-roman', 'Rinsing the whole mouth once so water reaches everywhere (gargle if not fasting).', 'poore munh ko ek baar is tarah dhona ke pani har jagah pahunch jaye (roza na ho to gharara karein).'),
  ('570ae4308ce6f2ba973d9936e5f43ef88ad43376827bc43b95c51ecbf53fbd24', 'ur', 'Sniffing water into the nose once, up to the soft bone.', 'ناک میں ایک بار نرم ہڈی تک پانی چڑھانا۔'),
  ('ebdc6e966b230d6b826ae6183eca6c32b4d18224e0a489a9b6eaefa540653b58', 'ur-roman', 'Sniffing water into the nose once, up to the soft bone.', 'naak ke narm haddi tak ek baar pani pahunchana.'),
  ('09740f6bd067e55e6631e2636de84b38d8238935045495104a2255ed8f19b99c', 'ur', 'Pouring water over the entire body once so that no spot — even a hair’s breadth — is left dry.', 'پورے جسم پر ایک بار اس طرح پانی بہانا کہ بال برابر جگہ بھی خشک نہ رہے۔'),
  ('b6c2772dc2982c8d9092e37949bac3894b80ebdf8ed79fa40b6e7e04fa406151', 'ur-roman', 'Pouring water over the entire body once so that no spot — even a hair’s breadth — is left dry.', 'poore jism par ek baar is tarah pani bahana ke baal barabar jagah bhi khushk na rahe.'),
  ('539330d526c697347d8ac1d6e01f01b927a50e6497ac5c88d3ed0eb669c89cb9', 'ur', 'After janabah — emission of semen with desire, or marital relations (even without emission).', 'جنابت کے بعد — شہوت کے ساتھ منی کا خارج ہونا، یا میاں بیوی کا ملاپ (خواہ انزال نہ ہو)۔'),
  ('f77e6301d3cae53eee860ff0c48e908c28bd2b9437cf4e6b1160d5aab56e8f3f', 'ur-roman', 'After janabah — emission of semen with desire, or marital relations (even without emission).', 'janabat ke baad — shahwat ke saath mani ka kharij hona, ya miyan biwi ka milaap (khwah inzaal na ho).'),
  ('51b0bb3e9306ee6bb9fcc9528e1049ee3ca8100207cee1705c2a0e1010e85fe5', 'ur', 'On seeing wetness (semen) after waking, i.e. a wet dream.', 'بیدار ہونے کے بعد تری (منی) دیکھنا، یعنی احتلام۔'),
  ('f2d7720704e5ef3788392de0291fea0567b44d061221efa61026a088290c7e5d', 'ur-roman', 'On seeing wetness (semen) after waking, i.e. a wet dream.', 'jaagne ke baad tari (mani) dekhna, yaani ehtelaam.'),
