  ('e5d5ba4da871cf31ba875a2db4cff27c13f35a78393384e70a4e06a0aa316a08', 'ur', 'Washing both hands up to the wrists.', 'دونوں ہاتھ گٹوں تک دھونا۔'),
  ('6c8d710d8793bc4ea66916c6d0d81a710f0cc1855b16f832f55896eaa8449597', 'ur-roman', 'Washing both hands up to the wrists.', 'dono haath gatton tak dhona.'),
