  ('840f89600af6266a6b798cfead1ac714892de56b6cd43b5ffed1c3091229c99b', 'ur', 'Rubbing the body with the hand each time.', 'ہر بار جسم کو ہاتھ سے ملنا۔'),
  ('c3672ed4bb9b066793fcdc2dd4acf135cefb2e4f5d6ed82bcb170a6bb4c962c4', 'ur-roman', 'Rubbing the body with the hand each time.', 'har baar jism ko haath se malna.'),
