  ('71e4ae7d3523ed6c884fd3cdeeb73b1484c71628f357050107795ac9a98d42a3', 'ur-roman', 'Wiping both arms up to and including the elbows.', 'dono baazuon ka kohniyon samet masah karna.'),
  ('a7967e42f149d250a14cff744cc6c99c4708105a820de243aea952e78b93cc60', 'ur', 'No water is available within roughly one mile.', 'تقریباً ایک میل کے اندر پانی دستیاب نہ ہو۔'),
  ('b2fca5b999a2938502d8995956ee479239a2fcdcec5dceb62e9b57ad2133e859', 'ur-roman', 'No water is available within roughly one mile.', 'taqreeban ek meel ke andar pani dastyaab na ho.'),
  ('19bc9bcf2b0256a428681d8bbe6dddb6ad46e12e12a25affb4d89e51d720fa69', 'ur', 'Illness or a wound where using water would cause harm or delay recovery.', 'ایسی بیماری یا زخم جہاں پانی استعمال کرنا نقصان دہ ہو یا شفا میں تاخیر کرے۔'),
  ('96cb0eacc2e31c4eb13ef517f784c98d0014b9f1b7439c8776fbc00ce39e61fa', 'ur-roman', 'Illness or a wound where using water would cause harm or delay recovery.', 'aisi bimaari ya zakhm jahan pani istemaal karna nuqsaan deh ho ya shifa me taakheer kare.'),
  ('b1d1f0d05d6a478c8344f21d81f0384d15a8197bb5dbda08a6a597f1f6525da2', 'ur', 'Water is present but is needed for drinking (self, others, or animals).', 'پانی موجود ہو مگر پینے کے لیے درکار ہو (خود، دوسروں، یا جانوروں کے لیے)۔'),
  ('900b622b45d03ca98b9643d1e27b1d114f6312baa23d3572d279b2235ab6a710', 'ur-roman', 'Water is present but is needed for drinking (self, others, or animals).', 'pani maujood ho magar peene ke liye darkaar ho (khud, doosron, ya jaanwaron ke liye).'),
  ('0bf20e499e0299d843e87f29ea534777ea5ee1bfe6c0b21885bc13b96d1e78d5', 'ur', 'Danger in reaching the water (enemy, beast, or fear of missing the funeral / Eid prayer with no time to make wudu).', 'پانی تک پہنچنے میں خطرہ ہو (دشمن، درندہ، یا جنازہ / عید کی نماز چھوٹ جانے کا اندیشہ اور وضو کا وقت نہ ہو)۔'),
  ('1eda02bf22a2bff1cb2800bd5b896d3cc34be3c780b093a2bb76817244c452ff', 'ur-roman', 'Danger in reaching the water (enemy, beast, or fear of missing the funeral / Eid prayer with no time to make wudu).', 'pani tak pahunchne me khatra ho (dushman, darinda, ya janaza / Eid ki namaz chhoot jane ka andesha aur wuzu ka waqt na ho).'),
  ('2c9a761991722ef0a18aca08f3d16a645525bf986f335fe46cb657215c922130', 'ur', 'Pure earth, sand, stone, lime, clay, or a dusty wall — anything of the earth’s substance.', 'پاک مٹی، ریت، پتھر، چونا، گارا، یا گرد آلود دیوار — ہر وہ چیز جو زمین کی جنس سے ہو۔'),
  ('40711cb9614498bd352e86d85bf9e924cedc91e63f106ed9e6b163481c3a0c5a', 'ur-roman', 'Pure earth, sand, stone, lime, clay, or a dusty wall — anything of the earth’s substance.', 'paak mitti, ret, patthar, choona, gaara, ya gard-aalood deewar — har wo cheez jo zameen ki jins se ho.'),
  ('22b422d8c214c47898110d4c9cbb69ba26fe97fa813be586fbab506003258987', 'ur', 'Not valid on wood, metal, glass, food, or cloth that carries no dust.', 'لکڑی، دھات، شیشہ، کھانے، یا ایسے کپڑے پر جائز نہیں جس پر گرد نہ ہو۔'),
  ('5d27db3f954c31a0f66a78ba36b1ea31fed7e693e7332aca59b118780526777a', 'ur-roman', 'Not valid on wood, metal, glass, food, or cloth that carries no dust.', 'lakdi, dhaat, sheesha, khane, ya aise kapde par jaiz nahin jis par gard na ho.'),
  ('e119bb337c98b8c1dbd86eae90747b72cda752727d8c3f61ea340ea4238f0d3b', 'ur', 'Saying Bismillah.', 'بسم اللہ کہنا۔'),
  ('df34f721bfcd5c373a4b85347a75aada69c4c1af759bb89540bbe88275ebbd0a', 'ur-roman', 'Saying Bismillah.', 'Bismillah kehna.'),
  ('651121762f8989727234f4c433ad1e41535903f1f7cef89d3d36ed3b39bfc66e', 'ur', 'Striking both palms on the clean surface.', 'دونوں ہتھیلیاں پاک سطح پر مارنا۔'),
  ('4c0841a85be9b43fb84519a27c8e13544660543ea46d5fe2d2057f3d38670e87', 'ur-roman', 'Striking both palms on the clean surface.', 'dono hatheliyan paak satah par maarna.'),
  ('fd37e9e0434af6e2c57cae313217087e8afb7119e8923569e38a6385d8b4b0e6', 'ur', 'Moving the palms forward and back on the surface, then dusting off excess.', 'ہتھیلیوں کو سطح پر آگے پیچھے پھیرنا، پھر زائد گرد جھاڑنا۔'),
  ('3c56b89acad3f0e7f12c887c2c945bc048424e634bbba2baa0131070025fe7f3', 'ur-roman', 'Moving the palms forward and back on the surface, then dusting off excess.', 'hatheliyon ko satah par aage peeche pherna, phir zaaid gard jhaadna.'),
  ('5010b38608b005b1ad1d1ddaacc1ddd16ba64122623ccde992dee17a6068a77b', 'ur', 'Keeping the order: face first, then the arms; and doing it continuously.', 'ترتیب رکھنا: پہلے چہرہ، پھر بازو؛ اور مسلسل کرنا۔'),
