  ('adf547869c971c6121839e7a2c338e010dd9a5258d38ffecae16d0eb3ec46e43', 'ur-roman', 'Taharat — purity of the body from hadath (needing wudu/gusl).', 'taharat — jism ka hadath se paak hona (wuzu/ghusl ki haajat se).'),
  ('4585c638059ac9b659e76b8d64536774b8192b3c73ba8ba8934a40f66243a728', 'ur', 'Purity of the clothes and the place of prayer from najasat.', 'کپڑوں اور نماز کی جگہ کا نجاست سے پاک ہونا۔'),
  ('446d752a0dd71cbb4933f128b0f11375a52e2abd4665d5738ca51af5db7f98af', 'ur-roman', 'Purity of the clothes and the place of prayer from najasat.', 'kapdon aur namaz ki jagah ka najasat se paak hona.'),
  ('80345ae78616b5e5b1b9e28dbf77c4fdc76e0bc0af3b572d4d907a7663fd658b', 'ur', 'Satr al-awrah — covering the body (men: navel to knee; women: whole body except face, hands and feet).', 'سترِ عورت — جسم ڈھانپنا (مرد: ناف سے گھٹنے تک؛ عورتیں: چہرے، ہاتھوں اور پاؤں کے سوا پورا جسم)۔'),
  ('966c5df3682f4faf5f332b69cf83b7d497765a5474e780742978a24bd0bc0ca2', 'ur-roman', 'Satr al-awrah — covering the body (men: navel to knee; women: whole body except face, hands and feet).', 'satar-e-awrat — jism dhaanpna (mard: naaf se ghutne tak; auratein: chehre, haathon aur paon ke siwa poora jism).'),
  ('1ec6a2ff06b374e8d40452526101c677ea569e58f17348b98bde2194b897cf45', 'ur', 'Istiqbal al-Qibla — facing the Ka’bah.', 'استقبالِ قبلہ — کعبہ کی طرف رخ کرنا۔'),
  ('f9d4f9e144ababf54fcd28904ea7d4b3feb2ebf7949b5016a26f298eed656e3e', 'ur-roman', 'Istiqbal al-Qibla — facing the Ka’bah.', 'istiqbaal-e-Qibla — Kaaba ki taraf rukh karna.'),
  ('c02ccdfa2ceeb4afa8d2a29cc3e740e509eeb265cdd2e8d6dd9804a9750440a6', 'ur', 'Waqt — the prescribed time of that salah has entered.', 'وقت — اس نماز کا مقررہ وقت داخل ہو چکا ہو۔'),
  ('4b4dfac3a514ed1bc02c59b3bee405beed10ced11b38c4d162e894e1a81b2836', 'ur-roman', 'Waqt — the prescribed time of that salah has entered.', 'waqt — us namaz ka muqarrara waqt dakhil ho chuka ho.'),
  ('9153092e0377c09ac77b7a6354e71d497159376d131416c85a6821024d937c43', 'ur', 'Niyyah — intention of the specific salah.', 'نیت — اُس مخصوص نماز کی نیت۔'),
  ('35e2439d3a377c91017ac52cdaae86e6ef0714bdaa075b7909cd2e340db06b4b', 'ur-roman', 'Niyyah — intention of the specific salah.', 'niyyat — us makhsoos namaz ki niyyat.'),
  ('681d199114950543cf645bd7e2629c0a1d7fdf713c7db409a63ee4466099c1a1', 'ur', 'Takbir-e-Tahrima — the opening “Allahu Akbar”.', 'تکبیرِ تحریمہ — شروع کی “Allahu Akbar”۔'),
  ('5aee94686a01c0711dfa31802e940ad08abb012ff8acc9554aa29abcfa2df180', 'ur-roman', 'Takbir-e-Tahrima — the opening “Allahu Akbar”.', 'Takbir-e-Tahrima — shuru ki “Allahu Akbar”.'),
  ('c43c5951e045da7422c36d6fb7ca682fe17e8c07b2bafdf701e16e8747acbd2c', 'ur', 'Qiyam — standing (for one who is able) in fard and witr.', 'قیام — فرض اور وتر میں کھڑا ہونا (جو قادر ہو)۔'),
  ('e67257d4d97e928728d72940ae3e54a16bb47d6016902991ea552382ff759a2f', 'ur-roman', 'Qiyam — standing (for one who is able) in fard and witr.', 'qiyam — farz aur witr me khada hona (jo qaadir ho).'),
  ('d227614f89eafb75d4b797724ea1c0dda68afa7d86b77f53779431ebea51aed9', 'ur', 'Qira’at — reciting at least the prescribed amount of Qur’an.', 'قرأت — کم از کم مقررہ مقدار میں قرآن پڑھنا۔'),
  ('fa0f74155d142a0975665b9ee0d2e74c821115664e56fa56b172bc5147294c8c', 'ur-roman', 'Qira’at — reciting at least the prescribed amount of Qur’an.', 'qiraat — kam az kam muqarrara miqdaar me Quran padhna.'),
  ('ef00efd78cff15a1abcaeccbcf4c5492c1f2a09fad3e38f7588de912f88061c9', 'ur', 'Ruku — bowing.', 'رکوع — جھکنا۔'),
  ('9362858d5e2f940852356bc762752969086bd2d820533d44f3505795e4785d06', 'ur-roman', 'Ruku — bowing.', 'ruku — jhukna.'),
  ('e74b43616da8d8672dcefd5e8c320faf8c3ba95267fea8caccdf608c9303e371', 'ur', 'Sujud — two prostrations in each rak’ah.', 'سجود — ہر رکعت میں دو سجدے۔'),
  ('acac196ec56514a8b0c8ce6c91082f7281d3b9fc9dac7c28aa35a6395f5cc1bf', 'ur-roman', 'Sujud — two prostrations in each rak’ah.', 'sujood — har rakat me do sajde.'),
  ('f8777303f722110bd6666642fc12cfd30b450605e35527eafcbd017c9841883e', 'ur', 'Qa’dah Akhirah — sitting at the end for the length of the Tashahhud.', 'قعدہ اخیرہ — آخر میں تشہد کی مقدار بیٹھنا۔'),
  ('24842bc85a3c35809a8355624c33ceea928f288d211483b9e9377e6dacb9ca94', 'ur-roman', 'Qa’dah Akhirah — sitting at the end for the length of the Tashahhud.', 'qaada akhirah — aakhir me Tashahhud ki miqdaar baithna.'),
  ('b963748386698e819b9b0785cc674f91a31e69023e8e7692ccb2d0b08b68f925', 'ur', 'Reciting Surah Al-Fatiha in every rak’ah (of fard, and all of witr/nafl).', 'ہر رکعت میں سورۃ الفاتحہ پڑھنا (فرض کی، اور وتر/نفل کی سب میں)۔'),
  ('942ff828bf84a7cfa29f6a6d43a0f45418d2105f231cb0d5630a4cec56d211e3', 'ur-roman', 'Reciting Surah Al-Fatiha in every rak’ah (of fard, and all of witr/nafl).', 'har rakat me Surah Al-Fatiha padhna (farz ki, aur witr/nafl ki sab me).'),
  ('4c8d35180526243428ddb12fabb3a58e5ec956b3ac8095263c17607b31982ad5', 'ur', 'Joining a surah or three short ayahs after Fatiha in the first two rak’ahs of fard, and every rak’ah of witr/nafl.', 'فرض کی پہلی دو رکعتوں میں، اور وتر/نفل کی ہر رکعت میں، فاتحہ کے بعد کوئی سورت یا تین چھوٹی آیات ملانا۔'),
  ('17e1e9c08ae6eb33100df5a76b05a8d6fee28b27d226359767145c17e450f81c', 'ur-roman', 'Joining a surah or three short ayahs after Fatiha in the first two rak’ahs of fard, and every rak’ah of witr/nafl.', 'farz ki pehli do rakaton me, aur witr/nafl ki har rakat me, Fatiha ke baad koi surat ya teen chhoti ayatein milana.'),
  ('045d280342c40cff151f02766d435ba74d5a4740e8e4805652b7d7dbf2c9353a', 'ur', 'Ta’dil-e-arkan — performing ruku and sujud calmly, with a pause.', 'تعدیلِ ارکان — رکوع اور سجدہ اطمینان سے، ٹھہر کر ادا کرنا۔'),
  ('b96b9f7a2b7def68878869644b6da08aefbd8c11a9f467b8b1b1240fef21579c', 'ur-roman', 'Ta’dil-e-arkan — performing ruku and sujud calmly, with a pause.', 'taadeel-e-arkaan — ruku aur sajda itminaan se, thehar kar ada karna.'),
  ('14d6d2dd358f87a3611ef0528771a94a4e0c66c362c2858f3d7ae98862c44477', 'ur', 'Qa’dah Ula — the first sitting after two rak’ahs.', 'قعدہ اولیٰ — دو رکعتوں کے بعد پہلا بیٹھنا۔'),
  ('bbd5671a4a733360f1ba56b042cd5a367f5ae107e4be636b580e3bbc74422961', 'ur-roman', 'Qa’dah Ula — the first sitting after two rak’ahs.', 'qaada oola — do rakaton ke baad pehla baithna.'),
  ('63579bd9fa007c457372f3863280a9fc02dd05a870175d2211ecca7820a944c3', 'ur', 'Reciting the Tashahhud (At-tahiyyat) in both sittings.', 'دونوں قعدوں میں تشہد (التحیات) پڑھنا۔'),
  ('7128c9944684ed49266599631b5e3f052090000f31bcf021100b149fd0d782aa', 'ur-roman', 'Reciting the Tashahhud (At-tahiyyat) in both sittings.', 'dono qaadon me Tashahhud (At-tahiyyat) padhna.'),
  ('9e619933690c8a2bc68b85ae607d0506112295ecf4007e021687c8b7630f52d1', 'ur', 'Keeping the fard recitation and actions in order.', 'فرض قرأت اور افعال کو ترتیب سے رکھنا۔'),
  ('d04d7bb3918f4d92f2dfa238ac0d6d7246f24aacd9894700e2503fc1e03fafec', 'ur-roman', 'Keeping the fard recitation and actions in order.', 'farz qiraat aur afaal ko tarteeb se rakhna.'),
  ('98c340d39278f6b2566aee340ab4121e95e769ae9e3bdac8724db1ee1b5fb241', 'ur', 'Reciting aloud in the loud prayers and silently in the silent prayers (for the imam).', 'جہری نمازوں میں بلند آواز سے اور سری نمازوں میں آہستہ پڑھنا (امام کے لیے)۔'),
  ('f655729bd8a6511213d510fd63ccbda4eb98e178cf58042fd40c13387b2cf0e3', 'ur-roman', 'Reciting aloud in the loud prayers and silently in the silent prayers (for the imam).', 'jehri namazon me buland awaz se aur sirri namazon me aahista padhna (imam ke liye).'),
  ('552e018bae5d44e739fbfa664c9e1fb95ca17e5ced6e908326dd2f73ac47cc80', 'ur', 'The three takbirs and the du’a-e-Qunut of witr.', 'وتر کی تین تکبیریں اور دعائے قنوت۔'),
  ('425aa74437fe2ca73ac481b80dfb275e97ecf245a5c05f7bf3fdbb35379c835d', 'ur-roman', 'The three takbirs and the du’a-e-Qunut of witr.', 'witr ki teen takbeerein aur Dua-e-Qunut.'),
  ('a167f8881f2ded83308ef5f889977f3982f290dd1cd313f7b6f404c4294942d5', 'ur', 'The additional takbirs of the two Eid prayers.', 'دونوں عید کی نمازوں کی زائد تکبیریں۔'),
  ('3430df92e7d2e32e9bf9f694179c386dc76121571271385ed39aaa4d742af97c', 'ur-roman', 'The additional takbirs of the two Eid prayers.', 'dono Eid ki namazon ki zaaid takbeerein.'),
  ('13fb7cdf32987ea0ce4fa370e0a0059ee1f9ae44d2fde5ec2666a087af4db2da', 'ur', 'Ending the salah with the words of Salam.', 'نماز کو سلام کے الفاظ کے ساتھ ختم کرنا۔'),
  ('85299bbe613890199f7c229eb5955f54c44681842ab4803aa5af2a27cb7a3ea3', 'ur-roman', 'Ending the salah with the words of Salam.', 'namaz ko salam ke alfaaz ke saath khatam karna.'),
  ('8d048d2ed2264cb77735fa14d018f9be0b76fa47b86a7a07a2614b51bd679ee5', 'ur', 'Performing Sajdah Sahw when a wajib is missed or delayed.', 'جب کوئی واجب چھوٹ جائے یا تاخیر ہو تو سجدہ سہو کرنا۔'),
  ('5539e647d10fa563c41afc413be652a61ce177f2615a84705507cc41573bc092', 'ur-roman', 'Performing Sajdah Sahw when a wajib is missed or delayed.', 'jab koi wajib chhoot jaye ya taakheer ho to sajda sahw karna.'),
  ('be4a23ddaa113cc28ea23f218b1836b69ea06f444f47880809874ac0fc475524', 'ur', 'Reciting Thana (Subhanaka) after the opening takbir.', 'تکبیرِ تحریمہ کے بعد ثنا (سبحانک) پڑھنا۔'),
  ('86f939d54e606a3a24518c77c222cb38efa508691690ee7f210277990df0c57a', 'ur-roman', 'Reciting Thana (Subhanaka) after the opening takbir.', 'takbir-e-tahrima ke baad Sana (Subhanaka) padhna.'),
  ('3279f3dcd903978a8f26f89088112b2227c8a310085610a614ca42dbdb5cb7d6', 'ur', 'Ta’awwudh (A’udhu billah) and Tasmiyah (Bismillah) before Al-Fatiha.', 'الفاتحہ سے پہلے تعوذ (اعوذ باللہ) اور تسمیہ (بسم اللہ)۔'),
  ('c6cbbc95b62fcf8f4efa7ce9287322fe422cafd9e328f29b768cc4d04f6a4a02', 'ur-roman', 'Ta’awwudh (A’udhu billah) and Tasmiyah (Bismillah) before Al-Fatiha.', 'Al-Fatiha se pehle Taawwuz (Auzu billah) aur Tasmiyah (Bismillah).'),
  ('34a56b0f89963ca33a38703697213a3f23b1f895043beedfa4e2d1a5be307310', 'ur', 'Saying Ameen quietly after Al-Fatiha.', 'الفاتحہ کے بعد آہستہ آمین کہنا۔'),
  ('4e110ad95133d6e543be15db58463a7132dae3e82f9a8621bf027a104f29b071', 'ur-roman', 'Saying Ameen quietly after Al-Fatiha.', 'Al-Fatiha ke baad aahista Ameen kehna.'),
  ('1e10fe4cb9cf66494b3d797acaf17bcfcec6637ea05641f3cfcd3aba0da0a2ef', 'ur', 'Saying the takbirs when moving between postures.', 'ایک حالت سے دوسری میں جاتے وقت تکبیریں کہنا۔'),
  ('e94baeee813c4d263384eb513edd4461528e18a757db0bf285c0b5864803d2fd', 'ur-roman', 'Saying the takbirs when moving between postures.', 'ek halat se doosri me jaate waqt takbeerein kehna.'),
  ('1db3ab1480207bf4c878c93b1dffe300963347d46d402e7b43d06ee4304a62e9', 'ur', 'Reciting the tasbih of ruku (“Subhana Rabbiyal Azeem”) and sujud (“Subhana Rabbiyal A’la”) at least three times.', 'رکوع کی تسبیح (“Subhana Rabbiyal Azeem”) اور سجدے کی (“Subhana Rabbiyal A’la”) کم از کم تین بار پڑھنا۔'),
  ('e6274ebfc71d2742bd47a8f7fe8a895e083d9f878c92af1e07baca912f7b6ad6', 'ur-roman', 'Reciting the tasbih of ruku (“Subhana Rabbiyal Azeem”) and sujud (“Subhana Rabbiyal A’la”) at least three times.', 'ruku ki tasbeeh (“Subhana Rabbiyal Azeem”) aur sajde ki (“Subhana Rabbiyal A’la”) kam az kam teen baar padhna.'),
  ('1762c46ea85e288d742f2839a46d22ed718e45af08b6fd573183e5f32c106be7', 'ur', 'Saying “Sami’Allahu liman hamidah” when rising, and “Rabbana lakal hamd”.', 'اٹھتے وقت “Sami’Allahu liman hamidah” اور “Rabbana lakal hamd” کہنا۔'),
  ('07b3b4bfb2676586929922c3a21c234c36abe0fe2478b675ba91f3918d068992', 'ur-roman', 'Saying “Sami’Allahu liman hamidah” when rising, and “Rabbana lakal hamd”.', 'uthte waqt “Sami’Allahu liman hamidah” aur “Rabbana lakal hamd” kehna.'),
  ('0750adeb4aeac872898a73362df7857929a7c87b60fcb8677540a37541706b52', 'ur', 'Reciting Durood Sharif and a du’a in the final sitting.', 'آخری قعدے میں درود شریف اور دعا پڑھنا۔'),
  ('ef56fd6a14226f6d872fd6a3b7498e1406698189e6f9997cda8cedb2d003a6de', 'ur-roman', 'Reciting Durood Sharif and a du’a in the final sitting.', 'aakhri qaade me Durood Sharif aur dua padhna.'),
  ('73d8564862b664c423b8acd3ae07186b3fab1f369fbf5d9629e615ea6522e52e', 'ur', 'Raise the hands up to the ear-lobes for the opening takbir.', 'تکبیرِ تحریمہ کے لیے ہاتھ کانوں کی لو تک اٹھائیں۔'),
  ('86da2679135876135b1fb3dc58d76472f4a36841eb241e6ac7cd6a0a103fced8', 'ur-roman', 'Raise the hands up to the ear-lobes for the opening takbir.', 'takbir-e-tahrima ke liye haath kaanon ki lo tak uthayein.'),
  ('3b5d6e0dd1b7b02a865436a9091986383a253c850762fa6c0e2dbb6cf9c9840b', 'ur', 'Fold the hands below the navel, right over left, grasping the left wrist.', 'ہاتھ ناف کے نیچے باندھیں، دایاں بائیں پر، بائیں گٹے کو پکڑ کر۔'),
  ('886c44b0c86a1f3836ed27b6a3e456bff7fbce64b6a1f83ed3c4bce03954a143', 'ur-roman', 'Fold the hands below the navel, right over left, grasping the left wrist.', 'haath naaf ke neeche baandhein, daya bayein par, bayein gatte ko pakad kar.'),
  ('aad64006c461e14d4f6d1d28fe16c5db0d0cae885584b580f851d579393a8ca6', 'ur', 'In ruku, grasp the knees with the fingers spread and keep the back level.', 'رکوع میں انگلیاں کھول کر گھٹنے پکڑیں اور کمر سیدھی رکھیں۔'),
  ('56f09b4ec1eb280d27054c1f06d0637ce5730da60ae582c5487d6401b4080dc8', 'ur-roman', 'In ruku, grasp the knees with the fingers spread and keep the back level.', 'ruku me ungliyan khol kar ghutne pakdein aur kamar seedhi rakhein.'),
  ('162caba4e1ad75725d5469fdaa6c1250410b4526b7aead04169c389b6d32c230', 'ur', 'In sujud, keep the elbows raised off the ground and away from the sides, and the belly off the thighs.', 'سجدے میں کہنیاں زمین سے اور پہلوؤں سے دور اٹھی رکھیں، اور پیٹ رانوں سے الگ رکھیں۔'),
  ('8cefb044ba8adcfffd809e67531a5b15ed537ab0065d3229f5adb6387d2f3508', 'ur-roman', 'In sujud, keep the elbows raised off the ground and away from the sides, and the belly off the thighs.', 'sajde me kohniyan zameen se aur pehluon se door uthi rakhein, aur pet raanon se alag rakhein.'),
  ('91e407d5c76fb411dbc1117bc8cb01d698541528b212c301e83019a920fe6f9a', 'ur', 'Sit with the left foot laid flat underneath and the right foot upright (iftirash).', 'بایاں پاؤں نیچے بچھا کر اور دایاں پاؤں کھڑا کر کے بیٹھیں (افتراش)۔'),
  ('a510b4df5ef853e4db32dc8b77a142b1839153634c08a46d0d496a5ddc2f910c', 'ur-roman', 'Sit with the left foot laid flat underneath and the right foot upright (iftirash).', 'baya paon neeche bichha kar aur daya paon khada kar ke baithein (iftiraash).'),
  ('ff54cdbf007e87e01351af08154b064e51588b4980f642102329a6fa2b399456', 'ur', 'Raise the hands only up to the shoulders for the opening takbir.', 'تکبیرِ تحریمہ کے لیے ہاتھ صرف کندھوں تک اٹھائیں۔'),
  ('cba50f920479babd2a17086b30a6db8b20f957d17d689b5f1f545f7bdd1d8af1', 'ur-roman', 'Raise the hands only up to the shoulders for the opening takbir.', 'takbir-e-tahrima ke liye haath sirf kandhon tak uthayein.'),
  ('0ac3195d968c1cf3f4551168f5e490310cb5fd26ecd58516998ee5f099350948', 'ur', 'Fold the hands on the chest, right over left.', 'ہاتھ سینے پر باندھیں، دایاں بائیں پر۔'),
  ('8b12eeca548fc400a3bee37496af73c184659861882ea1bc4af6bc8e0ef36425', 'ur-roman', 'Fold the hands on the chest, right over left.', 'haath seene par baandhein, daya bayein par.'),
  ('de7baa53cf0aec6d798893eeb34a8cb22d3693bd5d92dcd4cc86cab1dc397db9', 'ur', 'In ruku, bend just enough to reach the knees, keeping the fingers together and the arms close to the body.', 'رکوع میں صرف اتنا جھکیں کہ گھٹنوں تک ہاتھ پہنچ جائیں، انگلیاں ملی رکھیں اور بازو جسم سے قریب رکھیں۔'),
  ('3196664e591d6cb0a7a950e2d7115b95d5d3dbf732dd5094ae892eff36bd3202', 'ur-roman', 'In ruku, bend just enough to reach the knees, keeping the fingers together and the arms close to the body.', 'ruku me sirf itna jhukein ke ghutnon tak haath pahunch jayein, ungliyan mili rakhein aur baazu jism se qareeb rakhein.'),
  ('ab995086aefa5a84779f152ddfb565903d75131cf9122a7d1b8d4ed6196c713c', 'ur', 'In sujud, keep the body drawn together — forearms on the ground and the belly close to the thighs.', 'سجدے میں جسم سمیٹ کر رکھیں — بازو زمین پر اور پیٹ رانوں سے قریب۔'),
  ('395728ca45e8d5db6f0600c26307c01e38b61d20f95b9033d82f3a9f1e6d341e', 'ur-roman', 'In sujud, keep the body drawn together — forearms on the ground and the belly close to the thighs.', 'sajde me jism samet kar rakhein — baazu zameen par aur pet raanon se qareeb.'),
  ('972c82fca853ab7d2c323ef3b0dfcdce6131e835c328ecfb6dad203aa5089386', 'ur', 'Sit with both feet brought out to the right side (tawarruk).', 'دونوں پاؤں دائیں طرف نکال کر بیٹھیں (تورک)۔'),
  ('6bc684e70735c69c6e37dd753c9721f89bcaefb7a89261502cbde7d1267119b1', 'ur-roman', 'Sit with both feet brought out to the right side (tawarruk).', 'dono paon dayein taraf nikaal kar baithein (tawarruk).'),
  ('7808487a052133f6da9cade9230d269f5e190129c5bd0d97699b5be39502fe5d', 'ur', 'Talking intentionally, even a word or two.', 'جان بوجھ کر بات کرنا، چاہے ایک دو لفظ ہی ہوں۔'),
  ('a9b4b73b1d8e86c6dbe72613da024960f76406ffd353b625cec75455922c9fd3', 'ur-roman', 'Talking intentionally, even a word or two.', 'jaan boojh kar baat karna, chahe ek do lafz hi hon.'),
  ('67a8187a427ab44d5606e68da4674d255ef121a75fc72b2787dc4a360069d836', 'ur', 'Eating or drinking, even a little.', 'کھانا یا پینا، تھوڑا سا بھی۔'),
  ('a163011bbe3b91df3b65a5580658908acb39fc39ba9c82c712f62f88fd38e984', 'ur-roman', 'Eating or drinking, even a little.', 'khana ya peena, thoda sa bhi.'),
  ('8bf337788d74d97a7e0ba6ca4103f5d48350300e8f2afcc7c08359c1ae61fa18', 'ur', 'Amal-e-kathir — excessive movement not part of salah.', 'عملِ کثیر — نماز سے باہر کی زیادہ حرکت۔'),
  ('08a2b6c81538c0fc9eb32d5a50c1994d60990e43fd79b8d9854cde87adbbbd10', 'ur-roman', 'Amal-e-kathir — excessive movement not part of salah.', 'amal-e-kaseer — namaz se bahar ki zyada harkat.'),
  ('99925d0e867776a311623e6a8dd44ca851e2abbe084903f8ffd0f90807931fff', 'ur', 'Turning the chest away from the Qibla without excuse.', 'بغیر عذر سینے کو قبلہ سے پھیر لینا۔'),
  ('b4081208ff0c6a86c26f3eee0da0273c25ef192ea326c8b03dba34bfc9c96c56', 'ur-roman', 'Turning the chest away from the Qibla without excuse.', 'bagair uzr seene ko Qibla se pher lena.'),
  ('887d07c7b62b5ea9ce986a3ee5e59a6f49383b5b193552e968237e90df0a6e9c', 'ur', 'Loud laughter (in a salah with sujud — also breaks wudu).', 'قہقہہ (ایسی نماز میں جس میں سجدہ ہو — وضو بھی توڑ دیتا ہے)۔'),
  ('c25fd61d1bfc4e5be4294c6b499915cb0d0a75a5fb27906ac434e6ce978e0469', 'ur-roman', 'Loud laughter (in a salah with sujud — also breaks wudu).', 'qehqaha (aisi namaz me jis me sajda ho — wuzu bhi tod deta hai).'),
  ('8b30b0734d75634c1d1c62aecff91e2086d9fae5eaa6123bda1751041b649be8', 'ur', 'Reciting so incorrectly that the meaning is corrupted.', 'اتنا غلط پڑھنا کہ معنی بگڑ جائے۔'),
  ('95fb5cfb646bf4172371cb5b6421c177838406bb636a82ec8c20a7ed9fc23732', 'ur-roman', 'Reciting so incorrectly that the meaning is corrupted.', 'itna ghalat padhna ke maani bigad jaye.'),
  ('42c16f002e6d52fe21f2014cb0939c8099af027b251cb16d76ee13222b65d60c', 'ur', 'Saying “Ameen” to a worldly request, or responding to someone with Qur’an intending conversation.', 'کسی دنیاوی درخواست پر “Ameen” کہنا، یا کسی کو قرآن سے گفتگو کی نیت سے جواب دینا۔'),
  ('f058f3047651ef06125c537313aa79a08445f4494720955d2368cc8054b21b5a', 'ur-roman', 'Saying “Ameen” to a worldly request, or responding to someone with Qur’an intending conversation.', 'kisi duniyavi darkhwast par “Ameen” kehna, ya kisi ko Quran se guftagu ki niyyat se jawab dena.'),
  ('8d42b61b2608051c9dcde7b0f7abe886d10a49b2fcd0a8ea18c8dc5fc33f5857', 'ur', 'Playing with clothes or the body, or cracking the fingers.', 'کپڑوں یا جسم سے کھیلنا، یا انگلیاں چٹخانا۔'),
  ('67c5b249cc88c6e5fef3855bfc6eeae93ad548b5aa10dc450c137d6b57922ce6', 'ur-roman', 'Playing with clothes or the body, or cracking the fingers.', 'kapdon ya jism se khelna, ya ungliyan chatkhana.'),
  ('39c58e07703c6f1e8ebec4bac953ca165b8a324255359436db9f45f5cbb42fec', 'ur', 'Looking around; the gaze should be at the place of sujud.', 'ادھر ادھر دیکھنا؛ نظر سجدے کی جگہ پر ہونی چاہیے۔'),
  ('150faad567a6fa7d5804da832d46f1f25494b3d969c01ef32c59a1204e572658', 'ur-roman', 'Looking around; the gaze should be at the place of sujud.', 'idhar udhar dekhna; nazar sajde ki jagah par honi chahiye.'),
  ('b8d963113b141ad8f6a83dd92af87bb851a976d277ea893afa5ad5e593b3da4d', 'ur', 'Praying while food is served and one is hungry, or while needing the toilet.', 'کھانا سامنے ہو اور بھوک ہو، یا رفعِ حاجت کی حاجت ہو، اس حال میں نماز پڑھنا۔'),
  ('2d27281f197ffba0110a4946158c2661dad5571cc45ab000ce2eee66e48ac85a', 'ur-roman', 'Praying while food is served and one is hungry, or while needing the toilet.', 'khana saamne ho aur bhook ho, ya raf-e-haajat ki haajat ho, is haal me namaz padhna.'),
  ('b05e1f194cf98c30b97190cb24953b235682748b79d0054b7889bbb96657f7c9', 'ur', 'Covering the mouth, or letting the garment hang loose (sadl).', 'منہ ڈھانپنا، یا کپڑا لٹکتا چھوڑنا (سدل)۔'),
  ('d4e007906903438a9bf30a93557ba467a3c5ea610db17c3e2e5be7ee36046a85', 'ur-roman', 'Covering the mouth, or letting the garment hang loose (sadl).', 'munh dhaanpna, ya kapda latakta chhodna (sadl).'),
  ('f92921b8961739387852371aaba460433420dc6b69fd6d47c88ec03ad20e9f2f', 'ur', 'Praying in clothing bearing pictures of living beings.', 'ایسے کپڑوں میں نماز پڑھنا جن پر جانداروں کی تصویریں ہوں۔'),
  ('594333b39554b459cb866fddcb10193d5ee81cbd80cc633d5fc71dab0f9d74e1', 'ur-roman', 'Praying in clothing bearing pictures of living beings.', 'aise kapdon me namaz padhna jin par jaandaron ki tasveerein hon.'),
  ('890ddab7a2c748f0814b420ddbac697fe1a5a083f802a73a9aa89df9a02fbc7a', 'ur', 'A wajib was left out or delayed unintentionally.', 'کوئی واجب غیر ارادی طور پر چھوٹ گیا یا تاخیر سے ہوا۔'),
  ('f0d2e9cce1a832864b2b067166c7d72831f93396b0f94238a0007d6736cf6077', 'ur-roman', 'A wajib was left out or delayed unintentionally.', 'koi wajib ghair-iraadi taur par chhoot gaya ya taakheer se hua.'),
  ('987d9921286f6cf77800f395a403a804e415fee96e110b58cd9059b1760271ec', 'ur', 'A fard was delayed (e.g. an extra ruku or missed sitting), without leaving a fard entirely.', 'کوئی فرض تاخیر سے ہوا (مثلاً زائد رکوع یا قعدہ چھوٹنا)، بغیر کسی فرض کو بالکل چھوڑے۔'),
  ('da1408726c3c16edae251e41c4c4a2ef4c2525d014637506f66af522f17eb8c5', 'ur-roman', 'A fard was delayed (e.g. an extra ruku or missed sitting), without leaving a fard entirely.', 'koi farz taakheer se hua (masalan zaaid ruku ya qaada chhootna), bagair kisi farz ko bilkul chhode.'),
  ('941d4b7052809cff9f620e2e2d3e28b4853206d82e20bcd1f6c5579f924ab426', 'ur', 'Method: after the final Tashahhud, make one Salam to the right, then two sajdahs, then Tashahhud, Durood, du’a and Salam.', 'طریقہ: آخری تشہد کے بعد دائیں طرف ایک سلام پھیریں، پھر دو سجدے، پھر تشہد، درود، دعا اور سلام۔'),
  ('e3cae6c88bed2ca2c0e1569751cc99289e80f20ba4bca67064ff10e9a49bbfa6', 'ur-roman', 'Method: after the final Tashahhud, make one Salam to the right, then two sajdahs, then Tashahhud, Durood, du’a and Salam.', 'tareeqa: aakhri Tashahhud ke baad dayein taraf ek salam pherein, phir do sajde, phir Tashahhud, Durood, dua aur salam.'),
  ('99fb491765f34ddff6269c930e990400c485bda0770268a744f34a39e79a71d3', 'ur', 'Niyyah (intention) — for Ramadan it may be made from the night up to before midday; a missed/qada or kaffarah fast needs the intention before Subah Sadiq.', 'نیت — رمضان کے لیے رات سے دوپہر سے پہلے تک کی جا سکتی ہے؛ قضا یا کفارہ کے روزے کی نیت صبح صادق سے پہلے ضروری ہے۔'),
  ('1ecdc8a68f859cdc01ca539633a9b63f53ee07b7c7065f1a505b9038b1f892eb', 'ur-roman', 'Niyyah (intention) — for Ramadan it may be made from the night up to before midday; a missed/qada or kaffarah fast needs the intention before Subah Sadiq.', 'niyyat — Ramzan ke liye raat se dopeher se pehle tak ki ja sakti hai; qaza ya kaffara ke roze ki niyyat Subah Sadiq se pehle zaroori hai.'),
  ('a93f81af2747feaca8c6c0c7b83cfb30f7b4ded786add5eba1a8ad1f5d8807df', 'ur', 'Abstaining from eating, drinking and marital relations from Subah Sadiq (true dawn) until sunset.', 'صبح صادق سے غروبِ آفتاب تک کھانے، پینے اور میاں بیوی کے ملاپ سے رکنا۔'),
  ('47854bc6dcc3738fa95390b818c9c5e809ec8e8ce7467099adfa3ec8aa19d534', 'ur-roman', 'Abstaining from eating, drinking and marital relations from Subah Sadiq (true dawn) until sunset.', 'Subah Sadiq se ghuroob-e-aftaab tak khane, peene aur miyan biwi ke milaap se rukna.'),
  ('0afa023f9269bcf933bae93c09af58a1faf67fe0c6cefd31ab34c109cace25b0', 'ur', 'Eating or drinking intentionally without a valid excuse.', 'بغیر کسی جائز عذر کے جان بوجھ کر کھانا یا پینا۔'),
  ('6d33e34fd8c4e4201b4a58459c7705d2b737d194affbfd26cae45ad301d272ea', 'ur-roman', 'Eating or drinking intentionally without a valid excuse.', 'bagair kisi jaiz uzr ke jaan boojh kar khana ya peena.'),
  ('b6f8a941147445334e6a12f92629518675efb1633c435d0a41cfc7d5fcf26ca1', 'ur', 'Marital relations during the fast.', 'روزے کی حالت میں میاں بیوی کا ملاپ۔'),
  ('4c43493c16ea7303703d0abb3773c42f2dfcea38b563f2084707141abb8f2359', 'ur-roman', 'Marital relations during the fast.', 'roze ki halat me miyan biwi ka milaap.'),
  ('0d64c6268331699a011f817edef0a547760d157f6274b4a60d0bbac25742bb29', 'ur', 'Kaffarah = freeing a slave, or fasting 60 consecutive days, or feeding 60 poor persons — in addition to making up (qada) the day.', 'کفارہ = ایک غلام آزاد کرنا، یا مسلسل 60 دن روزے، یا 60 مسکینوں کو کھانا کھلانا — اس دن کی قضا کے علاوہ۔'),
  ('079262c9cf730803d039310d31a5d8641bd5cc0684bd2123e7a55fc380a41425', 'ur-roman', 'Kaffarah = freeing a slave, or fasting 60 consecutive days, or feeding 60 poor persons — in addition to making up (qada) the day.', 'kaffara = ek ghulam aazaad karna, ya musalsal 60 din roze, ya 60 miskeenon ko khana khilana — us din ki qaza ke ilawa.'),
  ('6aa1ee8fcd89be65b8c38f9b808e87128312714ed045259ee8474568c2fb46ee', 'ur', 'Eating or drinking by mistake believing the fast was already broken.', 'یہ سمجھ کر کھانا یا پینا کہ روزہ پہلے ہی ٹوٹ چکا ہے۔'),
  ('1f2251cb9d0491df48571734ad2deecd25d82833a3b216fe6fc26c44e51ae784', 'ur-roman', 'Eating or drinking by mistake believing the fast was already broken.', 'yeh samajh kar khana ya peena ke roza pehle hi toot chuka hai.'),
  ('1b68924f6dc140c0d5e2f5609a2ddb695d8e84da30fc6e8d18b9e69c968b1f83', 'ur', 'Intentional vomiting of a mouthful.', 'جان بوجھ کر منہ بھر قے کرنا۔'),
  ('a33782a123063ad687d42cd6e522bd82d8dd4013f736a3a08737347cecd209e7', 'ur-roman', 'Intentional vomiting of a mouthful.', 'jaan boojh kar munh bhar qai karna.'),
  ('539ec97b8697e4f169ad5e3fa1e4882e22132a7d4c116ae9e2bb270ba0ac40fc', 'ur', 'Water reaching the throat while gargling, or medicine/drops entering the body cavity.', 'غرارہ کرتے وقت پانی کا حلق میں چلا جانا، یا دوا/قطرے کا جسم کے اندر پہنچنا۔'),
  ('9ee8cbade6cb4ed5235d4b30116df4d3a2a5eaf768079951e785ec72b32b9fdc', 'ur-roman', 'Water reaching the throat while gargling, or medicine/drops entering the body cavity.', 'gharara karte waqt pani ka halaq me chala jana, ya dawa/qatre ka jism ke andar pahunchna.'),
  ('14419511114537fc7f74f94d0e8e4cbe4809c4d8f43fd4a0e459579ffe018e60', 'ur', 'Swallowing something that is not normally eaten.', 'ایسی چیز نگل لینا جو عام طور پر کھائی نہیں جاتی۔'),
  ('562f36b9dc997674e618b8c1cdd6cbaed1d5c279c276c533d9607712eddbfe6d', 'ur-roman', 'Swallowing something that is not normally eaten.', 'aisi cheez nigal lena jo aam taur par khai nahin jaati.'),
  ('3007517cc82e13ff6f4b87470c40aa01d3efb69c0be25502993cef92b0592b53', 'ur', 'Eating or drinking out of genuine forgetfulness.', 'حقیقی بھول کر کھانا یا پینا۔'),
  ('a9b1f7dda29983c966fa83fd1fba8c77d59fdc7a89d3b4d20297da7fb2ea4c65', 'ur-roman', 'Eating or drinking out of genuine forgetfulness.', 'haqeeqi bhool kar khana ya peena.'),
  ('be9eb5c42cafd76f894f3d5de9fbe9a1c4b732e0baf111ba5f0095ca183c5864', 'ur', 'Unintentional vomiting.', 'بغیر ارادے کے قے آنا۔'),
  ('d6d869e9d46de746bb25e015844442664d07e7b15940e61ee309be4fafd34638', 'ur-roman', 'Unintentional vomiting.', 'bagair iraade ke qai aana.'),
  ('2dc902d0ffac40c17e53f59789ca78f1b9d3f7e979edeabc352d9e3b6d99a053', 'ur', 'A wet dream, or dust / smoke entering the throat unavoidably.', 'احتلام، یا مجبوراً گرد / دھواں حلق میں چلا جانا۔'),
  ('9dab4354cd9c0dd66b0564b52b5b2e5a6450727e32fb8c52b80de166bde923b5', 'ur-roman', 'A wet dream, or dust / smoke entering the throat unavoidably.', 'ehtelaam, ya majbooran gard / dhuan halaq me chala jana.'),
  ('24d4d4f0cea3d7bf677362156ef5e0386f01c141e82991fd3686b9e9cbdd1952', 'ur', 'Using miswak, and applying surma (kohl) or oil.', 'مسواک کرنا، اور سرمہ یا تیل لگانا۔'),
  ('72ec8b1f7db172aa04ace2ca220e79f388b41e50c79059efb9eae88bbd9bc1ee', 'ur-roman', 'Using miswak, and applying surma (kohl) or oil.', 'miswak karna, aur surma ya tel lagana.'),
  ('3851392a44eda6583baaf7e376585a146c8c30a23b0c488bba5339591cf6690b', 'ur', 'Eating Sehri and delaying it near to the end of its time.', 'سحری کھانا اور اسے وقت کے آخر کے قریب تاخیر سے کھانا۔'),
  ('9ff6265c28d4cc8f49a78770d2a5561f79553dd8c3fdd614fcbde01862620e95', 'ur-roman', 'Eating Sehri and delaying it near to the end of its time.', 'sehri khana aur use waqt ke aakhir ke qareeb taakheer se khana.'),
  ('072dd3ac78d3be8d474392c7ab5eb48671512e4daec5a49f4cb54450ee7763a0', 'ur', 'Hastening the iftar immediately after sunset.', 'غروبِ آفتاب کے فوراً بعد افطار میں جلدی کرنا۔'),
  ('0bb49b3b81ea4c63caf7fb6fb11c9636191a73d54c4ad42f15c1e436a2d16fb6', 'ur-roman', 'Hastening the iftar immediately after sunset.', 'ghuroob-e-aftaab ke fauran baad iftar me jaldi karna.'),
  ('58e1874db7a4d8ab1ceb4cb14e12da6a754e010d6aa4d51c0b1a4c2cab6fa3a8', 'ur', 'Opening the fast with dates or water and making the du’a of iftar.', 'کھجور یا پانی سے روزہ کھولنا اور افطار کی دعا کرنا۔'),
  ('6a3104c1f660e29c8883b051d269542e4d0bdf53de41eadfe30f3ed9029f9bc1', 'ur-roman', 'Opening the fast with dates or water and making the du’a of iftar.', 'khajoor ya pani se roza kholna aur iftar ki dua karna.'),
  ('35525472a5b4699f266d1ec2d302bbad68d3ffa9799ed20baf2054e67d8ef0d4', 'ur', 'Increasing in Qur’an recitation, charity and worship, especially in the last ten nights.', 'قرآن کی تلاوت، صدقہ اور عبادت میں اضافہ کرنا، خاص کر آخری دس راتوں میں۔'),
  ('6c7238c1106505f2d4b6f78d7b854f4109a51d8b0049dc4f0013fa45473e41f9', 'ur-roman', 'Increasing in Qur’an recitation, charity and worship, especially in the last ten nights.', 'Quran ki tilawat, sadqa aur ibadat me izafa karna, khaas kar aakhri das raaton me.'),
  ('a24aab9075f5caa02cdba1b9caece8b427a597e40ea9bcc91b791e197737464a', 'ur', 'The traveller (musafir) and the genuinely sick — make qada later.', 'مسافر اور حقیقی بیمار — بعد میں قضا کریں۔'),
  ('19f4d605a232a4f750fd218ff9340d1430b9fc4fc55bdba56b327adf3de801b5', 'ur-roman', 'The traveller (musafir) and the genuinely sick — make qada later.', 'musafir aur haqeeqi beemar — baad me qaza karein.'),
  ('bb7151fa8f6d2a6a7e4602060c9ceba8a944151a9ee3e41d88ca0d4bbea94bad', 'ur', 'The menstruating woman and the woman in nifas — fasting is not valid; make qada later.', 'حیض والی عورت اور نفاس والی عورت — روزہ درست نہیں؛ بعد میں قضا کریں۔'),
  ('77f970673da5d5c58c6427b08739fb1d2f84c48b0e1c54d3c7984e4f7a5ae2d3', 'ur-roman', 'The menstruating woman and the woman in nifas — fasting is not valid; make qada later.', 'haiz wali aurat aur nifaas wali aurat — roza durust nahin; baad me qaza karein.'),
  ('6ffc2287a4beeb35b2352ff8daf819369e3af4e2414c398f590d71fcd6eb0eb1', 'ur', 'The pregnant or nursing woman who fears harm — make qada later.', 'حاملہ یا دودھ پلانے والی عورت جسے نقصان کا اندیشہ ہو — بعد میں قضا کرے۔'),
  ('e40d50bf806a34e8a5fcda94f79739a293f50c49d8366705de0179f34af93f2a', 'ur-roman', 'The pregnant or nursing woman who fears harm — make qada later.', 'haamila ya doodh pilane wali aurat jise nuqsaan ka andesha ho — baad me qaza kare.'),
  ('c400a17a5a09f60045a8e25376e412a98b20992d515ab0c589685b81c455d1fe', 'ur', 'The very old or terminally ill who cannot fast — give fidyah (feed a poor person for each day).', 'بہت بوڑھا یا لاعلاج بیمار جو روزہ نہ رکھ سکے — فدیہ دے (ہر دن کے بدلے ایک مسکین کو کھانا کھلائے)۔'),
