  ('ed253009e84882b9b12e8a2827fd940153529fbcccdd30f02b92e1c2189e13a0', 'ur-roman', 'Perform wudu', 'wuzu karein'),
  ('e708f871754a5f42c4b230d8ffaab18100bc4d90e63b86135d911b21139b0e59', 'ur', 'Perform a complete wudu (delay washing the feet if standing in water).', 'مکمل وضو کریں (اگر پانی میں کھڑے ہوں تو پاؤں بعد میں دھوئیں)۔'),
  ('e1b9cfe0777154f94678f67dba6bb371efe1e96d5d3ead40329ee9a2a207cc78', 'ur-roman', 'Perform a complete wudu (delay washing the feet if standing in water).', 'mukammal wuzu karein (agar pani me khade hon to paon baad me dhoyein).'),
  ('81c0f0267e99a13db5b3f7ab7a009727a21d56ca1eec15cc7a56fab9f63b1b1d', 'ur', 'Rinse mouth & nose', 'کلی اور ناک صاف کریں'),
  ('802bfe2d1fc29ece2a5c1c23daaf940ffe15d3a312a333efee10eac5760c92f9', 'ur-roman', 'Rinse mouth & nose', 'kulli aur naak saaf karein'),
  ('89bdf4fb6c0d2066c33191ea61580db6d46b814fb7c560c98f26f2793a0bcb8a', 'ur', 'Gargle the mouth and sniff water into the nose thoroughly — both are obligatory in the Hanafi gusl.', 'منہ میں غرارہ کریں اور ناک میں اچھی طرح پانی چڑھائیں — حنفی غسل میں دونوں فرض ہیں۔'),
  ('63e12427de50a9c03006c89915b9fc885ec230e3cb7e8e75fa1a0bb41d2c8c7f', 'ur-roman', 'Gargle the mouth and sniff water into the nose thoroughly — both are obligatory in the Hanafi gusl.', 'munh me gharara karein aur naak me achhi tarah pani chadhayein — Hanafi ghusl me dono farz hain.'),
  ('c677e2f79fbac4f09f40601d95abbcfa1df8726154b701a5382c769442ad782d', 'ur', 'Pour over head', 'سر پر پانی بہائیں'),
  ('229229a01e36ba82ab7fb581c9567402381190d33b9a159165da5327b6f29964', 'ur-roman', 'Pour over head', 'sar par pani bahayein'),
  ('2805fb494dc6d115d642c51cf7a388327d97b2b337b6f8e71d2e15bfb23dafef', 'ur', 'Pour water over the head three times.', 'سر پر تین بار پانی بہائیں۔'),
  ('614b69ed041920d732b3727d08cdd343316c4c866e3fb6ef13b1094f693eec46', 'ur-roman', 'Pour water over the head three times.', 'sar par teen baar pani bahayein.'),
  ('d915b8a9aa4475adafb18606baa0ba365daf4b35248a57de2fccd16bc3eaba2e', 'ur', 'Right then left', 'پہلے دائیں پھر بائیں'),
  ('9f2eecb8b12bba0bebf090900fa0762b4128de0819b5807e3c4b47af5d5993c4', 'ur-roman', 'Right then left', 'pehle dayein phir bayein'),
  ('3adab7b3fa70addab44f674c5ab9e94bd99a841cfad03bd4e8b7a6346a09a7cc', 'ur', 'Pour water over the right shoulder three times, then the left, rubbing the skin.', 'دائیں کندھے پر تین بار پانی بہائیں، پھر بائیں پر، جلد کو ملتے ہوئے۔'),
  ('66d4ce2ea594b6a53f98be3fa394081a8656610c5519471e3840b0a8e958b05f', 'ur-roman', 'Pour water over the right shoulder three times, then the left, rubbing the skin.', 'dayein kandhe par teen baar pani bahayein, phir bayein par, jild ko malte hue.'),
  ('749ca51b1710bf648261e64b47e85c4d7e5d9918e6d27f8ffa5957b6118f8ba6', 'ur', 'Whole body', 'پورا جسم'),
  ('5a4ba4ebedca38a325cc7159935cf593e31e18d3b22956662d677c6ced854a1a', 'ur-roman', 'Whole body', 'poora jism'),
  ('95fe4597da35d53f4708676ff03a69fa73d66ee499982438ea14a3aae1fcad09', 'ur', 'Ensure water reaches every part — under the arms, navel, back — no dry spot remains.', 'یقینی بنائیں کہ پانی ہر حصے تک پہنچے — بغلوں کے نیچے، ناف، کمر — کوئی خشک جگہ نہ رہے۔'),
  ('aa3ce66f620625cabd5085eb3ad54bb945d8059df4cd2f8506061ff1950ec76f', 'ur-roman', 'Ensure water reaches every part — under the arms, navel, back — no dry spot remains.', 'yaqeeni banayein ke pani har hisse tak pahunche — baghlon ke neeche, naaf, kamar — koi khushk jagah na rahe.'),
  ('1d9f966851424effa2836d70cb1f18e99eb378677654a679585116e045a204f0', 'ur', 'Intention', 'نیت'),
  ('0a342d8c53d0dee4772190f0fa90cf7ac5033c1efbe2e63db8b699d0fdaaa496', 'ur-roman', 'Intention', 'niyyat'),
  ('63beb7ca48364be819bb98cf84121e83428aafd629ecef57df3821a8acc675c8', 'ur', 'Make the intention for tayammum and say Bismillah.', 'تیمم کی نیت کریں اور بسم اللہ کہیں۔'),
  ('851c6021905f8d228be58bbf9f8f581b0eda25e319b6cda86f9aade39a534183', 'ur-roman', 'Make the intention for tayammum and say Bismillah.', 'tayammum ki niyyat karein aur Bismillah kahein.'),
  ('481081296050a5c156ff870fed1da3eb59e4c9af4253290aa708f60e63650d17', 'ur', 'Strike the earth', 'زمین پر ہاتھ ماریں'),
  ('9de7321462198115ec153b9baf1789069c86f1125d77f6c9bc51bf5869c70063', 'ur-roman', 'Strike the earth', 'zameen par haath maarein'),
  ('f39eb9e8759c23244d9a6c7da829e0a115c90d7822bbbc4fd1139fbec9320603', 'ur', 'Strike both palms on clean earth, dust, stone or a dusty wall.', 'دونوں ہتھیلیاں پاک مٹی، گرد، پتھر یا گرد آلود دیوار پر ماریں۔'),
  ('1ff1190083e63701f3030bfa367b051312bfeef172422f55d4b70e0364080a60', 'ur-roman', 'Strike both palms on clean earth, dust, stone or a dusty wall.', 'dono hatheliyan paak mitti, gard, patthar ya gard-aalood deewar par maarein.'),
  ('593fc81d72b384c1143f05b0f17c72c5f31c408711efe04b3aed903a65ed5d88', 'ur', 'Wipe the face', 'چہرے کا مسح'),
  ('8aba72aed03de92f2384ca7db6bb3b9a2fc9b7868ffd58bddd5b4e109028c0d6', 'ur-roman', 'Wipe the face', 'chehre ka masah'),
  ('82c7a61a30bec4d3f868c0cc5ce0c05f3291f5325cb07f9be8fa46bb6615b3fb', 'ur', 'Wipe the entire face once with both hands.', 'دونوں ہاتھوں سے پورے چہرے کا ایک بار مسح کریں۔'),
  ('c927f7cb5978f30f79ad60d055b48b1abebec4c1ac1b56110c95fed4b41cb7ff', 'ur-roman', 'Wipe the entire face once with both hands.', 'dono haathon se poore chehre ka ek baar masah karein.'),
  ('8fbfe66f5a9d572b27507010470c51e2f3ab5ea8c3246b2b38a6118fa1dc17a0', 'ur', 'Strike again', 'دوبارہ ہاتھ ماریں'),
  ('5d8bc7b05b10e307f5f4d7aae020c2ac5299e5b33fc980b0e74ca3b8984ab2dc', 'ur-roman', 'Strike again', 'dobara haath maarein'),
  ('b046e61693c6799be7002a6703d4eaf718de793f593a4ec0f9b33dcdabb5ccca', 'ur', 'Strike the palms on the surface a second time and dust off excess.', 'ہتھیلیاں دوسری بار سطح پر ماریں اور زائد گرد جھاڑ دیں۔'),
  ('714709db283dce2f0b150d372ca9fea838ce7a5079f614bd33f276a6dbfcdbc5', 'ur-roman', 'Strike the palms on the surface a second time and dust off excess.', 'hatheliyan doosri baar satah par maarein aur zaaid gard jhaad dein.'),
  ('cad3ba650b1317670680a15436aa10cd07174e1308056598f9fd47867ded8606', 'ur', 'Wipe right arm', 'دائیں بازو کا مسح'),
  ('71d8a11ea46ce8370699c00bbe69554e154b849977b334561862be2803b399f8', 'ur-roman', 'Wipe right arm', 'dayein baazu ka masah'),
  ('020439e02c9b0b7e98235170438198c741342cf857a7d92c067a1feb2fcc230d', 'ur', 'Wipe the right arm from the fingertips up to and including the elbow.', 'دائیں بازو کا انگلیوں کے سرے سے کہنی سمیت مسح کریں۔'),
  ('210284220a01765440e2e9afe5659102b4253e41d17162613d7e37ddf4f7ff47', 'ur-roman', 'Wipe the right arm from the fingertips up to and including the elbow.', 'dayein baazu ka ungliyon ke sire se kohni samet masah karein.'),
  ('d840a51c13a73fc7465b6b8da65959501de4e8083bfc260f36f07fd3a732ce49', 'ur', 'Wipe left arm', 'بائیں بازو کا مسح'),
  ('54da5ea04af8e1394c88a92e40e70824e303c9dc3aa0e178319ff22a6dff1a6c', 'ur-roman', 'Wipe left arm', 'bayein baazu ka masah'),
  ('0fb06bc78186388e3f862637a0ccc01927b9ddabab0ead800bc8be186d3fcb03', 'ur', 'Wipe the left arm from the fingertips up to and including the elbow.', 'بائیں بازو کا انگلیوں کے سرے سے کہنی سمیت مسح کریں۔'),
  ('fd0d18c870a57ebf8ae8ee169acc70f2ef16396fbb636285f4d54a8a05f425f3', 'ur-roman', 'Wipe the left arm from the fingertips up to and including the elbow.', 'bayein baazu ka ungliyon ke sire se kohni samet masah karein.'),
  ('df209f2e71ddb2f75f6291dc64c0968b310af7e3ccf3b08d70d277a38cf0fc59', 'ur', 'Rak’ah 1 — Niyyah & Takbir', 'پہلی رکعت — نیت اور تکبیر'),
  ('b2b371ff456aab7da5f788661b0e00fcada09703533036d06265c4abde4e73df', 'ur-roman', 'Rak’ah 1 — Niyyah & Takbir', 'pehli rakat — niyyat aur takbeer'),
  ('33c75728725b577ebb09d2f22c08790fba081c1610c8d3b19e8e020718fed633', 'ur', 'Intend two rak’ah nafl. Men raise the hands to the ears, women to the shoulders, say “Allahu Akbar”, then fold the hands (men below the navel, women on the chest).', 'دو رکعت نفل کی نیت کریں۔ مرد ہاتھ کانوں تک اٹھائیں، عورتیں کندھوں تک، “Allahu Akbar” کہیں، پھر ہاتھ باندھیں (مرد ناف کے نیچے، عورتیں سینے پر)۔'),
  ('6642b15fbfad03b26c7454d2e15ecffe93aadafa0077821282a2b15d2f9358ff', 'ur-roman', 'Intend two rak’ah nafl. Men raise the hands to the ears, women to the shoulders, say “Allahu Akbar”, then fold the hands (men below the navel, women on the chest).', 'do rakat nafl ki niyyat karein. mard haath kaanon tak uthayein, auratein kandhon tak, “Allahu Akbar” kahein, phir haath baandhein (mard naaf ke neeche, auratein seene par).'),
  ('6601bd6eeac1d808878d8241964dd9cea8bc8fd273212df282bf77e57afcd9f8', 'ur', 'Sana(Thana)', 'ثنا'),
  ('e621ad10a1083e43dfc03b93c0d8c56a4f433d8c4f8e18f565ace9d89d7f8d26', 'ur-roman', 'Sana(Thana)', 'Sana'),
  ('b4b88093c2a4bc6a33b60758a323fa3f5bf40d65d79abe386bdbb90466ef92a0', 'ur', 'Recite the Sana(Thana): “Subhanakal-lahumma wa bihamdika, wa tabarakasmuka, wa ta’ala jadduka, wa la ilaha ghairuk.”', 'ثنا پڑھیں: “Subhanakal-lahumma wa bihamdika, wa tabarakasmuka, wa ta’ala jadduka, wa la ilaha ghairuk.”'),
  ('bb02e2f331a8e89315655a1248690662629d40d174cbbc5e07d4cacecdad7fc6', 'ur-roman', 'Recite the Sana(Thana): “Subhanakal-lahumma wa bihamdika, wa tabarakasmuka, wa ta’ala jadduka, wa la ilaha ghairuk.”', 'Sana padhein: “Subhanakal-lahumma wa bihamdika, wa tabarakasmuka, wa ta’ala jadduka, wa la ilaha ghairuk.”'),
  ('959a57130761a8f69731d16fd659594d54b776da54571da306a07ece92c65597', 'ur', 'Qirat', 'قرأت'),
  ('2f9b4b377239991d012032820481354efe5e89389f905ed6017f2bfda845db97', 'ur-roman', 'Qirat', 'qiraat'),
  ('565b657d6909fc84fb737102ad4ab2f799ac60652408e792abe559baf2a39551', 'ur', 'Recite Ta’awwudh and Bismillah, then Surah Al-Fatiha, say Ameen quietly, then recite another surah (e.g. Al-Ikhlas).', 'تعوذ اور بسم اللہ پڑھیں، پھر سورۃ الفاتحہ، آہستہ آمین کہیں، پھر کوئی اور سورت پڑھیں (مثلاً الاخلاص)۔'),
  ('af801f8b0f84ee329d45d3a554dc11b8ea5ebd86b3328508039a588b93de3fdc', 'ur-roman', 'Recite Ta’awwudh and Bismillah, then Surah Al-Fatiha, say Ameen quietly, then recite another surah (e.g. Al-Ikhlas).', 'Taawwuz aur Bismillah padhein, phir Surah Al-Fatiha, aahista Ameen kahein, phir koi aur surat padhein (masalan Al-Ikhlas).'),
  ('da999f7138980756a2883f61dea3694cdff1f0721ede5aca99c5e502e4dea43f', 'ur', 'Ruku', 'رکوع'),
  ('553fa417a5a8dcb2cfd4e1bd1f915bef504d37ed0cdc5c35bda9b930c8dcd381', 'ur-roman', 'Ruku', 'ruku'),
  ('8baec258890f4cab64407fa6215026235102a714cf62d1d27db445ac1ee51687', 'ur', 'Say “Allahu Akbar” and bow; recite “Subhana Rabbiyal Azeem” three times.', '“Allahu Akbar” کہیں اور رکوع کریں؛ “Subhana Rabbiyal Azeem” تین بار پڑھیں۔'),
  ('d2d9088492e08033945112159c710cbc52690fb5c86cdbdb167c9a11d60255da', 'ur-roman', 'Say “Allahu Akbar” and bow; recite “Subhana Rabbiyal Azeem” three times.', '“Allahu Akbar” kahein aur ruku karein; “Subhana Rabbiyal Azeem” teen baar padhein.'),
  ('47301b94bef41deceb879934e01917060be5c693794a7ab76aa79ec6fd16ccec', 'ur', 'Qawmah', 'قومہ'),
  ('868d118e60852a41764e77685ddd2cee5142c22bfe892f965a35f1fc4f1d1d8c', 'ur-roman', 'Qawmah', 'qawmah'),
  ('3b9fe9e5226490a8959dd8413d62dbc7cf3266c3da7054422b214c7073c6ac8a', 'ur', 'Rise fully upright, saying “Sami’Allahu liman hamidah, Rabbana lakal hamd.”', 'پوری طرح سیدھے کھڑے ہوں، کہتے ہوئے “Sami’Allahu liman hamidah, Rabbana lakal hamd.”'),
  ('baa7d56b9fa55010e656f77a99a22d47cea338780570fd7c162fab5d72136ca9', 'ur-roman', 'Rise fully upright, saying “Sami’Allahu liman hamidah, Rabbana lakal hamd.”', 'poori tarah seedhe khade hon, kehte hue “Sami’Allahu liman hamidah, Rabbana lakal hamd.”'),
  ('f95d7db8c67369bfa9c27a731f3e52e48bb1465a0c320780dd091c037a451426', 'ur', 'Sajdah 1', 'پہلا سجدہ'),
  ('d3da61710ac142a4ab77eb6886b3c76b07c39003dc0c9ab24d439e1c63bf23d7', 'ur-roman', 'Sajdah 1', 'pehla sajda'),
  ('33e3f3061577434a761cf61acd88feafd9cd418cbe92f184446c1f3c3e215812', 'ur', 'Say “Allahu Akbar”, prostrate with forehead and nose on the ground; recite “Subhana Rabbiyal A’la” 3 or 5 or 7 times.', '“Allahu Akbar” کہیں، پیشانی اور ناک زمین پر رکھ کر سجدہ کریں؛ “Subhana Rabbiyal A’la” 3 یا 5 یا 7 بار پڑھیں۔'),
  ('a161382da2c7d6cf1383737c8be6c261d5f1f2781088a5c0807f0b4c51b44f21', 'ur-roman', 'Say “Allahu Akbar”, prostrate with forehead and nose on the ground; recite “Subhana Rabbiyal A’la” 3 or 5 or 7 times.', '“Allahu Akbar” kahein, peshani aur naak zameen par rakh kar sajda karein; “Subhana Rabbiyal A’la” 3 ya 5 ya 7 baar padhein.'),
  ('a7bd7775e782a73af4215b37b986537f19e4032643d5f5ad6a5e16fd6c23166c', 'ur', 'Jalsa', 'جلسہ'),
  ('812afde8d0217d5b9c38b3dccd614e795f275bd505ac3f151989250fa10c6267', 'ur-roman', 'Jalsa', 'jalsa'),
  ('9185c8636b526e1af2a27a13b231b3edc634fccaad2bd4a37085fd9db9e5cc7c', 'ur', 'Say “Allahu Akbar” and sit up calmly for a moment between the two prostrations.', '“Allahu Akbar” کہیں اور دو سجدوں کے درمیان لمحہ بھر اطمینان سے بیٹھیں۔'),
  ('c2d560a5572c880ec371ac7a41829d9a0aa952b07b1789fdea50234a93bec0b3', 'ur-roman', 'Say “Allahu Akbar” and sit up calmly for a moment between the two prostrations.', '“Allahu Akbar” kahein aur do sajdon ke darmiyaan lamha bhar itminaan se baithein.'),
  ('472df761be495ec579113ad3c6fe6dbbf4aceb9a60ba9e8a14f30b089ba03dcc', 'ur', 'Sajdah 2', 'دوسرا سجدہ'),
  ('6fd29e004ef787e1c5dabe0d730212bb18522f2ce0211c84e875eca5705508fc', 'ur-roman', 'Sajdah 2', 'doosra sajda'),
  ('6422850a97b38614dbd0ba82afd62075ba393c2071da0f359823c75db58a9f84', 'ur', 'Say “Allahu Akbar” and prostrate a second time with the same tasbih.', '“Allahu Akbar” کہیں اور اسی تسبیح کے ساتھ دوسرا سجدہ کریں۔'),
  ('c9cfd78d2126061fe343bfc46ec5f7560f3415b101e24b18687d7c9ab0b2687c', 'ur-roman', 'Say “Allahu Akbar” and prostrate a second time with the same tasbih.', '“Allahu Akbar” kahein aur usi tasbeeh ke saath doosra sajda karein.'),
  ('41ea1a3198654f75ee605c7a0160f099ae5361d4282af136e3fb49827d4f988a', 'ur', 'Rak’ah 2 — Stand', 'دوسری رکعت — کھڑے ہوں'),
  ('5eee4e69a1dc3ca7e476837c86fc5f46516486de19614aa4a47a9ea44c875638', 'ur-roman', 'Rak’ah 2 — Stand', 'doosri rakat — khade hon'),
  ('5183da93c37abb32e6930b912ed8eafbb232babcfc72dba711e6f3e2556fe8f4', 'ur', 'Say “Allahu Akbar” and rise to stand for the second rak’ah, folding the hands. (No Sana(Thana) or Ta’awwudh this time.)', '“Allahu Akbar” کہیں اور دوسری رکعت کے لیے کھڑے ہوں، ہاتھ باندھ لیں۔ (اس بار ثنا یا تعوذ نہیں)۔'),
  ('c914c9c5316e06cf4d533026f7e08c215b043f3ab5d7651c6ba10b06665202c5', 'ur-roman', 'Say “Allahu Akbar” and rise to stand for the second rak’ah, folding the hands. (No Sana(Thana) or Ta’awwudh this time.)', '“Allahu Akbar” kahein aur doosri rakat ke liye khade hon, haath baandh lein. (is baar Sana ya Taawwuz nahin.)'),
  ('f5a8c31b6e834fa8b2bfcf45c8c83751af1c78dbf211dd32f436083655a70192', 'ur', 'Recite Bismillah, then Surah Al-Fatiha, Ameen, then another surah.', 'بسم اللہ پڑھیں، پھر سورۃ الفاتحہ، آمین، پھر کوئی اور سورت۔'),
  ('bb41e870619c2982b0304667fb84b8e1d3218358cdd69b8faa231f3009970ddd', 'ur-roman', 'Recite Bismillah, then Surah Al-Fatiha, Ameen, then another surah.', 'Bismillah padhein, phir Surah Al-Fatiha, Ameen, phir koi aur surat.'),
