  ('ed26a22d9f07ef2611378e1a88c343d82d7924118ebf40308d022dfc84eaa650', 'ur', 'Then recite Durood-e-Ibrahim: “Allahumma salli ‘ala Muhammadiw wa ‘ala aali Muhammadin kama sallaita ‘ala Ibrahima wa ‘ala aali Ibrahima innaka Hamidum Majid. Allahumma barik ‘ala Muhammadiw wa ‘ala aali Muhammadin kama barakta ‘ala Ibrahima wa ‘ala aali Ibrahima innaka Hamidum Majid.”', 'پھر درودِ ابراہیمی پڑھیں: “Allahumma salli ‘ala Muhammadiw wa ‘ala aali Muhammadin kama sallaita ‘ala Ibrahima wa ‘ala aali Ibrahima innaka Hamidum Majid. Allahumma barik ‘ala Muhammadiw wa ‘ala aali Muhammadin kama barakta ‘ala Ibrahima wa ‘ala aali Ibrahima innaka Hamidum Majid.”'),
  ('8b8b7a48759e8e8ea8221a4183add2116607fd9cf14108db24017b66f8b8668b', 'ur-roman', 'Then recite Durood-e-Ibrahim: “Allahumma salli ‘ala Muhammadiw wa ‘ala aali Muhammadin kama sallaita ‘ala Ibrahima wa ‘ala aali Ibrahima innaka Hamidum Majid. Allahumma barik ‘ala Muhammadiw wa ‘ala aali Muhammadin kama barakta ‘ala Ibrahima wa ‘ala aali Ibrahima innaka Hamidum Majid.”', 'phir Durood-e-Ibrahim padhein: “Allahumma salli ‘ala Muhammadiw wa ‘ala aali Muhammadin kama sallaita ‘ala Ibrahima wa ‘ala aali Ibrahima innaka Hamidum Majid. Allahumma barik ‘ala Muhammadiw wa ‘ala aali Muhammadin kama barakta ‘ala Ibrahima wa ‘ala aali Ibrahima innaka Hamidum Majid.”'),
