  ('4410448f39a5682a6ea5b653334ba1f442481e1d6725b7a28e9d02d8946ea12b', 'ur', 'All praise is for Allah who fed us, gave us drink, and made us Muslims.', 'سب تعریف اللہ کے لیے ہے جس نے ہمیں کھلایا، پلایا، اور مسلمان بنایا۔'),
  ('eaeb261aec0898d9fc41a7ad667a94faa8d17da4cb276fccb008222c249fe533', 'ur-roman', 'All praise is for Allah who fed us, gave us drink, and made us Muslims.', 'sab tareef Allah ke liye hai jis ne humein khilaya, pilaya, aur musalman banaya.'),
  ('159968b678da058d0c54b04f89211bd90d6602bc8cce57405189b36b4d050b7f', 'ur', 'O Allah, in Your name I die and I live.', 'اے اللہ، تیرے ہی نام کے ساتھ میں مرتا ہوں اور جیتا ہوں۔'),
  ('d59212b32ae05ee691c3fb4d910ea07ffdc0f49065f13da615ffe39221328cd9', 'ur-roman', 'O Allah, in Your name I die and I live.', 'aye Allah, tere hi naam ke saath main marta hoon aur jeeta hoon.'),
  ('0cf1e7f6f4643b7fdb13b5e3c9e65bd049a04f5a2b23da81946ae74c8b3abe5e', 'ur', 'All praise is for Allah who gave us life after death, and to Him is the return.', 'سب تعریف اللہ کے لیے ہے جس نے ہمیں مرنے کے بعد زندگی دی، اور اسی کی طرف لوٹنا ہے۔'),
  ('31f2ae91535faff403c94f7b879ea9442c260ed0601c13f6572b6f58e92dbfdc', 'ur-roman', 'All praise is for Allah who gave us life after death, and to Him is the return.', 'sab tareef Allah ke liye hai jis ne humein marne ke baad zindagi di, aur usi ki taraf lautna hai.'),
  ('95b91d09e929ea45801d683c0ce5c3a0d36a18b9d0e3147478e5a55be67f0033', 'ur', 'O Allah, I seek refuge in You from the male and female evil ones.', 'اے اللہ، میں تیری پناہ مانگتا ہوں ناپاک جنوں (نر و مادہ) سے۔'),
  ('2167c75ff35bca206d5e37f4f63e08ebd3544c01043ea0e64136a3f24314498b', 'ur-roman', 'O Allah, I seek refuge in You from the male and female evil ones.', 'aye Allah, main teri panah maangta hoon napaak jinnon (nar o maada) se.'),
  ('483641041bb16e1befb9025f01db5df6657e42c3b6faa763c83ed50ea715c9ba', 'ur', 'I seek Your forgiveness.', 'میں تیری بخشش مانگتا ہوں۔'),
  ('d80c635cee274f37c6f3e18dc814ae8ca308fa4e26884b1d2bb0d7868c94838f', 'ur-roman', 'I seek Your forgiveness.', 'main teri bakhshish maangta hoon.'),
  ('f78e742c6182f92dfd0e8b935d7015d60460dda587a19382d804d10640f9267f', 'ur', 'In the name of Allah, I place my trust in Allah; there is no power nor strength except with Allah.', 'اللہ کے نام سے، میں نے اللہ پر بھروسہ کیا؛ کوئی طاقت اور قوت نہیں مگر اللہ کے ساتھ۔'),
  ('b0b3a461da11a1171a4ad892393077ec50f9718a9b7b0c21d5a6110550be06e0', 'ur-roman', 'In the name of Allah, I place my trust in Allah; there is no power nor strength except with Allah.', 'Allah ke naam se, main ne Allah par bharosa kiya; koi taaqat aur quwwat nahin magar Allah ke saath.'),
  ('483aa4603b3184e3d11366855634e2b163a038bfffd1c4cac453b9ba3cfd0658', 'ur', 'O Allah, open for me the doors of Your mercy.', 'اے اللہ، میرے لیے اپنی رحمت کے دروازے کھول دے۔'),
  ('2b14fbcb8150b179ef36dcd6964c9370de931d01fbee058273c72d3a50fdee01', 'ur-roman', 'O Allah, open for me the doors of Your mercy.', 'aye Allah, mere liye apni rehmat ke darwaze khol de.'),
  ('b873bb9c10bc3496ac2c8aa11c794c1b63a7065d65d73ecd59700a62d9a23887', 'ur', 'O Allah, I ask You from Your bounty.', 'اے اللہ، میں تجھ سے تیرا فضل مانگتا ہوں۔'),
  ('356b02f20b4d38c908c32ff7433857bee9acad1463cf6a2b7e7d20631ac01002', 'ur-roman', 'O Allah, I ask You from Your bounty.', 'aye Allah, main tujh se tera fazl maangta hoon.'),
  ('d4dab6b7e4b99567f4e0f5f545a985a55d7bf24d72487282fb780521fcd735f9', 'ur', 'I bear witness that none is worthy of worship except Allah alone, with no partner, and that Muhammad is His servant and messenger.', 'میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی عبادت کے لائق نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، اور محمد ﷺ اس کے بندے اور رسول ہیں۔'),
  ('c8a1406c6813b1d8ee3eb804701e4c57778382335474b126c0ca798f1bb1ca51', 'ur-roman', 'I bear witness that none is worthy of worship except Allah alone, with no partner, and that Muhammad is His servant and messenger.', 'main gawahi deta hoon ke Allah ke siwa koi ibadat ke laayaq nahin, wo akela hai, us ka koi shareek nahin, aur Muhammad ﷺ us ke bande aur rasool hain.'),
  ('4484fa46f8624219f3878436b88223b9f186c6bbe42d65d1355c5105cf15c941', 'ur', 'All praise is for Allah who clothed me with this and provided it for me without any power or strength from me.', 'سب تعریف اللہ کے لیے ہے جس نے مجھے یہ پہنایا اور بغیر میری کسی طاقت و قوت کے مجھے عطا کیا۔'),
  ('a122360ad715369247b98afc71770ac2682ca2298ebc807538e1cbe02e42b258', 'ur-roman', 'All praise is for Allah who clothed me with this and provided it for me without any power or strength from me.', 'sab tareef Allah ke liye hai jis ne mujhe yeh pehnaya aur bagair meri kisi taaqat o quwwat ke mujhe ata kiya.'),
  ('0fa2d7d9a3ec9c60d7755a480d119ecf9a80c8461be36119c083d4afa4790a71', 'ur', 'Glory to Him who subjected this to us, and we could not have done it. And indeed, to our Lord we will return.', 'پاک ہے وہ جس نے اسے ہمارے تابع کر دیا، ورنہ ہم اس کے قابو میں لانے والے نہ تھے۔ اور بے شک ہم اپنے رب ہی کی طرف لوٹنے والے ہیں۔'),
  ('998a92f1b323cab5beb4a9a7e4f1a55f5a8000cdab8cc91fe26a811bbc4f8928', 'ur-roman', 'Glory to Him who subjected this to us, and we could not have done it. And indeed, to our Lord we will return.', 'paak hai wo jis ne ise hamare taabe kar diya, warna hum ise qaboo me lane wale na the. aur be-shak hum apne rab hi ki taraf lautne wale hain.'),
  ('036bddd68bc3b586cb365bed52765721a96d05e6fbb309056a5c8da2814865cf', 'ur', 'There is no god but Allah, the Mighty, the Forbearing; there is no god but Allah, Lord of the Mighty Throne.', 'اللہ کے سوا کوئی معبود نہیں جو عظمت والا، بردبار ہے؛ اللہ کے سوا کوئی معبود نہیں جو عظیم عرش کا رب ہے۔'),
  ('3db252ff6876fc3b43326a4c035391f23d86b6d71f399dc8947fa71cbefb8b6a', 'ur-roman', 'There is no god but Allah, the Mighty, the Forbearing; there is no god but Allah, Lord of the Mighty Throne.', 'Allah ke siwa koi mabood nahin jo azmat wala, burdbaar hai; Allah ke siwa koi mabood nahin jo azeem arsh ka rab hai.'),
  ('fd049fc58fddb965471220ba6acb8eb4375cddbfed3d4d25b7314cb68aa51f00', 'ur', 'My Lord, increase me in knowledge.', 'اے میرے رب، میرے علم میں اضافہ فرما۔'),
  ('d6dce08a6962d9bad38e69ae429c4e0a0efdfcb5e8907904f92faf166d8dc5f5', 'ur-roman', 'My Lord, increase me in knowledge.', 'aye mere rab, mere ilm me izafa farma.'),
  ('0a2c7ec1ca3ca72f1edaf5a0feca6d132ef5b5e93ec16eebee12a4e8275dbd3f', 'ur', 'In the name of Allah we enter, in the name of Allah we leave, and upon Allah our Lord we rely.', 'اللہ کے نام سے ہم داخل ہوئے، اللہ کے نام سے ہم نکلے، اور اپنے رب اللہ ہی پر ہم نے بھروسہ کیا۔'),
  ('1a791f33dc111573a80c11f46f9e0dac630ae28726ab9e83a603520ca3791fe1', 'ur-roman', 'In the name of Allah we enter, in the name of Allah we leave, and upon Allah our Lord we rely.', 'Allah ke naam se hum dakhil hue, Allah ke naam se hum nikle, aur apne rab Allah hi par hum ne bharosa kiya.'),
  ('56d226462b3eebf9b68d959f8751b9d00c909cbd39eb678b49f36b501e2c8438', 'ur', 'I seek refuge in Allah from the accursed Satan.', 'میں شیطان مردود سے اللہ کی پناہ مانگتا ہوں۔'),
  ('891b8470b5726ca46bdf835d8093ccb1230957cf364a5c40ada7d5158e143118', 'ur-roman', 'I seek refuge in Allah from the accursed Satan.', 'main shaytan mardood se Allah ki panah maangta hoon.'),
  ('6ebf81aa4b011bdfbbebae7db78122095fc602f8c42a0e7833b7674c309267d3', 'ur', 'All praise is for Allah by whose grace all good things are completed.', 'سب تعریف اللہ کے لیے ہے جس کے فضل سے تمام اچھے کام مکمل ہوتے ہیں۔'),
  ('1685bf3d15d754a4678b41fd7d691593ce503f7b9f1e73eb1c70589f6cef0ed3', 'ur-roman', 'All praise is for Allah by whose grace all good things are completed.', 'sab tareef Allah ke liye hai jis ke fazl se tamam achhe kaam mukammal hote hain.'),
  ('b05af6b9c6c05c91cf08f5dcb19bd37bd4ad8a12aee01c7550ed016368eaeaba', 'ur', 'All praise is for Allah. (Listener replies “Yarhamukallah”, then you say “Yahdikumullahu wa yuslihu balakum”.)', 'سب تعریف اللہ کے لیے ہے۔ (سننے والا “Yarhamukallah” کہے، پھر آپ “Yahdikumullahu wa yuslihu balakum” کہیں۔)'),
  ('4e3a8c6723762594405deea4e14ef7f3725755b8d10259c298e0be0fada12d0f', 'ur-roman', 'All praise is for Allah. (Listener replies “Yarhamukallah”, then you say “Yahdikumullahu wa yuslihu balakum”.)', 'sab tareef Allah ke liye hai. (sunne wala “Yarhamukallah” kahe, phir aap “Yahdikumullahu wa yuslihu balakum” kahein.)'),
  ('463683e16768164533d0c188a080cab1b41506f90746595b0ea18c03905d236c', 'ur', 'In the name of Allah. (Drink with the right hand, in three sips.)', 'اللہ کے نام سے۔ (دائیں ہاتھ سے، تین گھونٹ میں پئیں۔)'),
  ('9a5d8792cfc28f8a0a40bf8e6ee4f67a5dd21929a6fae6fa90506abcc7cb41ba', 'ur-roman', 'In the name of Allah. (Drink with the right hand, in three sips.)', 'Allah ke naam se. (dayein haath se, teen ghoont me piyein.)'),
  ('98ce6c0ba4b73f2295344eb4bb4ef53545db09a36ef40f7608fa84ff46287f9f', 'ur', 'The thirst is gone, the veins are moistened, and the reward is confirmed, if Allah wills.', 'پیاس چلی گئی، رگیں تر ہو گئیں، اور اجر ثابت ہو گیا، اگر اللہ نے چاہا۔'),
  ('dab9fe8605e4e1f3beb4c3ef65e2ba09c5b900f32bec7a5fcdbafdef119124a0', 'ur-roman', 'The thirst is gone, the veins are moistened, and the reward is confirmed, if Allah wills.', 'pyaas chali gayi, ragein tar ho gayin, aur ajr saabit ho gaya, agar Allah ne chaha.'),
  ('0cecd509de0fb7af966d8a7a131555f27e145bcb057260833d6a2859d758aa31', 'ur', 'O Allah, (send) a beneficial rain.', 'اے اللہ، نفع بخش بارش برسا۔'),
  ('4203c81a8b8aa58a4b1660dba3e992cd3a774c4d583d26d51c25d66b3e9ff4a8', 'ur-roman', 'O Allah, (send) a beneficial rain.', 'aye Allah, nafa-bakhsh baarish barsa.'),
  ('9c61b76a0f43f7b384ef204b526f79916f743d6a0db746a3030986838e578d0f', 'ur', 'O Allah, I seek refuge in You from worry, grief, incapacity and laziness.', 'اے اللہ، میں تیری پناہ مانگتا ہوں فکر، غم، عاجزی اور سستی سے۔'),
  ('94ebf89e21147cdecf862e89ebcc09647ce0a247b9bbd96d4bf4d2169f03c84b', 'ur-roman', 'O Allah, I seek refuge in You from worry, grief, incapacity and laziness.', 'aye Allah, main teri panah maangta hoon fikr, gham, aajizi aur susti se.'),
  ('0cb5dfb004f5cb4b8e0a17ccca59a9ef816445c3472d151aad7abdefcff14893', 'ur', 'No harm, (it is) a purification, if Allah wills.', 'کوئی حرج نہیں، یہ (گناہوں سے) پاکی ہے، اگر اللہ نے چاہا۔'),
  ('75002d5c6cce24c7826e10fb84324d04151086b9f0e586cf9874923830702d67', 'ur-roman', 'No harm, (it is) a purification, if Allah wills.', 'koi harj nahin, yeh (gunahon se) paaki hai, agar Allah ne chaha.'),
  ('3abd3c69df9efc699a41d7b9328d32814f9406ab6b65ed81eaea8377d85c6b2c', 'ur', 'There is no god but Allah alone… In His hand is all good and He is over all things competent. (Great reward for reciting on entering the market.)', 'اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے… اسی کے ہاتھ میں ہر بھلائی ہے اور وہ ہر چیز پر قادر ہے۔ (بازار میں پڑھنے پر بڑا اجر ہے۔)'),
  ('e0b2d7847eaf7a27e31f3f08a6a7bdea9be19776d59942d6f3bd79980bd3348f', 'ur-roman', 'There is no god but Allah alone… In His hand is all good and He is over all things competent. (Great reward for reciting on entering the market.)', 'Allah ke siwa koi mabood nahin, wo akela hai… usi ke haath me har bhalai hai aur wo har cheez par qaadir hai. (bazaar me padhne par bada ajr hai.)'),
  ('dd033ff8c2e514d9dfdbbd63ddeb88b3f7d9bf788725e3af86ea6a81e27ddc1a', 'ur', 'O Allah, You are my Lord… forgive me, for none forgives sins but You. (Whoever says it with certainty by day and dies that day is of the people of Paradise.)', 'اے اللہ، تو ہی میرا رب ہے… مجھے بخش دے، کیونکہ تیرے سوا کوئی گناہ نہیں بخشتا۔ (جو یقین کے ساتھ دن میں پڑھے اور اسی دن مر جائے وہ جنتی ہے۔)'),
  ('065c09931372ff218306033dee9556e0d7df521c328d2d3fdb39a6d703a7c91f', 'ur-roman', 'O Allah, You are my Lord… forgive me, for none forgives sins but You. (Whoever says it with certainty by day and dies that day is of the people of Paradise.)', 'aye Allah, tu hi mera rab hai… mujhe bakhsh de, kyunke tere siwa koi gunah nahin bakhshta. (jo yaqeen ke saath din me padhe aur usi din mar jaye wo jannati hai.)'),
  ('38b64a1253dcd60483530787b91dba564024cd6411e5b0e8b5d76dc501055d85', 'ur', '1st Kalima — Tayyaba', 'پہلا کلمہ — طیبہ'),
  ('b7b1f8ec6efa7eecde1aec0c5c5b5ff3d958d27e0b9b10ee1034fa2905ae3ce9', 'ur-roman', '1st Kalima — Tayyaba', 'pehla kalima — Tayyaba'),
  ('e537f51f45e6c80955888a834361f09ecbbe6e445a7b18e3abd9a6126aea73a0', 'ur', '2nd Kalima — Shahadat', 'دوسرا کلمہ — شہادت'),
  ('1c773cbe9bcb6c4a224de583685ca1b26a457e263c55421c0af940889b0a6545', 'ur-roman', '2nd Kalima — Shahadat', 'doosra kalima — Shahadat'),
  ('04e4abd0b11958edcb828c5d00ed42c47c74c6fab09bea474fbde6283a76d5a9', 'ur', '3rd Kalima — Tamjeed', 'تیسرا کلمہ — تمجید'),
  ('8056b1378badfe88911a24d93d2f7d220d0445401b78fbd1b15a3a1386c5c6ac', 'ur-roman', '3rd Kalima — Tamjeed', 'teesra kalima — Tamjeed'),
  ('4eb7d06127b0c78b176d3c9bb49f8f4d50b75ee7fae819827da4f113c665046e', 'ur', '4th Kalima — Tawheed', 'چوتھا کلمہ — توحید'),
  ('0c132164bf78f74f0d2122edbe59d318d03136c4f96b78c9790ffcdeaacd8201', 'ur-roman', '4th Kalima — Tawheed', 'chautha kalima — Tawheed'),
  ('71098bfe70ffd4cb1b3342f2b8b39c8a16e476f00b88b3cf9a5a9759fd374f03', 'ur', 'Short Durood', 'مختصر درود'),
  ('20f543c11567824361e80f2e6ced468515770358ca0cc48a9e15ced30d986bb0', 'ur-roman', 'Short Durood', 'mukhtasar Durood'),
  ('e07e7aafaeaddb63e170d995689bd4aa4101a6b2063f59e6552a9b9f5a5a72bd', 'ur', 'Astaghfar', 'استغفار'),
  ('195f9d1c60235cb3c7b8a2163dd8c6c3a6be6d4030e61feffef3005b2b2c87f5', 'ur-roman', 'Astaghfar', 'Astaghfar'),
  ('fb27ae11c39bec4491e2e706e67964bcac127a09e72efbec20565d67ba396750', 'ur', 'Astaghfar (full)', 'استغفار (مکمل)'),
  ('bc6921d844ef10595449810223803296a4fd316f3f3fc5ef3a35796e9648a2d2', 'ur-roman', 'Astaghfar (full)', 'Astaghfar (mukammal)'),
  ('c7d29de798644bb095385ecd8a3a8ed4936411f3cf1151f29069df871477627e', 'ur', 'SubhanAllahi wa bihamdihi', 'سبحان اللہ وبحمدہ'),
  ('414afc5bd3b6ae48b9a8d6e35186204824f4bf24a9a69608085c5699a2248d4c', 'ur-roman', 'SubhanAllahi wa bihamdihi', 'SubhanAllahi wa bihamdihi'),
  ('7c7492516f7c08cd9ca8287172eccf35cd9cef4cb2544963f933cec38a018211', 'ur', 'SubhanAllah', 'سبحان اللہ'),
  ('264b5db6d39ccd1c75c946326e74b1f60b07e699d46bb791e11fbea24c770886', 'ur-roman', 'SubhanAllah', 'SubhanAllah'),
  ('90601acca5ed6972631f02a1e98002cf61cb2d3b4ba629b0b1cb2ce96c734c4d', 'ur', 'Alhamdulillah', 'الحمد للہ'),
  ('700f99de95de53da97db8344341ed852d5604ae3d929725ad88c91f98a267339', 'ur-roman', 'Alhamdulillah', 'Alhamdulillah'),
  ('bc6a3fbf3aad1982e2c1159a1def9bcac1a7119f0264d3e0658980c9211761a5', 'ur', 'Allahu Akbar', 'اللہ اکبر'),
  ('188e65d0f18a0be8c9ffc6071a40a429536de87c0b8d1c314e111304c3787064', 'ur-roman', 'Allahu Akbar', 'Allahu Akbar'),
  ('ee874be62cab67a7693efb7fbdca4da9d4ad02afcb2ac43c220dd930db9f4189', 'ur', 'For strength — La hawla wa la quwwata illa billah', 'قوت کے لیے — لا حول ولا قوۃ الا باللہ'),
  ('eafe11c02ae58e33efb42e5a5c72c042f68c292591519bab0c7dafb48dfc9fc0', 'ur-roman', 'For strength — La hawla wa la quwwata illa billah', 'quwwat ke liye — La hawla wa la quwwata illa billah'),
  ('0119e5fc7b3de33aca243d44ff6ad2ba482bfc51d2e427f6f901b66fe1904116', 'ur', 'Beloved words — SubhanAllahi wa bihamdihi, SubhanAllahil-Azim', 'محبوب کلمات — سبحان اللہ وبحمدہ، سبحان اللہ العظیم'),
  ('f633d1a5318f44c437bdcb3ccf1bffc9c8393a7ba17e0e2072b01f9d4615165a', 'ur-roman', 'Beloved words — SubhanAllahi wa bihamdihi, SubhanAllahil-Azim', 'mehboob kalimaat — SubhanAllahi wa bihamdihi, SubhanAllahil-Azim'),
  ('e61e49ddfc37fac642c94619284bad7d7e969e8c096e50b4b134060f1e043dd2', 'ur', 'For rizq & barkat — Istighfar', 'رزق اور برکت کے لیے — استغفار'),
  ('55471034e6d3115261f94f5c2babc82fe294d60bd81b6351062b8a7a8634b79e', 'ur-roman', 'For rizq & barkat — Istighfar', 'rizq aur barkat ke liye — Istighfar'),
  ('015b8fc1427339cad300c8ca29e430ac90b1349699f823233e33344ca5815dee', 'ur', 'For relief from distress — Dua of Yunus', 'پریشانی سے نجات کے لیے — دعائے یونس'),
  ('490f4719702a33ea2e22e13861a863407a3a38c6a2e897f082547270015386f6', 'ur-roman', 'For relief from distress — Dua of Yunus', 'pareshani se nijaat ke liye — Dua-e-Yunus'),
  ('16d8870b2ae0ec1e5d5a70e5a87f7dde112220cbe677ab76ff3c5a029583c45b', 'ur', 'For reliance & protection — Hasbunallah', 'بھروسے اور حفاظت کے لیے — حسبنا اللہ'),
  ('531d62bfe8ac1ab4c4651ac998b12c9a3c53f8df290e6bb092245b969141ed1c', 'ur-roman', 'For reliance & protection — Hasbunallah', 'bharose aur hifazat ke liye — Hasbunallah'),
  ('e13977c445157e07d2df2200da7412beec22a9c6697424ee150d021ffddd3578', 'ur', 'For needs — Durood upon the Prophet ﷺ', 'حاجات کے لیے — نبی ﷺ پر درود'),
  ('05f124a49bb5f7f34a799d277148e9eb0de3f0b7adfef85fdd821cd6f26a8280', 'ur-roman', 'For needs — Durood upon the Prophet ﷺ', 'haajaat ke liye — Nabi ﷺ par Durood'),
  ('bab41620a01a5584d5b14255ab1bf3c23d035dc854e89f18907d4e2bc260c972', 'ur', 'For great reward — La ilaha illallah…', 'بڑے اجر کے لیے — لا الہ الا اللہ…'),
  ('f992ba38a9676edc46f3e6ec84faedd7d9e683bf647cb3439bf6216a1d6f4e1b', 'ur-roman', 'For great reward — La ilaha illallah…', 'bade ajr ke liye — La ilaha illallah…'),
  ('50cdd4a987c97883eae9d629e065140d92f6f49a023a26740f485b1fe2a23a47', 'ur', 'There is no god but Allah; Muhammad is the Messenger of Allah.', 'اللہ کے سوا کوئی معبود نہیں؛ محمد ﷺ اللہ کے رسول ہیں۔'),
  ('fa83c8ca2633ec4de3832973589094935892851a9694d65803a4297dafb6e293', 'ur-roman', 'There is no god but Allah; Muhammad is the Messenger of Allah.', 'Allah ke siwa koi mabood nahin; Muhammad ﷺ Allah ke rasool hain.'),
  ('3a92f2dc908a0120399450b6b2d33f6fb6bbde7aa4d4af0fba0e377daec80607', 'ur', 'Glory be to Allah, all praise to Allah, there is no god but Allah, and Allah is the Greatest.', 'اللہ پاک ہے، سب تعریف اللہ کے لیے، اللہ کے سوا کوئی معبود نہیں، اور اللہ سب سے بڑا ہے۔'),
  ('4686428de8d70f63ff7694a5a18fcb7bb1f9dfbf50e1f8cb743454d154138647', 'ur-roman', 'Glory be to Allah, all praise to Allah, there is no god but Allah, and Allah is the Greatest.', 'Allah paak hai, sab tareef Allah ke liye, Allah ke siwa koi mabood nahin, aur Allah sab se bada hai.'),
  ('a4b317d76c82c827823037e345c991bc95aae0a3cca19e7cf92ae3f225b4a86e', 'ur', 'There is no god but Allah alone, with no partner. His is the dominion and His is all praise, and He has power over everything.', 'اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں۔ اسی کی بادشاہی ہے اور اسی کے لیے سب تعریف ہے، اور وہ ہر چیز پر قادر ہے۔'),
  ('733f1c7ff28bbdb2c27dea526bde2ba0a1dbe1c59dfdea9f2fba08abe8e6ec1d', 'ur-roman', 'There is no god but Allah alone, with no partner. His is the dominion and His is all praise, and He has power over everything.', 'Allah ke siwa koi mabood nahin, wo akela hai, us ka koi shareek nahin. usi ki badshahi hai aur usi ke liye sab tareef hai, aur wo har cheez par qaadir hai.'),
  ('860cb19f5512aba9a9652b0f962beb0997b251e4a3049ad779423a069346c4bf', 'ur', 'O Allah, send blessings upon Muhammad and the family of Muhammad.', 'اے اللہ، محمد ﷺ اور آلِ محمد پر رحمت بھیج۔'),
  ('14b7e8bbd488b1c7f89dc31d1592eca6f9923dd6c531bfa6d543467e85fca862', 'ur-roman', 'O Allah, send blessings upon Muhammad and the family of Muhammad.', 'aye Allah, Muhammad ﷺ aur aal-e-Muhammad par rehmat bhej.'),
  ('305a36dca62fdd075a6068d8189e407447a209ae486a3e19cb66f56eb4e28c35', 'ur', 'I seek forgiveness from Allah.', 'میں اللہ سے بخشش مانگتا ہوں۔'),
  ('4dec9a4f1dd5ab86144a9e7df1cdb9092d228a143348ba1f31835973ca84bf7f', 'ur-roman', 'I seek forgiveness from Allah.', 'main Allah se bakhshish maangta hoon.'),
  ('fee4458f70a72be6e8781fdd2b6acfc2f838b0b1d6327ca7d71fb4e0735664c7', 'ur', 'I seek forgiveness from Allah, my Lord, from every sin, and I turn to Him in repentance.', 'میں اللہ، اپنے رب سے، ہر گناہ کی بخشش مانگتا ہوں، اور اسی کی طرف توبہ کرتا ہوں۔'),
  ('c829fa6872903ba0a8895046b3f592eb568a7cd4a5c2fdf11a56c2ae64e3b63d', 'ur-roman', 'I seek forgiveness from Allah, my Lord, from every sin, and I turn to Him in repentance.', 'main Allah, apne rab se, har gunah ki bakhshish maangta hoon, aur usi ki taraf tauba karta hoon.'),
  ('91afc120770b78193d5449b96a6be855592115df9570b85a93b030337cf91089', 'ur', 'Glory be to Allah and to Him is all praise.', 'اللہ پاک ہے اور اسی کے لیے سب تعریف ہے۔'),
  ('8bc8af74e22e2908f0ed80fd5c534e83caf2d938b572f9dd265f93b237042243', 'ur-roman', 'Glory be to Allah and to Him is all praise.', 'Allah paak hai aur usi ke liye sab tareef hai.'),
  ('9a3d43d8b2d4a33f167dcf565fe8814a23fe6af998b293df976d93e3c0edbed2', 'ur', 'Glory be to Allah.', 'اللہ پاک ہے۔'),
  ('7ac4d50b50ac7a6002966eabbbb328e47615cbd3c843b3b608a68b557dc82282', 'ur-roman', 'Glory be to Allah.', 'Allah paak hai.'),
  ('32f8e4b2abbf85f5b16c71968bbef5033c5176e0a29214b23b8afc1ecfb2d672', 'ur', 'All praise is for Allah.', 'سب تعریف اللہ کے لیے ہے۔'),
  ('d7f9d3f981164b9ea47a4c586aa6f4445a38c40eb51298081f445d7b22673bd3', 'ur-roman', 'All praise is for Allah.', 'sab tareef Allah ke liye hai.'),
  ('c047cd34f6e82e46c9a7b03500d18a3fcdc2583b063005cebc199f6266cca8c6', 'ur', 'Allah is the Greatest.', 'اللہ سب سے بڑا ہے۔'),
  ('c2c20bfd7aaed52f01c9696a47837bf26ec04e4c7b27aa807f950dce52edd7d3', 'ur-roman', 'Allah is the Greatest.', 'Allah sab se bada hai.'),
  ('650f2eba45bbca0e96c338804b66b0a5b2af24878155b05653b26638136f108b', 'ur', 'There is no power nor strength except with Allah.', 'کوئی طاقت اور قوت نہیں مگر اللہ کے ساتھ۔'),
  ('1960448869db1e0d41eefecbd5f54d60229b39b9701beed1fab0e1c03b6322c9', 'ur-roman', 'There is no power nor strength except with Allah.', 'koi taaqat aur quwwat nahin magar Allah ke saath.'),
  ('18eddc31a37a12e6c7c0c736af262f2e41aa092c52754fab92a0b6663ab80276', 'ur', 'Glory and praise to Allah; glory to Allah the Most Great.', 'اللہ کی پاکی اور تعریف؛ اللہ عظیم کی پاکی۔'),
  ('7458445d7c0f4fa44009d1a15d963c388be1e876ceadc3b6bc2ea688157088e1', 'ur-roman', 'Glory and praise to Allah; glory to Allah the Most Great.', 'Allah ki paaki aur tareef; Allah azeem ki paaki.'),
  ('040d6a1c71b6c049218ad24523d735e2f40cee6611c83ac0aaa139dc0ed290c5', 'ur', 'I seek forgiveness of Allah my Lord and turn to Him.', 'میں اللہ اپنے رب سے بخشش مانگتا ہوں اور اسی کی طرف رجوع کرتا ہوں۔'),
  ('67700c60ce2b8ae6bbcc021866c25e3ffa596c3d56cf81534c4a8e213ce3d808', 'ur-roman', 'I seek forgiveness of Allah my Lord and turn to Him.', 'main Allah apne rab se bakhshish maangta hoon aur usi ki taraf rujoo karta hoon.'),
  ('887a95c81d6b2cebf18b9b840efb8b57a1a4b30e88f8aa9124eaee0983e55233', 'ur', 'There is no god but You; glory be to You; indeed I was among the wrongdoers.', 'تیرے سوا کوئی معبود نہیں؛ تو پاک ہے؛ بے شک میں ظالموں میں سے تھا۔'),
  ('245c54aeeb205bdbea6f1abd7c11ec5f46d90e81ccfd67ee9e8100d11a7f9096', 'ur-roman', 'There is no god but You; glory be to You; indeed I was among the wrongdoers.', 'tere siwa koi mabood nahin; tu paak hai; be-shak main zaalimon me se tha.'),
  ('794d772233d33b6eb9c7bc6782192ecacc6291d869a9b77d0a1fc31251b7dedc', 'ur', 'Allah is sufficient for us and the best Disposer of affairs.', 'اللہ ہمارے لیے کافی ہے اور وہ بہترین کارساز ہے۔'),
  ('b3e5000ff91c36f8ae22879ccf69028ff4f49017d8c5a33485311da29cbc4d49', 'ur-roman', 'Allah is sufficient for us and the best Disposer of affairs.', 'Allah hamare liye kaafi hai aur wo behtareen kaarsaaz hai.'),
  ('3996f3f1ee5016bdfac8d90667b3e9acb76c510cbb7eff88ea32e7ccecde353d', 'ur', 'O Allah, send blessings and peace upon our Prophet Muhammad.', 'اے اللہ، ہمارے نبی محمد ﷺ پر رحمت اور سلامتی بھیج۔'),
  ('e64746ba185c0d9229c394dd871231c6b4ce47e2335b8f1cfef89f8a30fcf653', 'ur-roman', 'O Allah, send blessings and peace upon our Prophet Muhammad.', 'aye Allah, hamare Nabi Muhammad ﷺ par rehmat aur salamti bhej.'),
  ('a76d02d0e549fdb8e0d0b89902d1fdba6f32ac5e3b1ee28e8f619104fc838d4c', 'ur', 'There is no god but Allah alone… and He is over all things competent.', 'اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے… اور وہ ہر چیز پر قادر ہے۔'),
  ('7c3d74b62a8e59ac6af3cc24becf5fa13be19acd362916abdc16ae4f4882d79d', 'ur-roman', 'There is no god but Allah alone… and He is over all things competent.', 'Allah ke siwa koi mabood nahin, wo akela hai… aur wo har cheez par qaadir hai.'),
  ('ec363de53e502d96779d651f3ff86b86ce6d09e5e7b65c4248ef35e6ce45246b', 'ur', 'I bear witness that none is worthy of worship but Allah alone, with no partner, and that Muhammad is His servant and messenger.', 'میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی عبادت کے لائق نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، اور محمد ﷺ اس کے بندے اور رسول ہیں۔'),
  ('9c2999506ba9fc237ce29f8596351aa3ccc5217483a8ffeede9212383ebf96e3', 'ur-roman', 'I bear witness that none is worthy of worship but Allah alone, with no partner, and that Muhammad is His servant and messenger.', 'main gawahi deta hoon ke Allah ke siwa koi ibadat ke laayaq nahin, wo akela hai, us ka koi shareek nahin, aur Muhammad ﷺ us ke bande aur rasool hain.'),
  ('ea678c043e53ec52e42b5847a8a3ea939666a3ab7508b10e0b470cc4d1da0686', 'ur', 'The Opening', 'کھولنے والی'),
  ('f6da4c585e8e51f73718ec933c3005be4838a8c5a9b17d01d8a79b80eaa36b7f', 'ur-roman', 'The Opening', 'kholne wali'),
  ('f58a3604beaa84a15fad741fa6bfe119c05561b5d30ebb5e111387a140e7f8d9', 'ur', 'The Declining Day', 'گزرتا ہوا زمانہ'),
