  ('a8d5cdd1055d4bf0019de2363c11f43081d1f1a2b17663ffcae36343cb7c739c', 'ur', 'Small Kindnesses', 'روزمرہ کی چھوٹی مدد'),
  ('cb2c1c2a8b41e871da3252b5d6fc6c6f568a3a8c1b2af0f9f2752090daa3dba7', 'ur-roman', 'Small Kindnesses', 'rozmarra ki chhoti madad'),
  ('d21027b3851b581b84887e3790d4d41be5d8aa62d072acb1382b089ed02e5146', 'ur', 'The Disbelievers', 'کافر لوگ'),
  ('a3b28789174169325b68a5968681e9396a652a66f1e81acf336f863f3657289c', 'ur-roman', 'The Disbelievers', 'kafir log'),
  ('2869f2e024b31615b4babf1a94c353af6c79a9402288cd8f7e1fdb17597daac9', 'ur', 'The Divine Support', 'اللہ کی مدد'),
  ('ced2ec254dc0809f57d0a149a2cd04912f28ee038944e103209306718190df2a', 'ur-roman', 'The Divine Support', 'Allah ki madad'),
  ('726bda37e8ca80bc5403269a16744155d86f443b3b824e284d8098f72fa131b9', 'ur', 'The Palm Fibre', 'کھجور کی رسی'),
  ('cf8bd6bac57d684d421e43dcd446e957bd608fa4c18f706d31c5b60261e13db6', 'ur-roman', 'The Palm Fibre', 'khajoor ki rassi'),
  ('55a3cbefcbfbc1068b205889c8a4aea38cc862e1e3886c44ad87ba4ef874d01b', 'ur', 'In the name of Allah, the Most Gracious, the Most Merciful.', 'اللہ کے نام سے جو نہایت مہربان، بہت رحم والا ہے۔'),
  ('82857eccb68ce1c7f100fa5a75ebe2578822f79591d6b295ff3d668d3e9c2f1d', 'ur-roman', 'In the name of Allah, the Most Gracious, the Most Merciful.', 'Allah ke naam se jo nihayat meharban, bahut reham wala hai.'),
  ('9136417afda24c07d0b9a2a631b0f4581d9f117b1593b0aa6c67a9432bcb7fe0', 'ur', 'All praise is for Allah, Lord of all the worlds.', 'سب تعریف اللہ کے لیے ہے جو تمام جہانوں کا رب ہے۔'),
  ('8b5a622cce726ad3f15db686faaf5de2c1d397ae27a35a05c577ce43cd066298', 'ur-roman', 'All praise is for Allah, Lord of all the worlds.', 'sab tareef Allah ke liye hai jo tamam jahanon ka rab hai.'),
  ('7672e329ba7563899de43f8954f75503b1728acde10f987770b50cafbf401dbe', 'ur', 'The Most Gracious, the Most Merciful.', 'نہایت مہربان، بہت رحم والا۔'),
  ('c39be102ba75a5403985287a84b18e597b13bafb1e906078a8494dd755d76b58', 'ur-roman', 'The Most Gracious, the Most Merciful.', 'nihayat meharban, bahut reham wala.'),
  ('3ea28524305b51d4236e7c8ed60f691196a55e3774a6a28f22a15f636906e4cd', 'ur', 'Master of the Day of Judgment.', 'بدلے کے دن کا مالک۔'),
  ('9d6f83d8f3261defaf8a3cfa9b49d15c2f58817ee707e531e45cf0e7422850ae', 'ur-roman', 'Master of the Day of Judgment.', 'badle ke din ka maalik.'),
  ('04cf07681226f4cc9188f706018e7dd24c6faf24d42508e7513422ce667b5cd0', 'ur', 'You alone we worship, and You alone we ask for help.', 'ہم تیری ہی عبادت کرتے ہیں اور تجھ ہی سے مدد مانگتے ہیں۔'),
  ('21a211944c1effa98fe18e5c402d606139b1ad1576edb999c731f5c3a7869939', 'ur-roman', 'You alone we worship, and You alone we ask for help.', 'hum teri hi ibadat karte hain aur tujh hi se madad maangte hain.'),
  ('9e97f47113efa92c3ee5dd5cb0eedc15ea3a4d145c1c042a3d71f0aeb63ee1b3', 'ur', 'Guide us along the straight path.', 'ہمیں سیدھے راستے کی ہدایت دے۔'),
  ('841ac4aef81e77e8899aed17ed691f7238e4387ee36f541f0f9a717d368f2fe2', 'ur-roman', 'Guide us along the straight path.', 'humein seedhe raaste ki hidayat de.'),
  ('efff6b999194af93c0377b27595995351e0f60dddea8ae19ad3c48eca3d9defb', 'ur', 'The path of those You have blessed — not those who earned anger, nor those who went astray.', 'ان لوگوں کا راستہ جن پر تو نے انعام کیا — نہ ان کا جن پر غضب ہوا اور نہ گمراہوں کا۔'),
  ('2a58ebc95d914b36cb46618f4a5930ec7bbc934b633e5e7247d9c207967425d9', 'ur-roman', 'The path of those You have blessed — not those who earned anger, nor those who went astray.', 'un logon ka raasta jin par tu ne inaam kiya — na un ka jin par ghazab hua aur na gumraahon ka.'),
  ('f01e941bea828347126032ac9f2f75474f13d86beee21f07fdd727f231768569', 'ur', 'By time,', 'زمانے کی قسم،'),
  ('49814cb3adb0a7af2123c8bf9edaca33bbd94041c382882514f643f63f48806c', 'ur-roman', 'By time,', 'zamane ki qasam,'),
  ('1ea779211717c307d09d94d47e6b5da4b02eac1a5edc36d972124d48f80f861d', 'ur', 'Indeed, mankind is in loss,', 'بے شک انسان خسارے میں ہے،'),
  ('b44665289a137f936e3b86870c9700a61962fb87d40728ad39c38af2675b2060', 'ur-roman', 'Indeed, mankind is in loss,', 'be-shak insaan khasaare me hai,'),
  ('df8319c7564ecad6fc3dd577db94b003065e500d067cb4bd53ec6c6d0a746508', 'ur', 'Except those who believe, do righteous deeds, and urge one another to truth and to patience.', 'سوائے ان کے جو ایمان لائے، نیک عمل کیے، اور ایک دوسرے کو حق اور صبر کی تلقین کی۔'),
  ('b2faad383a2d424e7881fb65ebea23a804c5a6598626e0dc1200f9b71d77e220', 'ur-roman', 'Except those who believe, do righteous deeds, and urge one another to truth and to patience.', 'siwaye un ke jo imaan laye, nek amal kiye, aur ek doosre ko haq aur sabr ki talqeen ki.'),
  ('9002f30e3d2ec9454938bb073aaa5a1de0060866d3bc26eaf251e56acf55454a', 'ur', 'Say, He is Allah, the One.', 'کہہ دو، وہ اللہ ایک ہے۔'),
  ('5a671e6db709f9909fb32866fdce1ef2990554308a96b9ba54fadaa78dd7b05b', 'ur-roman', 'Say, He is Allah, the One.', 'keh do, wo Allah ek hai.'),
  ('e52e6d532b33c07f599377fc44dec6e53eed99dc43a670e0dc37e808fa52e181', 'ur', 'Allah, the Eternal Refuge.', 'اللہ بے نیاز ہے (سب اسی کے محتاج ہیں)۔'),
  ('24668cf2e074e0b6b8b0a849b8a917bcaa215bed820564f4b4825711e3b169be', 'ur-roman', 'Allah, the Eternal Refuge.', 'Allah be-niyaz hai (sab usi ke muhtaaj hain).'),
  ('58b5f3765780e4779b8cc91ba5f80b1438289b11203803d9f5accbeec45f0931', 'ur', 'He neither begets nor is born,', 'نہ اس کی کوئی اولاد ہے اور نہ وہ کسی سے پیدا ہوا،'),
  ('3f393a2c5c24cb2aeb527aec8247a620e65f5164071978ec6f529620acc640cf', 'ur-roman', 'He neither begets nor is born,', 'na uski koi aulaad hai aur na wo kisi se paida hua,'),
  ('b3abb35e8fa0c77674b19b057f0a90e79dd3a6509d3d7c264e3bce665f99f66c', 'ur', 'Nor is there to Him any equivalent.', 'اور نہ کوئی اس کے برابر ہے۔'),
  ('0ef332eb3d3af57227a5cfb9befe054227eb5fe99b64aa6f851bdeb1b34759f3', 'ur-roman', 'Nor is there to Him any equivalent.', 'aur na koi uske barabar hai.'),
  ('fc526f95dcb46479f1398ab86f2d1ae08f3fc538db17fdcdf8a66445b38e0d70', 'ur', 'Say, I seek refuge in the Lord of daybreak,', 'کہہ دو، میں صبح کے رب کی پناہ مانگتا ہوں،'),
  ('cd5dfd6bd02998147c0c0d3d19b7b90c61f4b1b1c6ded4ec2fd5032d9f441467', 'ur-roman', 'Say, I seek refuge in the Lord of daybreak,', 'keh do, main subah ke rab ki panah maangta hoon,'),
  ('92583bb232c25e599aa97971f2b42e5cc63813033cdd3a731f18824a7fb5f3b2', 'ur', 'From the evil of what He created,', 'اس کی مخلوق کے شر سے،'),
  ('1d49d800b1cb7e99d50be65d6760f0e81157ed89a2f490be64cecdf2b2790faa', 'ur-roman', 'From the evil of what He created,', 'us ki makhlooq ke shar se,'),
  ('eee70a2f2e07df72133c65f8deca48f300d10e9752f0daa395499b160212e77a', 'ur', 'And from the evil of darkness when it settles,', 'اور اندھیرے کے شر سے جب وہ چھا جائے،'),
  ('a9e3d9f149d1c3073474778c44d46dd0b4d2edb061a4788789285ebc8d4f1cc0', 'ur-roman', 'And from the evil of darkness when it settles,', 'aur andhere ke shar se jab wo chha jaye,'),
  ('080549a8206b85f336ae8b8faf8bedc01c8c75b1ca31d80fff678f29c7b98084', 'ur', 'And from the evil of the blowers in knots,', 'اور گرہوں میں پھونکنے والوں (جادوگروں) کے شر سے،'),
  ('a2b2ee8da1cd6694e68b625b12ec33aa9f77468b07eafd3d175da3d34e378f0c', 'ur-roman', 'And from the evil of the blowers in knots,', 'aur girhon me phoonkne walon (jadugaron) ke shar se,'),
  ('1e70311d8b28624cb797ff4173b473976e6cfe26d2a31c5fa5d46516c5a0926d', 'ur', 'And from the evil of an envier when he envies.', 'اور حسد کرنے والے کے شر سے جب وہ حسد کرے۔'),
  ('ecac41988bcb5e1682be61d6f2282632f8a7b2bccabcfdac8b96df2ad43ed6fa', 'ur-roman', 'And from the evil of an envier when he envies.', 'aur hasad karne wale ke shar se jab wo hasad kare.'),
  ('84be5e18c0905faed71492a70182c76358eeb9a6f8fd167babf23243aa25e91f', 'ur', 'Say, I seek refuge in the Lord of mankind,', 'کہہ دو، میں انسانوں کے رب کی پناہ مانگتا ہوں،'),
  ('672690668a74ad46e34fed6db7716b2b0852d22cc29324449a2fa51672665703', 'ur-roman', 'Say, I seek refuge in the Lord of mankind,', 'keh do, main insaanon ke rab ki panah maangta hoon,'),
  ('4e79842fb2fa30a29b4e1839854640d92d428cde37a59a5c3f650493e456d0e6', 'ur', 'The King of mankind,', 'انسانوں کے بادشاہ،'),
  ('556e834fab917af32dbc40dea5c5647f4d49eb4c341861bfc5841c979f484785', 'ur-roman', 'The King of mankind,', 'insaanon ke badshah,'),
  ('dc3d317b266324f635c97b3e567fe01de5a61eef70fb0948ef26dc370158ac78', 'ur', 'The God of mankind,', 'انسانوں کے معبود،'),
  ('9e8f4d304ca35a5506975f9822779644fc26bac6b6561b7e7ff284822ebe3a95', 'ur-roman', 'The God of mankind,', 'insaanon ke mabood,'),
  ('85f41e8e15f00c099dfe6890d560fca705c5b9df45d03c487e33a8cd35f88f9b', 'ur', 'From the evil of the retreating whisperer,', 'اُس وسوسہ ڈالنے والے کے شر سے جو پیچھے ہٹ جاتا ہے،'),
  ('a1d03e2dceafffcc008d9bd4f32cd1e27b6cbc59f4939616970f5506aaa32939', 'ur-roman', 'From the evil of the retreating whisperer,', 'us waswasa daalne wale ke shar se jo peeche hat jata hai,'),
  ('571a2b2af7648a714ff751b02e9a9750ce2cf17bbcb4fdfb99664101e0bd9c04', 'ur', 'Who whispers in the breasts of mankind,', 'جو انسانوں کے سینوں میں وسوسہ ڈالتا ہے،'),
  ('fa6c53d41ee176c5537db86877771dac7565c02fc4edd5a765d0e52dd6e2e90e', 'ur-roman', 'Who whispers in the breasts of mankind,', 'jo insaanon ke seenon me waswasa daalta hai,'),
  ('b40be7fb9ff2fd69f33c35d93b5a4f196bca232cfd096485d8b7b46f5bc1c814', 'ur', 'From among jinn and mankind.', 'خواہ وہ جنوں میں سے ہو یا انسانوں میں سے۔'),
  ('e16308a5726f575ca698719b3135c933d0ba6673784b8ce640e307ad2af403df', 'ur-roman', 'From among jinn and mankind.', 'khwah wo jinnon me se ho ya insaanon me se.'),
  ('0fc3c8e4c0a43dee9893c5d7bf610017ecd6c5198a49dffb511309021b910502', 'ur', 'Indeed, We have granted you al-Kawthar.', 'بے شک ہم نے آپ کو کوثر عطا کی۔'),
  ('34341371ce0b7d7d47a39a64611ea30951d39899382b2a7adc9a7fdd3b0a38c6', 'ur-roman', 'Indeed, We have granted you al-Kawthar.', 'be-shak hum ne aap ko Kawthar ata ki.'),
  ('286e0edfbd144f41468e83232d0cfd8f7dbf5e4c5e27f8ecc8da7713bbcccc6c', 'ur', 'So pray to your Lord and sacrifice.', 'تو اپنے رب کے لیے نماز پڑھیں اور قربانی کریں۔'),
  ('bbfbfda920cde91a5d8880a0667cb6b70d8c612d3d7627020eb29a84b5f19df6', 'ur-roman', 'So pray to your Lord and sacrifice.', 'to apne rab ke liye namaz padhein aur qurbani karein.'),
  ('c0a8f5f37b63057270e4bde4494b63716e157d5d31a38963c3adcf7387d3a8b7', 'ur', 'Indeed, your enemy is the one cut off.', 'بے شک آپ کا دشمن ہی بے نام و نشان ہے۔'),
  ('38dac883b143baf701c6b3368ddf168ed33205dff45eafc3c33a0b6c15010d0c', 'ur-roman', 'Indeed, your enemy is the one cut off.', 'be-shak aap ka dushman hi be-naam o nishaan hai.'),
  ('34d8c8c7cf62199e0866fe1761bb522db762a53495d5283d649a46081c7eab09', 'ur', 'Have you not seen how your Lord dealt with the companions of the elephant?', 'کیا آپ نے نہیں دیکھا کہ آپ کے رب نے ہاتھی والوں کے ساتھ کیا کیا؟'),
  ('82f2180ffdf3cdd053b7639debf9b82af4b7bc369de32e8e26d99207ea17f327', 'ur-roman', 'Have you not seen how your Lord dealt with the companions of the elephant?', 'kya aap ne nahin dekha ke aap ke rab ne haathi walon ke saath kya kiya?'),
  ('d8a89fd7ab271f056a44c233fb0653a7eda9858f8c45c7c11d8b2111449c3e4a', 'ur', 'Did He not make their plan go astray?', 'کیا اس نے ان کی چال کو ناکام نہیں بنایا؟'),
  ('df7ec990a09ebe9dab092279d9d24f021033a79c477724c80df66ce4788bf5a1', 'ur-roman', 'Did He not make their plan go astray?', 'kya us ne un ki chaal ko nakaam nahin banaya?'),
  ('8a31d79f1ba69afb34600049c6ccc78bc8d5a108c64e367b84fa1c9b4c671af1', 'ur', 'And He sent against them birds in flocks,', 'اور ان پر جھنڈ کے جھنڈ پرندے بھیجے،'),
  ('011929bdbcb4c3dea231a18680ef0123a522f553542714155b18b3a56efc50c5', 'ur-roman', 'And He sent against them birds in flocks,', 'aur un par jhund ke jhund parinde bheje,'),
  ('139cfb58d5ba31114cbfe3574d7ad1bf282e018358e774cdf11373ca41566097', 'ur', 'Striking them with stones of hard clay,', 'جو ان پر کنکر کے پتھر مار رہے تھے،'),
  ('e563236d2e538cf241356b8cc6bcc3cec1d19767d396bf0a7a59c7fa5731b386', 'ur-roman', 'Striking them with stones of hard clay,', 'jo un par kankar ke patthar maar rahe the,'),
  ('0794e66b9f20cce38c1e4f2b15e85e90237ad1415a1d9c60ba3ddae56f0b6ef0', 'ur', 'And made them like eaten straw.', 'پھر انہیں کھائے ہوئے بھوسے کی طرح کر دیا۔'),
  ('6ca1831cf77b1f7bf7fbd6ad5720fdbb3324489b98286d9d15c2798971e80737', 'ur-roman', 'And made them like eaten straw.', 'phir unhein khaye hue bhoose ki tarah kar diya.'),
  ('fe1eafeab37029fbd22380bb9480b99b03dae8d13657eaf0de0998a256c6bcc3', 'ur', 'For the accustomed security of the Quraysh,', 'قریش کو مانوس کر دینے کی وجہ سے،'),
  ('2fe357450d8e044b4167cbfe9de194e5f25278a452ea1b248feb305dc71f861f', 'ur-roman', 'For the accustomed security of the Quraysh,', 'Quraysh ko maanoos kar dene ki wajah se,'),
  ('b0ee1782b176a749f798aed6dc04ae9aa570acefc477cb06b7f62a80d2c60d4a', 'ur', 'Their accustomed security in the caravans of winter and summer,', 'انہیں سردی اور گرمی کے سفروں سے مانوس کر دینے کی وجہ سے،'),
  ('03ad671356b134c69d18d59e635fa0bff818ac35e2b863cf7d98c5480e9fe715', 'ur-roman', 'Their accustomed security in the caravans of winter and summer,', 'unhein sardi aur garmi ke safron se maanoos kar dene ki wajah se,'),
  ('4319aa9de7d78cd91a4d8db63a77b90f1e631053b8cfdf05d5cfc4079f45b326', 'ur', 'Let them worship the Lord of this House,', 'تو انہیں اس گھر (کعبہ) کے رب کی عبادت کرنی چاہیے،'),
  ('835fa28796536dc572d439895bffb87705bdf3d34116a9559b8ea7a153171bff', 'ur-roman', 'Let them worship the Lord of this House,', 'to unhein is ghar (Kaaba) ke rab ki ibadat karni chahiye,'),
  ('42c46d38d87642a2658989da4e66a0c2601799d15491113d337a58db73171b4e', 'ur', 'Who has fed them against hunger and made them safe from fear.', 'جس نے انہیں بھوک میں کھانا دیا اور خوف سے امن بخشا۔'),
  ('4692738e37bdf1872fd0c6d537a1a9d01a2e0aa0258b0fc7860cdbf260f7e020', 'ur-roman', 'Who has fed them against hunger and made them safe from fear.', 'jis ne unhein bhook me khana diya aur khauf se aman bakhsha.'),
  ('aa3bd74ab0847aa78401d2c55dd9ca193706d2ffe7e47e95a249da4943613456', 'ur', 'Have you seen the one who denies the Recompense?', 'کیا آپ نے اسے دیکھا جو بدلے (کے دن) کو جھٹلاتا ہے؟'),
  ('1a0774148bb08c8496ccddc67e2ad599b6f74fb7afc2b0bdf92929b6808e7446', 'ur-roman', 'Have you seen the one who denies the Recompense?', 'kya aap ne use dekha jo badle (ke din) ko jhutlata hai?'),
  ('a511a447ba5f9c834554b8f2b579491578f6b55f3e6106f02236d31324455e19', 'ur', 'That is the one who repels the orphan,', 'یہ وہی ہے جو یتیم کو دھکے دیتا ہے،'),
  ('ea12f3a7b903eb50d826d2ec5e96aaaa751f8b3f2ac8e0ae1bff91dadddb5a97', 'ur-roman', 'That is the one who repels the orphan,', 'yeh wohi hai jo yateem ko dhakke deta hai,'),
  ('a4a43af3e4d1838b09920418c2fb14f20acda0d3e4ab5ac2643c62ede339901f', 'ur', 'And does not encourage feeding the poor.', 'اور مسکین کو کھانا کھلانے کی ترغیب نہیں دیتا۔'),
  ('5f6d3466a90cf617e8c473f122a0d0f38097b994e52a8e9901831968c6e4ed87', 'ur-roman', 'And does not encourage feeding the poor.', 'aur miskeen ko khana khilane ki targheeb nahin deta.'),
  ('1d21ee4b36e08d04593748ef40054992fd5caeb179ff048fcd90580a92f019b9', 'ur', 'So woe to those who pray,', 'تو خرابی ہے ان نمازیوں کے لیے،'),
  ('c593ca5d9087cfedf7944cc17c92e9d0c8298abac783bc5bc62907ca1b7f00f2', 'ur-roman', 'So woe to those who pray,', 'to kharabi hai un namaziyon ke liye,'),
  ('fd5d8a7b12f28847059555eb7f068e533c75eb46bd91307c45dd581cb2bd0642', 'ur', 'Who are heedless of their prayer,', 'جو اپنی نماز سے غافل ہیں،'),
  ('819431b849ffc969fe23ea6cb2d424aa241d9a29d8afe5390e3be253312d2187', 'ur-roman', 'Who are heedless of their prayer,', 'jo apni namaz se ghafil hain,'),
  ('c51354dd540473defd3ad72f1b4e2a9ed33d383e937209abe9eb729cd5708353', 'ur', 'Those who make show [of their deeds],', 'جو دکھاوا کرتے ہیں،'),
  ('065ff4eb86591c2dbfe979bae3c9c98e977f4ce823164226cac7fe6776fbe522', 'ur-roman', 'Those who make show [of their deeds],', 'jo dikhawa karte hain,'),
  ('8a66c37ac87019ff6bdede2a9eea92448ba4d69c942b9b6edcca7189dff8313d', 'ur', 'And withhold simple assistance.', 'اور معمولی برتنے کی چیزیں بھی روکتے ہیں۔'),
  ('c49d778ee2a194a56c26b4c3d9ba4db55cc3843d15eaa09d50cf9b484d7c74c1', 'ur-roman', 'And withhold simple assistance.', 'aur mamooli baratne ki cheezein bhi rokte hain.'),
  ('fa9894d170452ed08d2f8a9bb1f63bb49f5f1d0af3d80a91c3309b8bb9f40568', 'ur', 'Say, O disbelievers,', 'کہہ دو، اے کافرو،'),
  ('57fe6f5155ca48f48d51b31b7602a6a6121f99d92f018bdde7aa403540fc5c9a', 'ur-roman', 'Say, O disbelievers,', 'keh do, aye kafiro,'),
  ('10b97dfe4957675633a191c5d851c93c974ee0723521ac954c6d9716834ce9f1', 'ur', 'I do not worship what you worship,', 'میں اس کی عبادت نہیں کرتا جس کی تم عبادت کرتے ہو،'),
  ('7c518ecca422768dfb6335a746967de8afafa6d63c9f3c1980093b407154f307', 'ur-roman', 'I do not worship what you worship,', 'main us ki ibadat nahin karta jis ki tum ibadat karte ho,'),
  ('74c088e0d6d4318c499283fae427039b91f562be9c9ac673411fc7aad3e7cde3', 'ur', 'Nor are you worshippers of what I worship.', 'اور نہ تم اس کی عبادت کرنے والے ہو جس کی میں عبادت کرتا ہوں۔'),
  ('486f13e6f4f11078687650d052dde3aa9988c02b907a65bac98960f87e2f863e', 'ur-roman', 'Nor are you worshippers of what I worship.', 'aur na tum us ki ibadat karne wale ho jis ki main ibadat karta hoon.'),
  ('9850bd0054e2a6a4398b87e009cc38e705b4ed9f723ef69525eb913fc6bc6a4f', 'ur', 'Nor will I be a worshipper of what you worship,', 'اور نہ میں اس کی عبادت کرنے والا ہوں جس کی تم نے عبادت کی،'),
  ('617766a43bd4c059fb5c3e2b064b8f267e14c474002c0dc0ba23dba39d719d65', 'ur-roman', 'Nor will I be a worshipper of what you worship,', 'aur na main us ki ibadat karne wala hoon jis ki tum ne ibadat ki,'),
  ('a9ce6d8183699870a89d532746d81797647e25088492319faa206c9bde0806a5', 'ur', 'Nor will you be worshippers of what I worship.', 'اور نہ تم اس کی عبادت کرنے والے ہو جس کی میں عبادت کرتا ہوں۔'),
  ('4517923a8f2ed8755f1372c73abc215ed2862273cff0248be1216a6677ebb4fb', 'ur-roman', 'Nor will you be worshippers of what I worship.', 'aur na tum us ki ibadat karne wale ho jis ki main ibadat karta hoon.'),
  ('b0dd82e1b0601149cdcecbbe4ad880b21e20918d202c4e4f9859b1425370d1f8', 'ur', 'For you is your religion, and for me is my religion.', 'تمہارے لیے تمہارا دین اور میرے لیے میرا دین۔'),
  ('d4c1d8b0fc298bb48e79ec2e1fedcfacde20dfa64834cb01d41981f02426b8cd', 'ur-roman', 'For you is your religion, and for me is my religion.', 'tumhare liye tumhara deen aur mere liye mera deen.'),
  ('95a6d1507d4ec92e46a701129ebe1888b8880978b891abb8270ce799d391247b', 'ur', 'When the victory of Allah has come and the conquest,', 'جب اللہ کی مدد اور فتح آ جائے،'),
  ('edad72f3442fe68af76b3a27b52b235f85acc7ab52abce76dbc9cd0d3f12714c', 'ur-roman', 'When the victory of Allah has come and the conquest,', 'jab Allah ki madad aur fatah aa jaye,'),
  ('55310e486b48312b1a722ab4095c690772afaed5248b408ea75d4928e23921e2', 'ur', 'And you see the people entering into the religion of Allah in multitudes,', 'اور آپ لوگوں کو گروہ در گروہ اللہ کے دین میں داخل ہوتے دیکھیں،'),
  ('4737e9209df55ba9a676cb63c63135638c37643c6966ca10e23a2009a392031a', 'ur-roman', 'And you see the people entering into the religion of Allah in multitudes,', 'aur aap logon ko giroh dar giroh Allah ke deen me dakhil hote dekhein,'),
  ('16bde75b6d4a0a04222b3fd3e682694cbf1199a03bf75a70f0763d0f17f017bb', 'ur', 'Then exalt with praise of your Lord and ask His forgiveness. Indeed, He is ever Accepting of repentance.', 'تو اپنے رب کی حمد کے ساتھ تسبیح کریں اور اس سے مغفرت مانگیں۔ بے شک وہ بہت توبہ قبول کرنے والا ہے۔'),
  ('f1d71615cf05aef017bce66cf0cd0b333c23d10531bbdabe97e71a6bb10d5930', 'ur-roman', 'Then exalt with praise of your Lord and ask His forgiveness. Indeed, He is ever Accepting of repentance.', 'to apne rab ki hamd ke saath tasbeeh karein aur us se maghfirat maangein. be-shak wo bahut tauba qabool karne wala hai.'),
  ('f83c163882307f9a9e9a94c879f2b14fdbddf22833a44f953eab4035ef22b886', 'ur', 'May the hands of Abu Lahab be ruined, and ruined is he.', 'ابو لہب کے دونوں ہاتھ ٹوٹ جائیں، اور وہ ہلاک ہو۔'),
  ('a331a9c5880e8b678eb2aa0a47ad8f52f91ffa336fb3084604800936df597540', 'ur-roman', 'May the hands of Abu Lahab be ruined, and ruined is he.', 'Abu Lahab ke dono haath toot jayein, aur wo halaak ho.'),
  ('d734c344a5b31e78c2330c440b6c85361542af032f37f9359380752f09d19912', 'ur', 'His wealth will not avail him, nor that which he gained.', 'اس کا مال اور جو کچھ اس نے کمایا، اس کے کام نہ آیا۔'),
  ('37cc023d3310f02ee336f6160d6b06d54736112048473d4f15570db9440b821c', 'ur-roman', 'His wealth will not avail him, nor that which he gained.', 'us ka maal aur jo kuch us ne kamaya, us ke kaam na aaya.'),
  ('d6cc9a53778314ab10f3c56b7607bbdfddaa6fe1e68a7fa952ecee322499dc99', 'ur', 'He will burn in a Fire of blazing flame,', 'وہ عنقریب بھڑکتی ہوئی آگ میں داخل ہوگا،'),
  ('70bf7c9894660eeabdde0e51635670a240faf31f68a21583b4e53158f623c56e', 'ur-roman', 'He will burn in a Fire of blazing flame,', 'wo anqareeb bhadakti hui aag me dakhil hoga,'),
  ('67bd43e1cb88769ce67c145921478e6d7c93c21c50983fdfdb73dfac7a21bc63', 'ur', 'And his wife, the carrier of firewood,', 'اور اس کی بیوی بھی، جو لکڑیاں ڈھونے والی ہے،'),
  ('df1e5dd955c387b0644bac12ea759864fe09bd3545335b5d421cb77acbefa5ee', 'ur-roman', 'And his wife, the carrier of firewood,', 'aur us ki biwi bhi, jo lakdiyan dhone wali hai,'),
  ('19704279d98109af77c3935b0ec91f8e173189bf516154f1ba38b483d84816c5', 'ur', 'Around her neck a rope of twisted fibre.', 'اس کی گردن میں بٹی ہوئی رسی ہوگی۔'),
  ('908690049cec9941c6e84ec3f146b6369dcbda19078d41729f7a53cdfc6c0684', 'ur-roman', 'Around her neck a rope of twisted fibre.', 'us ki gardan me bati hui rassi hogi.'),
  ('71f44c43a609af4aa98768379a4b01a186b8d0d9cb893621d8eb74e7a1bf8ff7', 'ur', 'Home', 'ہوم'),
  ('48ebf0f9c856479e4d85394ec2e314e17baa8204a56985a25e4118a240873dc0', 'ur-roman', 'Home', 'Home'),
